local config = {
  ui_story_5089_50890100_1_dialog_content = "う～ん、いい天気！\n1人で皓津を歩くなんて久しぶりだ。いい気分だなぁ。",
  ui_story_5089_50890100_2_dialog_content = "でもさっきからジロジロ見られていような…",
