  ui_story_5089_50890100_7_dialog_content = "使者様は干し豆腐の鶏がらスープ煮込みがお好きとか。\n実はうちの看板メニューでして、ささやかではございますが、どうぞお召し上がりください。",
  ui_story_5089_50890100_8_dialog_content = "お口に合ったのなら、またぜひお声がけください。\nすぐにお届けに上がります。",
  ui_story_5089_50890100_9_dialog_content = "え？干し豆腐の鶏がらスープ煮込み…？\nあ、ちょっと待ってください！いきなり食べてって言われても…",
  ui_story_5089_50890100_10_dialog_content = "おお、あなたが使者様でしたか！お会いできて光栄です！\n私は沿海地域で絹織物の商いをしております。",
  ui_story_5089_50890100_11_dialog_content = "おい！とっておきの「双鳳五福八吉祥錦」を店から持ってきてくれ。\n使者様に差し上げるんだ。",
  ui_story_5089_50890100_12_dialog_content = "い、いや、そんな…もらえません！",
  ui_story_5089_50890100_13_dialog_content = "使者様、主があちらの店に宴席を設けましたので、\nどうぞお越しくださいませ。",
