  ui_story_5089_50890100_40_dialog_content = "ホホホ、分かっておる。",
  ui_story_5089_50890100_41_dialog_content = "PlayerNameは異邦の使者というだけじゃのうて、\n今や済の国を救うた英雄じゃからのう。",
  ui_story_5089_50890100_42_dialog_content = "そこに「お世継ぎにアストラ大陸の使者と婚姻の意あり」との噂までささやかれれば、\nそりゃあ皓津じゅうが騒がしくなるよのう。",
  ui_story_5089_50890100_43_dialog_content = "済の国は商人（あきんど）の国ゆえ、\n皆が先を争ってお主に近づこうとするのも分からぬことではない。",
  ui_story_5089_50890100_44_dialog_content = "皓津じゅうにそんな突拍子もないウワサが広まってるの！？何で誰も疑わないの？",
