  ui_story_5089_50890100_47_dialog_content = "いっそお世継ぎの意に添うてみてはどうかのう？",
  ui_story_5089_50890100_48_dialog_content = "いささかやんちゃではあるが、純粋な心の持ち主じゃ。\n春新節にPlayerNameが見せた勇姿を今でも称賛してやまぬしのう。",
  ui_story_5089_50890100_49_dialog_content = "お世継ぎの伴侶として王宮に入れば、商人らも大人しく引き下がるしかあるまい。",
  ui_story_5089_50890100_50_dialog_content = "…タンドウは僕をからかいに来たの？",
  ui_story_5089_50890100_51_dialog_content = "おや、PlayerNameの目には、\nわらわはさような人物に写っておるのかのう？",
  ui_story_5089_50890100_52_dialog_content = "いや、そういうわけじゃないけど…",
