  ui_story_5089_50890100_55_dialog_content = "はい。",
  ui_story_5089_50890100_56_dialog_content = "うわっ、キュウ！い…いたんだ。まったく気づかなかった。",
  ui_story_5089_50890100_57_dialog_content = "殿下はこれから使者様と大事なお話がございます。\n私が控えていますゆえ、皆さんはお下がり願います。",
  ui_story_5089_50890100_58_dialog_content = "はい。",
  ui_story_5089_50890100_59_dialog_content = "お茶をお淹れします。",
  ui_story_5089_50890100_60_dialog_content = "あ、大丈夫だよ。僕がやるから――",
  ui_story_5089_50890100_61_dialog_content = "宮中から茶菓子を持って参りました。どうぞお召し上がりください。\n他にお申し付けがなければ、私はこれにて。",
  ui_story_5089_50890100_62_dialog_content = "え？キュウは一緒に食べないの？",
  ui_story_5089_50890100_63_dialog_content = "PlayerNameの誘いじゃ。お主も座るがよい。",
  ui_story_5089_50890100_64_dialog_content = "…いいえ、それは礼に反します。\n私は外に控えております。御用の際はお呼びください。",
  ui_story_5089_50890100_65_dialog_content = "…",
  ui_story_5089_50890100_66_dialog_content = "…ケンカでもしたの？",
  ui_story_5089_50890100_67_dialog_content = "普段から言葉数が少ない方だけど、\n今日は特によそよそしい気がする…",
  ui_story_5089_50890100_68_dialog_content = "喧嘩でもできれば、よいのじゃがのう…",
  ui_story_5089_50890100_69_dialog_content = "？",
  ui_story_5089_50890100_70_dialog_content = "そのことはまたの機会に話すとしよう。\n今日はPlayerNameにいとまを告げに来たのじゃ。",
  ui_story_5089_50890100_71_dialog_content = "いとま…？どこか行くの？",
