  ui_story_5089_50890100_73_dialog_content = "わあ、良かったね！ようやく故郷に帰れるんだね！",
  ui_story_5089_50890100_74_dialog_content = "あ、でも…そんな単純な事でもないのかな…\nだって君は、その…ええと…留学しに来てたんだよね？",
  ui_story_5089_50890100_75_dialog_content = "はっきりと申してよい。\n「人質」と聞いて、わらわが腹を立てると思うたか？",
  ui_story_5089_50890100_76_dialog_content = "ただのう…PlayerNameの申す通りじゃ。\n人質の帰国はそう簡単なことではない。",
  ui_story_5089_50890100_77_dialog_content = "ゆえに済鄴両国は今、表向きには新たな条件の交渉に入っておる。",
  ui_story_5089_50890100_78_dialog_content = "じゃあ裏では？",
  ui_story_5089_50890100_79_dialog_content = "先生が約束してくださったのじゃ。\n済の国がわらわの帰国を阻むことはない。",
  ui_story_5089_50890100_80_dialog_content = "「商人は利を重んずるといえど、恩義に背くことはせぬ」――\n済王殿下がそうおっしゃったそうじゃ。",
  ui_story_5089_50890100_81_dialog_content = "恩義っていうのは…？",
  ui_story_5089_50890100_82_dialog_content = "春新節の動乱の後、宮廷は龍女廟を修繕し、お像の金箔を貼り直した。",
  ui_story_5089_50890100_83_dialog_content = "リン家も再興の一歩を踏み出し、今後大きく栄えることじゃろう。\nPlayerNameも済の国の栄誉国民となり、人々に慕われておる。",
  ui_story_5089_50890100_84_dialog_content = "その恩恵を受けて、わらわまで手厚い褒美を賜ったというわけじゃ。",
  ui_story_5089_50890100_85_dialog_content = "じゃが、功があったにも関わらず、\nなんの褒美ももろうておらぬ者がおるのう。",
  ui_story_5089_50890100_86_dialog_content = "センキョクのことだね…あ、そういえば、\nこのところずっと連絡がつかないんだけど、何か知ってる？",
  ui_story_5089_50890100_87_dialog_content = "今日ここへ来たもう一つの訳がそれじゃ。",
  ui_story_5089_50890100_88_dialog_content = "鄴の国からの便りによれば、春新節の後、\n璇璣卿は鄴王の勅により捕らえられ、獄に入れられたという。",
  ui_story_5089_50890100_89_dialog_content = "国の軍事機密たる武器を無断で用いたことが、\n反逆罪に当たるとのことじゃ。",
  ui_story_5089_50890100_90_dialog_content = "え！？",
  ui_story_5089_50890100_91_dialog_content = "ゆえに明日にでも発とうと思うてのう。",
  ui_story_5089_50890100_92_dialog_content = "一刻でも早う鄴の国へ戻り、事の次第を調べたい。\nさすれば何かしら璇璣卿の力となれるじゃろう。",
  ui_story_5089_50890100_93_dialog_content = "PlayerName――",
  ui_story_5089_50890100_94_dialog_content = "僕も行くよ！",
  ui_story_5089_50890100_95_dialog_content = "よかろう。",
  ui_story_5089_50890100_96_dialog_content = "さっき鄴の国に戻るって聞いた時から、\n一緒に連れて行ってもらおうって考えてたんだ。",
  ui_story_5089_50890100_97_dialog_content = "ただ座って神様のように崇め奉られる…僕はそんなことのために龍州に来たんじゃない。\n本物の神様だって頑張って働いているのに…",
  ui_story_5089_50890100_98_dialog_content = "このまま皓津にいてもやる事はないし、\nそろそろここを去るべきだったんだ。",
  ui_story_5089_50890100_99_dialog_content = "それにセンキョクは僕の友だちでもあるんだ。\n君が嫌だって言っても、何がなんでも付いて行く…って、あれ？…今何て言った？",
  ui_story_5089_50890100_100_dialog_content = "よかろうと申したのじゃ。",
  ui_story_5089_50890100_101_dialog_content = "…僕には関係ないって、てっきり断られるものと思ってた…",
  ui_story_5089_50890100_102_dialog_content = "人は独りでは生きられぬ。\n多くの者に支えられし者は栄え、さもなくば衰える。",
  ui_story_5089_50890100_103_dialog_content = "PlayerName、お主のこの言葉をわらわは片時も忘れたことはないぞ。",
  ui_story_5089_50890100_104_dialog_content = "僕…そんなこと言った？",
  ui_story_5089_50890100_105_dialog_content = "ホホホ。わらわは宮廷に戻り、出立の支度をするとしよう。\nPlayerName、また明日な。",
  ui_story_5089_50890100_106_dialog_content = "僕も荷物をまとめないと…",
  ui_story_5089_50890100_107_dialog_content = "どこぞ行くのか？",
  ui_story_5089_50890100_108_dialog_content = "うわっ！い、いつからいたの？",
  ui_story_5089_50890100_109_dialog_content = "わらわに姿を消してもらわねばと言うてた時からじゃ。",
  ui_story_5089_50890100_110_dialog_content = "…初めからいたってことだね。",
  ui_story_5089_50890100_111_dialog_content = "…だったら聞いてたよね？明日鄴の国へ発つんだ。\nしばらく君とは遊べなくなる。",
  ui_story_5089_50890100_112_dialog_content = "ならば、わらわも行こうかの。\n道を阻む者がおれば、この拳で退治してくれる。",
  ui_story_5089_50890100_113_dialog_content = "「その拳で、天下を鎮める！」",
  ui_story_5089_50890100_114_dialog_content = "いやいやいや…！今の状況は「鎮海の龍女の舞」とはまったく関係ないから！\nどうしてそんなセリフ覚えてるの？",
  ui_story_5089_50890100_115_dialog_content = "構わんじゃろが。人々の語る神やら菩薩やらというのは、\n時と共に変わるものじゃろうて。",
  ui_story_5089_50890100_116_dialog_content = "決めた。わらわも武道を学ぶことにする。",
  ui_story_5089_50890100_117_dialog_content = "そう…でも手加減してね。\nいつも僕が傍にいるわけじゃないんだから、勝手のし過ぎはダメだからね。",
  ui_story_5089_50890100_118_dialog_content = "なんじゃ？PlayerNameは鄴の国に行くのに、わらわが不要なのか？\nそなたが願えば…",
  ui_story_5089_50890100_119_dialog_content = "願い事なんてしたら、友だちじゃないでしょ？",
  ui_story_5089_50890100_120_dialog_content = "…",
  ui_story_5089_50890100_121_dialog_content = "シンゲイとはずっと友だちでいたいんだ。",
  ui_story_5089_50890100_122_dialog_content = "だから、自分の都合で心優しき龍王様の力を借りたくないんだよ。",
  ui_story_5089_50890100_123_dialog_content = "<color=#e8d9bb>シンゲイが突然手を挙げたかと思うと、窓の外から木の葉が1枚飛んできた</color>",
  ui_story_5089_50890100_124_dialog_content = "これは？",
  ui_story_5089_50890100_125_dialog_content = "餞別（せんべつ）じゃ。",
  ui_story_5089_50890100_126_dialog_content = "光霊には、かような習慣があるのじゃろ？",
  ui_story_5089_50890100_127_dialog_content = "戻ったら、また遊ぼうのう。",
  ui_story_5089_50890100_128_dialog_content = "いや、餞別に贈るのは柳の葉だけど…って、シンゲイ？",
  ui_story_5089_50890100_129_dialog_content = "もう行っちゃった…とりあえず、しまっておこう。\n今度押し花でも作ろうっと。",
  ui_story_5089_50890100_130_dialog_content = "僕も皆にあいさつしないと。",
  ui_story_5089_50890100_131_dialog_content = "<color=#e8d9bb>翌日</color>",
  ui_story_5089_50890100_132_dialog_content = "待ち合わせ場所はここでいいんだよね？",
  ui_story_5089_50890100_133_dialog_content = "PlayerName！PlayerName！\nようやく来たか。待ち侘びたぞ。",
  ui_story_5089_50890100_134_dialog_content = "お、お世継ぎ…ど、どうしてここに？\nそれに…その大きな箱は何ですか？",
  ui_story_5089_50890100_135_dialog_content = "見送りに決まっているだろう？\nそしてこれが餞別だ。",
  ui_story_5089_50890100_136_dialog_content = "どれも僕が自ら選んだ宝だぞ。",
  ui_story_5089_50890100_137_dialog_content = "見よ、これは僕が幼き頃に肌身離さず持っていた人形だ。\nこれは祭りの時に作った花提灯…",
  ui_story_5089_50890100_138_dialog_content = "それから…僕の一番好きなおとぎ話の本もあるぞ。\n先生からは読むのを禁止されているゆえ、こっそり人に頼んでようやく手に入れたのだ。",
  ui_story_5089_50890100_139_dialog_content = "それから…タンドウと先生に言われたのだが…",
  ui_story_5089_50890100_140_dialog_content = "そなたの意見も聞かず、許嫁にしてすまなかった。\nさぞかし困惑したであろう？",
  ui_story_5089_50890100_141_dialog_content = "お世継ぎ…",
  ui_story_5089_50890100_142_dialog_content = "PlayerName様、船が出ます。",
  ui_story_5089_50890100_143_dialog_content = "うん、分かった。\n…お世継ぎがわざわざ用意してくれたんです。餞別はいただいていきます。",
  ui_story_5089_50890100_144_dialog_content = "よかった！",
  ui_story_5089_50890100_145_dialog_content = "おい、残りも持ってこい！",
  ui_story_5089_50890100_146_dialog_content = "へ？ええっと…その山のように積み上げられた箱は何ですか？",
  ui_story_5089_50890100_147_dialog_content = "つまらぬオマケだ。\n時間がなく、一箱しか自分で選ぶことができなかった。",
  ui_story_5089_50890100_148_dialog_content = "だが、気持ちは本物だぞ！",
  ui_story_5089_50890100_149_dialog_content = "僕も今や子どもではない。\n世の中を知り、己のやり方がいかに早急だったか分かった。",
  ui_story_5089_50890100_150_dialog_content = "結婚はきちんと「段階」を踏まねばな。",
  ui_story_5089_50890100_151_dialog_content = "…はい？",
  ui_story_5089_50890100_152_dialog_content = "錨を上げろ――",
  ui_story_5089_50890100_153_dialog_content = "出航――",
  ui_story_5089_50890100_154_dialog_content = "<color=#e8d9bb>船がゆっくりと岸を離れ、埠頭で手を振るお世継ぎの高らかな声だけが響いてくる</color>",
  ui_story_5089_50890100_155_dialog_content = "そなたが許嫁になってくれるまで、贈り物を続けるぞ――",
  ui_story_5089_50890100_156_dialog_content = "…",
  ui_story_5089_50890100_157_dialog_content = "皓津を離れることにして正解だったな…",
  ui_story_5089_50890100_158_dialog_content = "お世継ぎはずいぶんとお主に惚れ込んでおるようじゃのう。\nかほどに熱心なお世継ぎはわらわも初めて見るぞ。",
  ui_story_5089_50890100_159_dialog_content = "中身は全部オモチャだとしても、\nこんなにたくさんはもらえないよ…",
  ui_story_5089_50890100_160_dialog_content = "どうしても受け取れぬというのなら、\n鄴の国に着いた後、人に頼んで返せばよかろう。",
  ui_story_5089_50890100_161_dialog_content = "うん、そうするしかなさそうだね。\n今はセンキョクを助けることが先だ。",
  ui_story_5089_50890100_162_dialog_content = "ならば、行こ…いや。",
  ui_story_5089_50890100_163_dialog_content = "鄴の国へ帰るとしよう。",
  ui_story_5089_50890201_1_dialog_content = "PlayerName様、タンドウ殿下。\n下船のご準備をなさってください。",
  ui_story_5089_50890201_2_dialog_content = "さっき済と鄴の国境を越えたばかりだよね。\nもう着いたの？",
  ui_story_5089_50890201_3_dialog_content = "いいや、鄴は中原に位置する国ゆえ、済の国のように水運が発達しておらぬ。\n水路で進めるのはここまでなのじゃ。",
  ui_story_5089_50890201_4_dialog_content = "この埠頭は確か…銅犂村といったのう。",
  ui_story_5089_50890201_5_dialog_content = "さようにございます。村に宿をとりました。\n本日はここで一晩お過ごしください。",
  ui_story_5089_50890201_6_dialog_content = "明日には馬車をご用意いたします。\nこの先は陸路で都へ向かいましょう。",
  ui_story_5089_50890201_7_dialog_content = "ずっと船の上にいたのに、もうそんなに準備してたんだね。",
  ui_story_5089_50890201_8_dialog_content = "船には小舟がございます。\nそれで先に陸に上がり、準備を済ませたにすぎません。",
  ui_story_5089_50890201_9_dialog_content = "此度の帰国は急でしたので、お迎えが間に合わず――",
  ui_story_5089_50890201_10_dialog_content = "宿も粗末なものしかご用意できず、申し訳ございません。\n代わりに周囲の安全はこれまで以上に細心の注意を払い、確保いたします。",
  ui_story_5089_50890201_11_dialog_content = "すぐとは言っても、まだ陸地は見えないんだね。",
  ui_story_5089_50890201_12_dialog_content = "それなのに独りで小舟を漕いで行き来してたなんて…\nどうりで服がビショビショなわけだ。",
  ui_story_5089_50890201_13_dialog_content = "すぐに着替えてきなよ。\nそのままだと風邪引いちゃうよ。",
  ui_story_5089_50890201_14_dialog_content = "ご心配にはおよびません。\n幼い頃より武をたしなんでおります。体は丈夫です。",
  ui_story_5089_50890201_15_dialog_content = "それに旅路の準備ならまだしも、\n己の瑣末事で殿下のおそばを離れるなど、もってのほかでございます。",
  ui_story_5089_50890201_16_dialog_content = "ただ、みすぼらしい姿を御前にさらすのは確かに非礼でございますね。\n殿下の目に触れぬよう影に控えておりましょう。",
  ui_story_5089_50890201_17_dialog_content = "あ、待って！そういう意味じゃ…",
  ui_story_5089_50890201_18_dialog_content = "よいのじゃ、PlayerName。好きにさせておけ。",
  ui_story_5089_50890201_19_dialog_content = "あれでも長く姿を見せていた方じゃ。",
  ui_story_5089_50890201_20_dialog_content = "このところは宮殿でさえ、ろくに姿も見せてくれぬのじゃ。\n先頃も文を片づけようと、ちとうつむいた隙に茶と菓子が用意されておった。",
  ui_story_5089_50890201_21_dialog_content = "ほんのわずかな間、人と話し、戻ってくると、\n部屋がすっかりきれいに掃除されておったこともある。",
  ui_story_5089_50890201_22_dialog_content = "以前にもまして多くの用をこなしているというに、\nまともに姿も見せぬのじゃよ。",
  ui_story_5089_50890201_23_dialog_content = "（なんか、靴屋の小人さんみたい…）",
  ui_story_5089_50890201_24_dialog_content = "君たちの間に何かあったの？",
  ui_story_5089_50890201_25_dialog_content = "…皓津で騒ぎを起こした者どもを覚えておるか？",
  ui_story_5089_50890201_26_dialog_content = "確か「天命を受けし者」って言ってたよね？",
  ui_story_5089_50890201_27_dialog_content = "龍王様の御助けもあり、巡検司は済の国に潜んでおった大勢の\n「天命を受けし者」を捉えることができたのじゃが…",
  ui_story_5089_50890201_28_dialog_content = "うち数十名もの者が済の朝廷で官職に就いておったのじゃ。",
  ui_story_5089_50890201_29_dialog_content = "官位も低く、さして重要な役職ではなかったものの、\n時が遅ければ、かような輩どもが広く張り巡らされた網となり…",
  ui_story_5089_50890201_30_dialog_content = "各方面から王や朝廷に影響を及ぼしていたことじゃろう。\nさすれば、たった一言が国を揺るがすと言うても過言ではない。",
  ui_story_5089_50890201_31_dialog_content = "そうだね…捕まえられて本当によかった。\nこれからは済王様も警戒するだろうし、もう好き勝手はできないね。",
  ui_story_5089_50890201_32_dialog_content = "じゃが、PlayerName…これが済の国だけのことと思うか？",
  ui_story_5089_50890201_33_dialog_content = "それって…",
  ui_story_5089_50890201_34_dialog_content = "皓津で動乱のあった夜、わらわはお主を探しに行こうとしたのじゃが、\n宮殿を出るとすぐに阻まれた。",
  ui_story_5089_50890201_35_dialog_content = "え？そんな話、初めて聞いたよ！？\nケガはなかった？どうして今まで言わなかったの？",
  ui_story_5089_50890201_36_dialog_content = "わらわを阻んだのが鄴の国の密偵だったゆえじゃ。",
  ui_story_5089_50890201_37_dialog_content = "！？",
  ui_story_5089_50890201_38_dialog_content = "兆の国の皇帝陛下はまだ幼く、\n八大諸侯はそれぞれ腹づもりをしておる。",
  ui_story_5089_50890201_39_dialog_content = "互いに密偵を潜ませ、探り合うのは自然なことじゃ。\nかといって公に口に出すわけにはいかぬがのう。",
  ui_story_5089_50890201_40_dialog_content = "鄴の国の密偵はわらわを郡主殿下と敬いはするが、\n奴らが従うのは叔父の命のみじゃ。",
  ui_story_5089_50890201_41_dialog_content = "ならば、奴らがわらわを阻み、天命を受けし者を助けようとしたのも…",
  ui_story_5089_50890201_42_dialog_content = "鄴王様の意志だってこと？",
  ui_story_5089_50890201_43_dialog_content = "…叔父はそう名声が高い方ではなかったが、王位に就きし後は、\n人材を愛し、民を慈しみ、明君と呼ぶにふさわしい王となられた。",
  ui_story_5089_50890201_44_dialog_content = "此度のことは天命を受けし者に惑わされたに違いない。",
  ui_story_5089_50890201_45_dialog_content = "そうだったのか…だから、こんなに急いで出発したんだね。",
  ui_story_5089_50890201_46_dialog_content = "早く出たら、その分、天命を受けし者の監視から逃れられる。\n自由に動く時間を稼げれば、鄴王様に真相を知らせるチャンスもある。",
  ui_story_5089_50890201_47_dialog_content = "そうすれば、僕たちのせいで牢に入れられたセンキョクも助けられるんだね！",
  ui_story_5089_50890201_48_dialog_content = "さすがはPlayerNameじゃ。よく分かっておるのう。",
  ui_story_5089_50890201_49_dialog_content = "でも、それとキュウと何の関係があるの？",
  ui_story_5089_50890201_50_dialog_content = "PlayerNameは知らんかったかのう？",
  ui_story_5089_50890201_51_dialog_content = "キュウは鄴の密偵の頭なのじゃ。",
  ui_story_5089_50890201_52_dialog_content = "え？でもキュウは…タンドウの護衛だよね？",
  ui_story_5089_50890201_53_dialog_content = "キュウはもともと叔父の側近であった。\nわらわが済の国へ向かう直前、護衛に命ぜられたのじゃ。",
  ui_story_5089_50890201_54_dialog_content = "キュウは叔父に恩があってのう。\nいかなることがあろうとも、キュウが叔父の命に背くことはない。",
  ui_story_5089_50890201_55_dialog_content = "それゆえ、わらわを守れと命ぜられれば、\n己の命を捨ててでも役目を果たそうとするのじゃ。",
  ui_story_5089_50890201_56_dialog_content = "叔父がわらわの安否を案じ、近況を報告せよと命じれば、\nいかなる状況下であろうと、キュウは速やかに報告する。",
  ui_story_5089_50890201_57_dialog_content = "それって…",
  ui_story_5089_50890201_58_dialog_content = "ホホホ、叔父のわらわを案ずる気持ちは本物じゃよ。\nまあ監視と言えなくもないがのう。",
  ui_story_5089_50890201_59_dialog_content = "ちょっと待って。ということは…\n僕たちの動きは今も天命を受けし者に伝わってるってこと？キュウは…",
  ui_story_5089_50890201_60_dialog_content = "…いいや。",
  ui_story_5089_50890201_61_dialog_content = "PlayerNameも知っておろう？キュウは決して器用な娘ではない。",
  ui_story_5089_50890201_62_dialog_content = "叔父の命が絶対である一方で、此度われらがなにゆえ帰国するかも重々承知しておる。\nゆえに目も耳も口も塞いでおるのじゃ。",
  ui_story_5089_50890201_63_dialog_content = "必要最低限の護衛に徹し、わらわのそばを離れておれば、\n己の知らぬことゆえ報告もせずに済もう。",
  ui_story_5089_50890201_64_dialog_content = "それがキュウにできる精一杯なのじゃ。",
  ui_story_5089_50890201_65_dialog_content = "それにのう、あの頑ななキュウの心が揺れるのを見て、\n実はちと嬉しいのじゃ。",
  ui_story_5089_50890201_66_dialog_content = "少なくとも…済の国で共に過ごした5年は\n無駄ではなかったようじゃのう。",
  ui_story_5089_50890201_67_dialog_content = "タンドウ。",
  ui_story_5089_50890201_68_dialog_content = "ん？なんじゃ？意地が悪いか？",
  ui_story_5089_50890201_69_dialog_content = "タンドウは…済の国で辛い思いをしたの？",
  ui_story_5089_50890201_70_dialog_content = "…む？",
  ui_story_5089_50890201_71_dialog_content = "あ、ええと…そのつまり…",
  ui_story_5089_50890201_72_dialog_content = "済王様やお世継ぎも、国師さんも皆いい人だけど、\nやっぱり家族じゃないし、済の国も故郷じゃないから…",
  ui_story_5089_50890201_73_dialog_content = "はぁ…",
  ui_story_5089_50890201_74_dialog_content = "え…？どうしてため息つくの？\n何か…ヘンなこと言った？",
  ui_story_5089_50890201_75_dialog_content = "PlayerNameが武将ならば、さぞかし奇襲に長けた将であろうのう。",
  ui_story_5089_50890201_76_dialog_content = "え？急に何の話？",
  ui_story_5089_50890201_77_dialog_content = "しばし失礼するぞ。\n船を降りるとあらば、化粧直しをせねばの。",
  ui_story_5089_50890201_78_dialog_content = "あ、うん…分かった…",
  ui_story_5089_50890201_79_dialog_content = "はぁ…",
  ui_story_5089_50890201_80_dialog_content = "はぁ…",
  ui_story_5089_50890201_81_dialog_content = "腐った木は彫刻に使えない。",
  ui_story_5089_50890201_82_dialog_content = "鉄の木に花は咲かない。",
  ui_story_5089_50890201_83_dialog_content = "「腐った木」ってまさか僕のこと？いや、待って…\n君たちは…タゲンとタゴだよね？どうしてここにいるの？",
  ui_story_5089_50890201_84_dialog_content = "金のウリをくれたら謎に答えてやる！",
  ui_story_5089_50890201_85_dialog_content = "銀のナツメをくれたら疑問に答えてやる！",
  ui_story_5089_50890201_86_dialog_content = "ごめん。残念だけど、そんなもの持ってないよ。",
  ui_story_5089_50890201_87_dialog_content = "お腹が空いたなら、ご主人様の所へ帰りな。どうせテンカンも来てるんでしょ？\n君たちのご主人様って本当に神出鬼没だよね。",
  ui_story_5089_50890201_88_dialog_content = "テンカン、いるんでしょ？",
  ui_story_5089_50890201_89_dialog_content = "ご主人様はいない。",
  ui_story_5089_50890201_90_dialog_content = "水の中に沈んだ。",
  ui_story_5089_50890201_91_dialog_content = "あそこ！",
  ui_story_5089_50890201_92_dialog_content = "…えっ！？",
  ui_story_5089_50890201_93_dialog_content = "ブクブク…た、たす…け…泳げないん…ですぅ…ブクブク…",
  ui_story_5089_50890201_94_dialog_content = "どうして水の中にいるの？…って、そうじゃなくて…",
  ui_story_5089_50890201_95_dialog_content = "助けなきゃ！",
  ui_story_5089_50890202_1_dialog_content = "…くしゅん！",
  ui_story_5089_50890202_2_dialog_content = "はぁ～、ようやく生き返りましたねぇ。",
  ui_story_5089_50890202_3_dialog_content = "どうしてこんな所で溺れてたの？竜宮城に招かれたとか言わないでよ。",
  ui_story_5089_50890202_4_dialog_content = "まあまあ、そう慌てず…話せば長くなる話でしてねぇ。",
  ui_story_5089_50890202_5_dialog_content = "済の国も遊び飽きてしまい、別の所へ行こうと思いましてね。\nただダンナもご存じの通り、僕は懐がそりゃあ寂しくてですねぇ…",
  ui_story_5089_50890202_6_dialog_content = "船に乗れないもんですから、とっかえひっかえ商人の馬車に乗せてもらいながら、\n何とか鄴の国に着いたは着いたんです。ただ…",
  ui_story_5089_50890202_7_dialog_content = "どうなったと思います？\n道を歩いていたら、妖魔に出くわしたんですよ！",
  ui_story_5089_50890202_8_dialog_content = "朝廷が毎年邪気祓いしてるってのに不思議なこともあるもんですねぇ。\n済と鄴の国境も海沿いではないんですが。",
  ui_story_5089_50890202_9_dialog_content = "きっとどこかの山に隠れていた妖魔がお腹を減らして降りてきたんでしょうねぇ。\nまったく運が悪いとしか言いようがありません。",
  ui_story_5089_50890202_10_dialog_content = "そうやって追い回され、逃げてたところ、\nうっかり水に落ちてしまったってわけです。",
  ui_story_5089_50890202_11_dialog_content = "いや～、ダンナは僕の命の恩人です。\nただ、この恩に報えるものを持ち合わせていませんで…",
  ui_story_5089_50890202_12_dialog_content = "どうやら、この身を差し上げるしかなさそうです。",
  ui_story_5089_50890202_13_dialog_content = "遠慮しとくよ！",
  ui_story_5089_50890202_14_dialog_content = "君って本当にいつも遊んでばかりだね。やることないの？",
  ui_story_5089_50890202_15_dialog_content = "おや、僕の名前をお忘れですか？",
  ui_story_5089_50890202_16_dialog_content = "え？テンカンでしょ？",
  ui_story_5089_50890202_17_dialog_content = "その通り！「天下一の閑人」と書いて「テンカン」ですよ。",
  ui_story_5089_50890202_18_dialog_content = "それよりもダンナ、そう慌てて断らないでください。\n出立前にちと占ってみたんですが、水禍に遭遇しつつも富める者の助けが得られると出たんです。",
  ui_story_5089_50890202_19_dialog_content = "で、その「富める者」なんですが…ちと、手を貸してもらえますか？",
  ui_story_5089_50890202_20_dialog_content = "こう？",
  ui_story_5089_50890202_21_dialog_content = "<color=#e8d9bb>カラン</color>",
  ui_story_5089_50890202_22_dialog_content = "…どうして僕の手のひらに出すの？",
  ui_story_5089_50890202_23_dialog_content = "おや、こりゃ大変だ、陰の辰と陰の子ですねぇ。",
  ui_story_5089_50890202_24_dialog_content = "龍が舞い、ネズミが跳ねるってのは本来吉兆なんですがね。\n両方とも陰となると、真の龍は身を潜め、小者が災いを成すといって大災難の兆しなんです。",
  ui_story_5089_50890202_25_dialog_content = "普段の僕であれば、こんな卦が出たらトンズラするところなんですが…\nはてさて命を助けていただいた恩はどう返しましょうかねぇ…",
  ui_story_5089_50890202_26_dialog_content = "ふ～む、仕方がないですねぇ。命をかけてダンナとご一緒しましょう。\n災難を払うお手伝いをして差し上げます。",
  ui_story_5089_50890202_27_dialog_content = "君の話があやしいのはもともとだけど、\nその命の恩人って本当に僕なのかな？",
  ui_story_5089_50890202_28_dialog_content = "何をおっしゃるんです？\nダンナご自身が助けてくださったんですよ？",
  ui_story_5089_50890202_29_dialog_content = "でもさっき「富める者の助けを得られる」って言ってたよね？",
  ui_story_5089_50890202_30_dialog_content = "僕はお世辞にも、今まで生きてきた中で「富」んだことがあるとは言えないんだけど…",
  ui_story_5089_50890202_31_dialog_content = "おかしいですねぇ。卦象を見る限り、\nダンナは国をも動かす富を持っているはずなんですが。",
  ui_story_5089_50890202_32_dialog_content = "えぇ？それって夢でも見たんじゃないの？",
  ui_story_5089_50890202_33_dialog_content = "PlayerName様、船が着岸いたしました。お降りください。\nお荷物は後ほど船員が運びます。",
  ui_story_5089_50890202_34_dialog_content = "おや、ではさっそく恩返しの手始めにお手伝いしましょう。\nこの箱は僕にお任せ…",
  ui_story_5089_50890202_35_dialog_content = "おや、こりゃずいぶんと…",
  ui_story_5089_50890202_36_dialog_content = "<color=#e8d9bb>ドン！</color>",
  ui_story_5089_50890202_37_dialog_content = "<color=#e8d9bb>落下の衝撃で箱のふたが開き、目にもまぶしい金色の光が見えた</color>",
  ui_story_5089_50890202_38_dialog_content = "PlayerName、船を降り…",
  ui_story_5089_50890202_39_dialog_content = "…",
  ui_story_5089_50890202_40_dialog_content = "…",
  ui_story_5089_50890202_41_dialog_content = "…",
  ui_story_5089_50890202_42_dialog_content = "こ、壊れてませんよね！？壊れたりしたら、\n僕には身売りしようが何をしようが、弁償できませんよ！",
  ui_story_5089_50890202_43_dialog_content = "タンドウ、テンカン…僕、なんか目がおかしくなったみたい…",
  ui_story_5089_50890202_44_dialog_content = "お世継ぎがくれた箱の中…き、金が入ってた…？\nはは…あはははは…",
  ui_story_5089_50890202_45_dialog_content = "…キュウ。",
  ui_story_5089_50890202_46_dialog_content = "<color=#e8d9bb>タンドウの声と共にキュウが姿を現し、指示を待つことなく、\n素早くすべての箱を調べ終えた</color>",
  ui_story_5089_50890202_47_dialog_content = "殿下、すべて調べました。おもちゃの入った箱2つと\n宝石の入った小箱の他はすべて金が収められておりました。",
  ui_story_5089_50890301_1_dialog_content = "ずいぶん歩いたけど、まだ着かないの？\n今日の宿って埠頭からこんなに遠かったんだ…",
  ui_story_5089_50890301_2_dialog_content = "何をおっしゃるんです？財宝の神をお迎えになった後、\nよからぬ輩に襲われないよう裏通りを進みたいっておっしゃったのはダンナですよ。",
  ui_story_5089_50890301_3_dialog_content = "だって当たり前でしょ？後で全部返さなきゃなんだし、\n誰だって急にこんなたくさんの金を持たされたら慎重になるよ。",
  ui_story_5089_50890301_4_dialog_content = "お世継ぎは「つまらぬオマケ」だって言ってたのに…",
  ui_story_5089_50890301_5_dialog_content = "済の国のお世継ぎともなれば、\n金銀財宝など「つまらぬもの」かもしれぬのう。",
  ui_story_5089_50890301_6_dialog_content = "じゃが、他の者にとっては…少なくとも鄴の国では、\nかほどの金があれば、町を丸ごと1つ買うても有り余るじゃろう。",
  ui_story_5089_50890301_7_dialog_content = "とはいえPlayerName、恐れずともよい。\nキュウがおるゆえ、並みの賊は近づけぬ。",
  ui_story_5089_50890301_8_dialog_content = "まもなくでございます。\n突き当りが今宵の宿でございます。",
  ui_story_5089_50890301_9_dialog_content = "はぁ、やっと休めるね…船を降りてからずっと気が気じゃなくって…\nあれ？タンドウ、どうしたの？",
  ui_story_5089_50890301_10_dialog_content = "何でもない。かつて済の国へ向かう際、\nここを通ったことを思い出してのう。",
  ui_story_5089_50890301_11_dialog_content = "銅犂村は鄴と済の国境にある最大の穀物産地じゃ。\n都市には及ばぬが、埠頭もあり、栄えておった。",
  ui_story_5089_50890301_12_dialog_content = "それが久方ぶりに訪れてみると…\n何だかさびれてしもうたのう。",
  ui_story_5089_50890301_13_dialog_content = "おや、お嬢さんは長いこと村を離れていたのかね？",
  ui_story_5089_50890301_14_dialog_content = "はい、ここ数年何があったか教えていただけますか？",
  ui_story_5089_50890301_15_dialog_content = "教えるも何も、この辺のもんなら皆知っとることじゃよ。",
  ui_story_5089_50890301_16_dialog_content = "ここ数年で街に大きな工房が次々とできてねぇ。\n賃金がいいもんだから、若いモンはみんな出て行っちまった。",
  ui_story_5089_50890301_17_dialog_content = "わしも若けりゃ、雨風の心配がないところで働きたいもんじゃよ。",
  ui_story_5089_50890301_18_dialog_content = "そうでしたか。\nところで、そのお米は今いくらで売ってらっしゃるのですか？",
  ui_story_5089_50890301_19_dialog_content = "おや、お嬢さん、米がほしいのかい？ここ2か月ほど上がりっぱなしでねぇ。\n今日もまた上がって、この値じゃよ――",
  ui_story_5089_50890301_20_dialog_content = "…分かりました。ありがとうございます。",
  ui_story_5089_50890301_21_dialog_content = "あのお米、何か問題でもあるの？",
  ui_story_5089_50890301_22_dialog_content = "皓津にいる時、興味本位でお米の値段を聞いてみたのじゃが、\n同じくらいの値段だったんじゃ。特に問題ないと思うが…",
  ui_story_5089_50890301_23_dialog_content = "この小さな村で、兆でも一二を争う大都市皓津と米が同じ値とは…",
  ui_story_5089_50890301_24_dialog_content = "明らかに大問題じゃ…じゃが、なにゆえ…",
  ui_story_5089_50890301_25_dialog_content = "<color=#e8d9bb>ドンッ</color>",
  ui_story_5089_50890301_26_dialog_content = "あ、すみません。大丈夫ですか…あれ？\n君が抱えてるのって…",
  ui_story_5089_50890301_27_dialog_content = "…！",
  ui_story_5089_50890301_28_dialog_content = "お客様！は、早く…その子を捕まえてください！",
  ui_story_5089_50890301_29_dialog_content = "お客様の荷物が…！",
  ui_story_5089_50890301_30_dialog_content = "！",
  ui_story_5089_50890301_31_dialog_content = "――！",
  ui_story_5089_50890301_32_dialog_content = "捕まえました。",
  ui_story_5089_50890301_33_dialog_content = "はなせ！は…はなせってば！ガブッ！",
  ui_story_5089_50890301_34_dialog_content = "<color=#e8d9bb>少年はキュウの手に力一杯咬みついたが、\nキュウはいっさい動じず、表情一つ変えなかった</color>",
  ui_story_5089_50890301_35_dialog_content = "返しなさい。",
  ui_story_5089_50890301_36_dialog_content = "<color=#e8d9bb>少年は目を血走らせ、さらに力一杯咬みついた</color>",
  ui_story_5089_50890301_37_dialog_content = "キュウ！",
  ui_story_5089_50890301_38_dialog_content = "<color=#e8d9bb>ほんの少し気を逸らせた隙に、\n少年は魚のようにするりとキュウの手からすり抜けた</color>",
  ui_story_5089_50890301_39_dialog_content = "べ～っだ！",
  ui_story_5089_50890301_40_dialog_content = "ちょっと、君――",
  ui_story_5089_50890301_41_dialog_content = "たすけて！誰か、たすけて！人さらいにつかまっちゃうよぉ！",
  ui_story_5089_50890301_42_dialog_content = "なんだって！？真昼間からなんてことだ！",
  ui_story_5089_50890301_43_dialog_content = "おかしな格好しやがって、明らかにあやしいぞ！",
  ui_story_5089_50890301_44_dialog_content = "捕まえろ！御上に引き渡せ！",
  ui_story_5089_50890301_45_dialog_content = "おや、いったいどうしたってんです？そう慌てなさんなって。\n僕たちは怪しいもんじゃありません。話せば分かります。",
  ui_story_5089_50890301_46_dialog_content = "お前が一番あやしいじゃないか！",
  ui_story_5089_50890301_47_dialog_content = "ダメだ、人が多すぎるよ。逃げられちゃう…",
  ui_story_5089_50890301_48_dialog_content = "殿下に近寄るな！",
  ui_story_5089_50890301_49_dialog_content = "キュウ、わらわのことは構わずともよい。\n皆ごく普通の村人じゃ。",
  ui_story_5089_50890301_50_dialog_content = "しかし万が一…",
  ui_story_5089_50890301_51_dialog_content = "お主は機敏じゃ。PlayerNameと共にさきの少年を探しに行け。\nここはわらわに任せよ。",
  ui_story_5089_50890301_52_dialog_content = "その御命令は承知いたしかねます。\n殿下をお守りするのが私の務めにございます。",
  ui_story_5089_50890301_53_dialog_content = "これは命令じゃ。",
  ui_story_5089_50890301_54_dialog_content = "…承知いたしました。",
  ui_story_5089_50890301_55_dialog_content = "PlayerName様、しっかりついてきてください。",
  ui_story_5089_50890301_56_dialog_content = "あの子…あっという間に姿が見えなくなっちゃったね。",
  ui_story_5089_50890301_57_dialog_content = "はぁ…箱の中身を見た時から、こうなる気がしてたんだ。",
  ui_story_5089_50890301_58_dialog_content = "でも、まさか子どもが…",
  ui_story_5089_50890301_59_dialog_content = "ボロボロの服を着てたし、何が事情があるのかも。",
  ui_story_5089_50890301_60_dialog_content = "…",
  ui_story_5089_50890301_61_dialog_content = "僕とも必要最低限しか話さないつもり？",
  ui_story_5089_50890301_62_dialog_content = "…",
  ui_story_5089_50890301_63_dialog_content = "僕はよそ者で、龍州のことはよく知らない。\n君たちが今どんな状況に置かれてるのかも、よく分からない…",
  ui_story_5089_50890301_64_dialog_content = "でも僕はこれまで色々な人と出会ってきたんだよ。",
  ui_story_5089_50890301_65_dialog_content = "信念にすべてを捧げて、黎明の光になろうとする人もいれば――",
  ui_story_5089_50890301_66_dialog_content = "自分の夢をかなえるため、暗闇の深淵に堕ちることさえいとわない人もいる。",
  ui_story_5089_50890301_67_dialog_content = "何が正しくて、何が間違ってるとか言いたいわけじゃないんだ。\nそもそも僕に他人をとやかく言う資格はない。ただ…",
  ui_story_5089_50890301_68_dialog_content = "何もしなければ、何も得られないし、\n何も変えられないと思うんだ。",
  ui_story_5089_50890301_69_dialog_content = "私は鄴王麾下の剣客であり、タンドウ殿下の護衛です。",
  ui_story_5089_50890301_70_dialog_content = "命令に従い、その責を全うすることが私の務めです。",
  ui_story_5089_50890301_71_dialog_content = "何かを変える必要はありません。",
  ui_story_5089_50890301_72_dialog_content = "じゃあ一つ質問させて。\nもし鄴王殿下とタンドウがまったく逆の命令を下したとしたら、どうする？",
  ui_story_5089_50890301_73_dialog_content = "…鄴王殿下も郡主殿下も共に天下を思い、\n鄴の国のために尽くしていらっしゃいます。",
  ui_story_5089_50890301_74_dialog_content = "その答えじゃ、誰も納得しないと思うな。",
  ui_story_5089_50890301_75_dialog_content = "私は…",
  ui_story_5089_50890301_76_dialog_content = "全然見つからないね。感知してみよう。",
  ui_story_5089_50890301_77_dialog_content = "感知。",
  ui_story_5089_50890301_78_dialog_content = "見つけた。南の路地だ…あれ？",
  ui_story_5089_50890301_79_dialog_content = "あっかんべ～！",
  ui_story_5089_50890301_80_dialog_content = "え？…なんなの、この子…",
  ui_story_5089_50890301_81_dialog_content = "（あれ？足に何か引っ掛かった…）",
  ui_story_5089_50890301_82_dialog_content = "<color=#e8d9bb>ガラガラガラッ――！</color>",
  ui_story_5089_50890301_83_dialog_content = "<color=#e8d9bb>大量の竹竿がものすごい勢いで倒れてきた</color>",
  ui_story_5089_50890301_84_dialog_content = "わ、罠！？",
  ui_story_5089_50890301_85_dialog_content = "（後ろに下がっ…）",
  ui_story_5089_50890301_86_dialog_content = "<color=#e8d9bb>侵入者の動きをあらかじめ予測していたかのように、\n後退した足元の石畳が突然抜け落ちた</color>",
  ui_story_5089_50890301_87_dialog_content = "<color=#e8d9bb>ザッ――</color>",
  ui_story_5089_50890301_88_dialog_content = "<color=#e8d9bb>満杯に水を張った桶が頭上からさらに追い打ちをかける――</color>",
  ui_story_5089_50890301_89_dialog_content = "うわ！",
  ui_story_5089_50890301_90_dialog_content = "お気を付けください。",
  ui_story_5089_50890301_91_dialog_content = "<color=#e8d9bb>それは突然つむじ風が通り過ぎて行ったかのようだった。</color>",
  ui_story_5089_50890301_92_dialog_content = "<color=#e8d9bb>キュウがほんの半歩ほど進み、鞘に入ったままの刀を桶の取っ手部分に差し込んだ。\nすると桶はその勢いに乗ってくるりと回転した</color>",
  ui_story_5089_50890301_93_dialog_content = "<color=#e8d9bb>そして一滴も水をこぼすことなく、向かい側の少年の足下に戻っていった</color>",
  ui_story_5089_50890301_94_dialog_content = "<color=#e8d9bb>同時に路地の両側から倒れてきていた竹竿も不思議なことに宙で動きを止め、\nそのまま力を失い、ことごとく地面に倒れた</color>",
  ui_story_5089_50890301_95_dialog_content = "<color=#e8d9bb>しかもいつの間にか、すべて真っ二つになっていた</color>",
  ui_story_5089_50890301_96_dialog_content = "す…すごい。",
  ui_story_5089_50890301_97_dialog_content = "そ、そんな…",
  ui_story_5089_50890301_98_dialog_content = "盗ったものを返しなさい。",
  ui_story_5089_50890301_99_dialog_content = "…な、なんのことだよ！",
  ui_story_5089_50890301_100_dialog_content = "待ちなさい――",
  ui_story_5089_50890301_101_dialog_content = "キュウ、待って。",
  ui_story_5089_50890301_102_dialog_content = "わざわざこんな手の込んだ罠を仕掛けて待ち構えてるなんて、\n何か意味があるんじゃないかな。",
  ui_story_5089_50890301_103_dialog_content = "盗んだ物は近くの建物に隠してあるのかも。",
  ui_story_5089_50890301_104_dialog_content = "！",
  ui_story_5089_50890301_105_dialog_content = "ちょ、ちょっと待ってよ！\nボクはぬすっとだよ、早くつかまえなよ！",
  ui_story_5089_50890301_106_dialog_content = "やっぱり。",
  ui_story_5089_50890301_107_dialog_content = "じゃあ、こうしよう。建物の中は探さない。\nでもその代わり、ちゃんと話してくれないかな？",
  ui_story_5089_50890301_108_dialog_content = "僕たちは悪人じゃない。\n君が何か困ってるなら、助けてあげられるかもしれない。",
  ui_story_5089_50890301_109_dialog_content = "…ボ、ボクは…でも…",
  ui_story_5089_50890301_110_dialog_content = "お下がりを！",
  ui_story_5089_50890301_111_dialog_content = "え、なに…！？",
  ui_story_5089_50890301_112_dialog_content = "<color=#e8d9bb>シュッ――</color>",
  ui_story_5089_50890301_113_dialog_content = "<color=#e8d9bb>一筋の光が目の前をさっとかすめた</color>",
  ui_story_5089_50890301_114_dialog_content = "<color=#e8d9bb>カン！</color>",
  ui_story_5089_50890301_115_dialog_content = "<color=#e8d9bb>次の瞬間には、キュウの刀が宙から降ってきた何本もの細く丈夫な金属の糸を受け止めていた</color>",
  ui_story_5089_50890301_116_dialog_content = "見つけましたよ。",
  ui_story_5089_50890301_117_dialog_content = "お前は――",
  ui_story_5089_50890301_118_dialog_content = "<color=#e8d9bb>相手はそれにこたえることなく、ただ冷たい金属の糸だけが襲ってきた</color>",
  ui_story_5089_50890302_1_dialog_content = "キュウ、今だ！",
  ui_story_5089_50890302_2_dialog_content = "チッ。",
  ui_story_5089_50890302_3_dialog_content = "<color=#e8d9bb>倒れていた刺客が突然手を挙げると、\n1本の金属の糸が目にもとまらぬ速さで僕に向かってきた</color>",
  ui_story_5089_50890302_4_dialog_content = "！",
  ui_story_5089_50890302_5_dialog_content = "<color=#e8d9bb>ポタッ…</color>",
  ui_story_5089_50890302_6_dialog_content = "<color=#e8d9bb>一滴の血がしずかに砕け散り、汚れた地面に赤い色が広がった</color>",
  ui_story_5089_50890302_7_dialog_content = "キュウ…！",
  ui_story_5089_50890302_8_dialog_content = "<color=#e8d9bb>襲ってきた金属の糸をキュウが素手で受け止めたのだ</color>",
  ui_story_5089_50890302_9_dialog_content = "PlayerName様、驚かせてしまい申し訳ありません。",
  ui_story_5089_50890302_10_dialog_content = "<color=#e8d9bb>そう言うと、キュウは力一杯に両手を握り合わせた</color>",
  ui_story_5089_50890302_11_dialog_content = "<color=#e8d9bb>宙に飛び上がり、隙を見て逃亡しようとしていた刺客は\n血色に染まった金属の糸に引っ張られ、どしんと地に落ちた</color>",
  ui_story_5089_50890302_12_dialog_content = "捕らえて参ります。",
  ui_story_5089_50890302_13_dialog_content = "まったく…なぜよりによって鬼面閻羅が…",
  ui_story_5089_50890302_14_dialog_content = "大人しく降参せよ。そうすれば命は助けてやろう。",
  ui_story_5089_50890302_15_dialog_content = "…霜刃様、たかが斥候と言えど、私も同じく大王様に直接仕える者。\n恐れながら、同僚と呼ばせていただきましょう。",
  ui_story_5089_50890302_16_dialog_content = "私は任務中なのです。\n今私を捕らえれば、大王様の命に背くことになるとは思いませんか？",
  ui_story_5089_50890302_17_dialog_content = "…",
  ui_story_5089_50890302_18_dialog_content = "キュウ、傷口は大丈夫？あれ？刺客は…",
  ui_story_5089_50890302_19_dialog_content = "申し訳ありません…逃げられてしまいました。",
  ui_story_5089_50890302_20_dialog_content = "そう、別に構わないよ。君が無事なら…って、いや、無事じゃない！",
  ui_story_5089_50890302_21_dialog_content = "どうして素手で受けるなんて無茶したの？\n傷口を見せて。",
  ui_story_5089_50890302_22_dialog_content = "大した傷ではありません。\nPlayerName様のお手を煩わすには及びません。",
  ui_story_5089_50890302_23_dialog_content = "あのね、キュウ…うーん…今はよそう。\nとにかく、すぐ傷の手当をしてね。僕は子どもたちを見てくるから。",
  ui_story_5089_50890302_24_dialog_content = "「子どもたち」…ですか？",
  ui_story_5089_50890302_25_dialog_content = "うん、あの建物の中にいるんだ。",
  ui_story_5089_50890302_26_dialog_content = "うわああん…こわいよぉ、うわああああん――",
  ui_story_5089_50890302_27_dialog_content = "な、泣かないで…あ、そうだ！いいものを持ってきたよ。",
  ui_story_5089_50890302_28_dialog_content = "ほら、このお人形かわいいだろ？\nきれいなチョウチンもあるよ。",
  ui_story_5089_50890302_29_dialog_content = "それからね、おとぎ話の本もあるんだ！\n読んであげるよ。だから、もう泣かないで…",
  ui_story_5089_50890302_30_dialog_content = "ぐすっ…ううぅ…",
  ui_story_5089_50890302_31_dialog_content = "あの子が盗ったのは金じゃなくて、\nお世継ぎからもらったオモチャだったんだよ。",
  ui_story_5089_50890302_32_dialog_content = "金なんかいらないよ！",
  ui_story_5089_50890302_33_dialog_content = "うわああ、こ、こわい人がいるよぉ…うわあああん――",
  ui_story_5089_50890302_34_dialog_content = "出てってよ、ハナがこわがってるじゃないか！\nねえ、泣かないで…ほしいモノがあるなら、ボクがなんでも持ってきてあげるから…",
  ui_story_5089_50890302_35_dialog_content = "…",
  ui_story_5089_50890302_36_dialog_content = "キュウ？",
  ui_story_5089_50890302_37_dialog_content = "<color=#e8d9bb>キュウは少女の前にかがむと、ぎこちない手つきで面を外し、少女の頭にのせた</color>",
  ui_story_5089_50890302_38_dialog_content = "な、なにするんだよ！？ハナになにかしたら…",
  ui_story_5089_50890302_39_dialog_content = "風が吹いた、雨が降った。\n龍王様が太鼓をたたく。",
  ui_story_5089_50890302_40_dialog_content = "あの子はどこだ、お面の下だ。\n小さな可愛い女の子。",
  ui_story_5089_50890302_41_dialog_content = "さあさあ、こっちへおいで。\nおいしい瓜をたくさん食べよう。",
  ui_story_5089_50890302_42_dialog_content = "<color=#e8d9bb>キュウの優しい歌声が響き、お面を頭にのせた少女はだんだんと泣き止んだ</color>",
  ui_story_5089_50890302_43_dialog_content = "（キュウも…こんなに優しい顔をする時があるんだ…）",
  ui_story_5089_50890302_44_dialog_content = "PlayerName、キュウ、ここにおったか。",
  ui_story_5089_50890302_45_dialog_content = "おや？キュウが面を外しておるのう。いかがした？",
  ui_story_5089_50890302_46_dialog_content = "殿下、これはその…",
  ui_story_5089_50890302_47_dialog_content = "おネエちゃん…",
  ui_story_5089_50890302_48_dialog_content = "はい…",
  ui_story_5089_50890302_49_dialog_content = "今のお歌、もう一回うたって。",
  ui_story_5089_50890302_50_dialog_content = "かあさんが…うたってくれた歌みたいだった。",
  ui_story_5089_50890302_51_dialog_content = "いいですよ。",
  ui_story_5089_50890302_52_dialog_content = "ほんと？じゃあ、みんなを呼んでもいい！？",
  ui_story_5089_50890302_53_dialog_content = "皆…？",
  ui_story_5089_50890302_54_dialog_content = "ワンにいちゃん、みんなを呼んできてもいい？",
  ui_story_5089_50890302_55_dialog_content = "コイツら…わるいヤツじゃないみたいだし…\n呼びたいならいいよ。",
  ui_story_5089_50890302_56_dialog_content = "なにごとだよ、ハナ。急に呼び出すなんて。",
  ui_story_5089_50890302_57_dialog_content = "いいじゃないか、どうせやる事ないんだし。",
  ui_story_5089_50890302_58_dialog_content = "なんでオトナがいるの…？",
  ui_story_5089_50890302_59_dialog_content = "子どもが、こんなにたくさん…？",
  ui_story_5089_50890302_60_dialog_content = "ああ、その事でしたら、宿のご主人から聞きましたよ。",
  ui_story_5089_50890302_61_dialog_content = "途中、ご老人が若いもんは皆出稼ぎに行ったって言ってたでしょう？\nでも同じ国とはいっても、慣れない土地で暮らすわけですからねぇ。",
  ui_story_5089_50890302_62_dialog_content = "その多くが自分の親に子どもを預けていったそうなんです。\nただ年寄りには世話しきれないことも多いですよねぇ。",
  ui_story_5089_50890302_63_dialog_content = "それで子どもたちが自分らで集まって、村や里を駆け回ってるらしいんです。",
  ui_story_5089_50890302_64_dialog_content = "ということは、この子たちは兄妹じゃないの？\n僕はてっきり兄妹だと…",
  ui_story_5089_50890302_65_dialog_content = "ハナは妹だよ。ボクの父さんと母さんはいなくなっちゃったから\nハナの父さんと母さんが食べさせてくれてるんだ。",
  ui_story_5089_50890302_66_dialog_content = "でもハナの父さんも母さんも「デカセギ」に行っちゃって、\nハナの面倒はボクが見てるんだ。",
  ui_story_5089_50890302_67_dialog_content = "でも父さんと母さんが恋しいみたいで、\n何日もずっと泣いてて、だから…",
  ui_story_5089_50890302_68_dialog_content = "オモチャを盗ったの？",
  ui_story_5089_50890302_69_dialog_content = "つかまっちゃったからには、\nどんなバツを受けても文句いわない！",
  ui_story_5089_50890302_70_dialog_content = "物を盗るのはいけないことだよ。\nでも事情も分かったし、君を罰する気はない。",
  ui_story_5089_50890302_71_dialog_content = "ただ…どうしよう？\n大勢の子どもに取り囲まれて、キュウが固まっちゃってる…",
  ui_story_5089_50890302_72_dialog_content = "PlayerNameも見てばかりではのうて、手を貸すのじゃ。",
  ui_story_5089_50890302_73_dialog_content = "手を貸すって…何を？",
  ui_story_5089_50890302_74_dialog_content = "大勢の前で歌うなどキュウには難儀なことじゃ。\nわれらも手伝おうではないか。",
  ui_story_5089_50890302_75_dialog_content = "さあ宿へ戻り、琵琶を持ってまいろう。",
  ui_story_5089_50890302_76_dialog_content = "PlayerNameが「ピアノ」なる楽器をたしなむことは知っておったが、聴いたことはなかったのう。\nどうじゃ、この機に合奏してみぬか？",
  ui_story_5089_50890302_77_dialog_content = "そうしたいけど、ピアノがないよ。",
  ui_story_5089_50890302_78_dialog_content = "ご心配にはおよびません！",
  ui_story_5089_50890302_79_dialog_content = "古の賢者は皿を叩いて楽を奏でたといいますしねぇ。\nダンナも杯を叩いてみてはいかがです？",
  ui_story_5089_50890302_80_dialog_content = "ほら、お聞きください。\n杯は中の水の量が変わると、叩いた時の音の高さが変わるんです。",
  ui_story_5089_50890302_81_dialog_content = "本当だ。そうだね、やってみる。",
  ui_story_5089_50890302_82_dialog_content = "キュウ、双閣港を訪れた時、わらわが言うたことを覚えておるか？",
  ui_story_5089_50890302_83_dialog_content = "もしピアニストと共に楽を奏でられる日が来たら、\nお主には刀剣の舞を披露してもらいたいと。",
  ui_story_5089_50890302_84_dialog_content = "し、しかし…このような大勢の前で…",
  ui_story_5089_50890302_85_dialog_content = "お主だけではない。われらもおる。",
  ui_story_5089_50890302_86_dialog_content = "ふむ。どうしても嫌じゃというのなら、無理強いはせぬ。\nただ…せっかくの楽が物足りなくなってしまうのう。",
  ui_story_5089_50890302_87_dialog_content = "しょ、承知いたしました…",
  ui_story_5089_50890302_88_dialog_content = "力不足ではございますが、舞うといたします。",
  ui_story_5089_50890302_89_dialog_content = "ホホホ。キュウ、見てみよ。\n子どもらの目が輝いておるぞ。",
  ui_story_5089_50890302_90_dialog_content = "お主の舞もきっと天下一なのじゃろうな。",
  ui_story_5089_50890302_91_dialog_content = "殿下！滅相もございません。\n私の舞はつたないもの、お恥ずかしゅうございます。",
  ui_story_5089_50890302_92_dialog_content = "楽も舞もそろったところで、僕は何をしましょうかねぇ？",
  ui_story_5089_50890302_93_dialog_content = "ちと小唄でも歌って、興を添えましょうか。",
  ui_story_5089_50890302_94_dialog_content = "ほう、小唄とな。何を歌えるのじゃ？",
  ui_story_5089_50890302_95_dialog_content = "コホン…さあ、寄ってらっしゃい見てらっしゃい！",
  ui_story_5089_50890302_96_dialog_content = "道行く旅の方も、村の皆様も、さあさあ見てらっしゃい。",
  ui_story_5089_50890302_97_dialog_content = "懐が寂しい方はお代は結構、\n懐に余裕がある方は、どうか投げ銭を。",
  ui_story_5089_50890302_98_dialog_content = "<color=#e8d9bb>チャリン</color>",
  ui_story_5089_50890302_99_dialog_content = "<color=#e8d9bb>事情を知らずに集まってきた人たちが本当に銅銭を投げてきた</color>",
  ui_story_5089_50890302_100_dialog_content = "テンカン！",
  ui_story_5089_50890302_101_dialog_content = "おやおや殿下、楽を奏でる時は心穏やかでないといけませんよ。",
  ui_story_5089_50890302_102_dialog_content = "<color=#e8d9bb>かすかに漂う風雲の兆し、間に合わせの「ピアノ」――\nそれぞれがそれぞれの思いを胸に音楽を奏で、舞いを舞う</color>",
  ui_story_5089_50890302_103_dialog_content = "<color=#e8d9bb>けっして完璧とはいえない、間に合わせの演奏――</color>",
  ui_story_5089_50890302_104_dialog_content = "<color=#e8d9bb>それでも今この瞬間だけは――</color>",
  ui_story_5089_50890302_105_dialog_content = "<color=#e8d9bb>この上なく美しい</color>",
  ui_story_5089_50890401_1_dialog_content = "PlayerName、先刻より何を真剣に見ておるのじゃ？",
  ui_story_5089_50890401_2_dialog_content = "あ…この人形のこと？ワンが別れ際にくれたんだよ。",
  ui_story_5089_50890401_3_dialog_content = "キュウがお面をあげたおかげでハナちゃんも泣き止んだし、\nオモチャはもういらないって、盗った物を全部返してくれたんだ。",
  ui_story_5089_50890401_4_dialog_content = "合わせてお詫びだって、これをくれたんだよ。",
  ui_story_5089_50890401_5_dialog_content = "少し前に村を通りかかったお姉ちゃんが作ってくれたんだって。\n「マゴラ」とかいう人形らしいよ。",
  ui_story_5089_50890401_6_dialog_content = "そのお姉ちゃん、黒い服の人をたっくさん連れてたんだよ。\nでも、黒い人たちはぜんぜんじゃべらなくて、なんかすごくこわかった。",
  ui_story_5089_50890401_7_dialog_content = "でもお姉ちゃんはとってもいい人だったよ。\nお肉をたくさん食べさせてくれたの。",
  ui_story_5089_50890401_8_dialog_content = "しかもいろんなモノを作れるんだ。\nあのワナもみんな、お姉ちゃんが書いた絵を見て作ったんだ。",
  ui_story_5089_50890401_9_dialog_content = "ワナはカラクリのキソだから、\n勉強すれば、かしこくなれるって言ってた。",
  ui_story_5089_50890401_10_dialog_content = "名前は教えてもらった？",
  ui_story_5089_50890401_11_dialog_content = "ううん、村には1日しかいなくて、すぐにいなくなっちゃったから。\nでも…あ、そうだ！",
  ui_story_5089_50890401_12_dialog_content = "そのお姉ちゃん、なんでかわからないけど、雨も降ってないのに、\n一日中ずっと大きな傘を持ってた。",
  ui_story_5089_50890401_13_dialog_content = "なんだか…僕たちがよく知ってる人みたいだよね？",
  ui_story_5089_50890401_14_dialog_content = "ここは済の国から鄴の国に入る最短経路じゃからのう。\n璇璣卿らが村を通ってもおかしくはない。",
  ui_story_5089_50890401_15_dialog_content = "じゃが馳走を食らい、子どもらと遊び、\nさらには武器を持ち歩いていたとは…",
  ui_story_5089_50890401_16_dialog_content = "朝廷の大罪人にそぐわぬ待遇じゃのう。",
  ui_story_5089_50890401_17_dialog_content = "でも、黒い服の人たちが付いてたなら、\n自由に行動することはできないよね？",
  ui_story_5089_50890401_18_dialog_content = "PlayerName、その人形をちと見せてもらえぬか？",
  ui_story_5089_50890401_19_dialog_content = "いいよ。でもいくら見ても何も分からなかった。\n中に何か入ってないか感知してみたけど、空っぽだったし…",
  ui_story_5089_50890401_20_dialog_content = "何か隠されているとすれば、人形そのものにか…",
  ui_story_5089_50890401_21_dialog_content = "<color=#e8d9bb>深夜</color>",
  ui_story_5089_50890401_22_dialog_content = "ふわ…",
  ui_story_5089_50890401_23_dialog_content = "喉が渇いたな…水を飲もう…",
  ui_story_5089_50890401_24_dialog_content = "あ、空っぽだ。広間にお水ないかな…",
  ui_story_5089_50890401_25_dialog_content = "あれ？隣は確かタンドウの部屋のはずだけど、まだ明かりがついてる…",
  ui_story_5089_50890401_26_dialog_content = "PlayerNameか？",
  ui_story_5089_50890401_27_dialog_content = "え？見えてるの？",
  ui_story_5089_50890401_28_dialog_content = "ホホホ、足音じゃよ。さあ中へ。",
  ui_story_5089_50890401_29_dialog_content = "そのテーブルの上のものって…まだ調べてたの？",
  ui_story_5089_50890401_30_dialog_content = "あの璇璣卿が残した物じゃぞ。\n故意でなくとも何かしらの情報が隠されているに違いない。",
  ui_story_5089_50890401_31_dialog_content = "そういえば聞きたかったんだけど、「マゴラ」って何？",
  ui_story_5089_50890401_32_dialog_content = "昔流行っていた玩具でのう。\n通常、粘土か木で作り、金属で造られることはない。",
  ui_story_5089_50890401_33_dialog_content = "でも、これは銅で出来てるよ？",
  ui_story_5089_50890401_34_dialog_content = "そうなのじゃ。璇璣卿は銅を使うのに長けている。\n卿が頭角を現し、世に知られるきっかけとなったのも銅の奏楽隊人形じゃった。",
  ui_story_5089_50890401_35_dialog_content = "卿は銅人形と楽を奏でたのじゃが、\n演奏が終わるまで誰もそれが人形だとは気づかなんだ。",
  ui_story_5089_50890401_36_dialog_content = "センキョクはそんなすごい物を作ったことがあったんだね。でも…\nだったらこの人形、どうしてこんなに可愛くないんだろう？",
  ui_story_5089_50890401_37_dialog_content = "そこなのじゃ。明らかにおかしい。",
  ui_story_5089_50890401_38_dialog_content = "「マゴラ」とは元来可愛らしい子どもの姿をした人形でのう。\nじゃが璇璣卿の「マゴラ」は妖魔のように醜く、しかもわざわざシワまで入れてある。",
  ui_story_5089_50890401_39_dialog_content = "「マゴラ」はハスの葉かハスの花を手に持っておるのじゃが――",
  ui_story_5089_50890401_40_dialog_content = "この人形が手にしておるのは、花は花でもモクレンじゃ。",
  ui_story_5089_50890401_41_dialog_content = "ハスは水を好み、モクレンは水を嫌う――\n相容れない性質を持っておる。",
  ui_story_5089_50890401_42_dialog_content = "この人形は「マゴラ」に似てはいるが、何もかも違うておる。\nまがいものを「マゴラ」に見せかけているだけじゃ。",
  ui_story_5089_50890401_43_dialog_content = "まがいもの…見せかけ…",
  ui_story_5089_50890401_44_dialog_content = "それにのう、かつて龍州には「魔合羅」という芝居があった。",
  ui_story_5089_50890401_45_dialog_content = "今や演じられることはなくなり、ある台詞だけが世に広く知られておる。",
  ui_story_5089_50890401_46_dialog_content = "どんな台詞？",
  ui_story_5089_50890401_47_dialog_content = "「虎の皮は描けても、骨までは描けぬ。\n人の顔は見えても、心までは見通せぬ」とな。",
  ui_story_5089_50890401_48_dialog_content = "<color=#e8d9bb>バン…</color>",
  ui_story_5089_50890401_49_dialog_content = "！",
  ui_story_5089_50890401_50_dialog_content = "何者じゃ！？",
  ui_story_5089_50890402_1_dialog_content = "勝てぬと分かれば逃げ出すか。\n奴らの力もたかが知れておるようじゃのう。",
  ui_story_5089_50890402_2_dialog_content = "今のは天命を受けし者？それとも…",
  ui_story_5089_50890402_3_dialog_content = "分からぬ。",
  ui_story_5089_50890402_4_dialog_content = "じゃが今や天命を受けし者であろうと、鄴の国の密偵であろうと、\n大した違いはあるまい。",
  ui_story_5089_50890402_5_dialog_content = "幸い今のは数も少なく、武にもさほど秀でておらぬ。",
  ui_story_5089_50890402_6_dialog_content = "唯一逃げ足だけは一流じゃったのう。\nおそらく偵察に来た斥候じゃろう。",
  ui_story_5089_50890402_7_dialog_content = "つまり、僕たちの足取りはもう知られてるってこと？\nだったら早くここを離れた方がいいんじゃ…",
  ui_story_5089_50890402_8_dialog_content = "それはそうとPlayerName、おかしなことに気づかぬか？",
  ui_story_5089_50890402_9_dialog_content = "え？おかしなこと？…あ！",
  ui_story_5089_50890402_10_dialog_content = "あんな大きな物音がしたのに…キュウが来ない！",
  ui_story_5089_50890402_11_dialog_content = "先に行った奴ら、なんだってまだ戻ってこないんだ？\nまさか、やられたか？",
  ui_story_5089_50890402_12_dialog_content = "この程度の任務もまともにできないようじゃ、やられても仕方ないな。",
  ui_story_5089_50890402_13_dialog_content = "はぁ…まったくついてないな。\nまあいい、厠へ行ってくる。",
  ui_story_5089_50890402_14_dialog_content = "動くな。",
  ui_story_5089_50890402_15_dialog_content = "！",
  ui_story_5089_50890402_16_dialog_content = "わ、分かった…動かないから、落ち着いてくれ。",
  ui_story_5089_50890402_17_dialog_content = "気配を完全に消して忍び込み、密偵の喉に刃を突き付けるなんて、\nあんたは相当な手練れだ。抵抗する気はない。",
  ui_story_5089_50890402_18_dialog_content = "まずは刀をどけてくれ。\nうっかり首でも切れば、何も聞き出せなくなるぞ。",
  ui_story_5089_50890402_19_dialog_content = "お前たち、ここで何をしている？\nいったい何の命令で動いているのだ？",
  ui_story_5089_50890402_20_dialog_content = "それは…",
  ui_story_5089_50890402_21_dialog_content = "さっさと答えろ。",
  ui_story_5089_50890402_22_dialog_content = "わ、分かった…俺たちは、主から言う事を聞かないお嬢様を連れ帰るよう言われてるんだ。",
  ui_story_5089_50890402_23_dialog_content = "ただの内輪事だ、罪じゃないだろう？",
  ui_story_5089_50890402_24_dialog_content = "「内輪事」にしてはずいぶんと仰々しいな。",
  ui_story_5089_50890402_25_dialog_content = "主の家はどこにでもあるような家じゃないんだよ。\nしかもお嬢様の近くには腕の立つ護衛が付いている。",
  ui_story_5089_50890402_26_dialog_content = "その護衛も主がお嬢様のために付けたんだが、\nいったい何を考えてるやら、そいつはお嬢様の命しか聞かないんだよ。",
  ui_story_5089_50890402_27_dialog_content = "主もひどくがっかりしててね。",
  ui_story_5089_50890402_28_dialog_content = "…",
  ui_story_5089_50890402_29_dialog_content = "言っただろ、ただの「内輪事」だって。",
  ui_story_5089_50890402_30_dialog_content = "腹を立てているだけで、主にお嬢様を傷つけるつもりはない。",
  ui_story_5089_50890402_31_dialog_content = "連れ帰った後だって、せいぜい謹慎か、\n家訓を何百回か書き写すくらいの罰ですむだろうに。",
  ui_story_5089_50890402_32_dialog_content = "あの護衛ときたら、己の本分も忘れて主の大事を台無しにしようとしている。",
  ui_story_5089_50890402_33_dialog_content = "長い間目に掛けてきてやったのに、まさか恩知らずに育つとはな。\nあんたも思わないか…",
  ui_story_5089_50890402_34_dialog_content = "おい、聞いてるか？",
  ui_story_5089_50890402_35_dialog_content = "フフ…",
  ui_story_5089_50890402_36_dialog_content = "おい、ずいぶんと長かったな。",
  ui_story_5089_50890402_37_dialog_content = "昔馴染みにばったり会ってね、少し話してたんだ。",
  ui_story_5089_50890402_38_dialog_content = "先に行った奴らが戻ったら、伝えるんだ。",
  ui_story_5089_50890402_39_dialog_content = "明日郡主殿下を連れ帰る。",
  ui_story_5089_50890402_40_dialog_content = "もし鬼面閻羅が邪魔をするようなら、反逆罪で――",
  ui_story_5089_50890402_41_dialog_content = "その場で処刑する。",
  ui_story_5089_50890402_42_dialog_content = "…タンドウ殿下、PlayerName様、なぜ外にいらっしゃるのですか？",
  ui_story_5089_50890402_43_dialog_content = "キュウ、どこへ行ってたの？さっき――",
  ui_story_5089_50890402_44_dialog_content = "PlayerName。",
  ui_story_5089_50890402_45_dialog_content = "もう遅い、戻って休むがよい。",
  ui_story_5089_50890402_46_dialog_content = "わらわはまだ考えたいことがある。",
  ui_story_5089_50890402_47_dialog_content = "…うん。",
  ui_story_5089_50890402_48_dialog_content = "お休み、タンドウ、キュウ。",
  ui_story_5089_50890402_49_dialog_content = "PlayerName、おやすみなさい。",
  ui_story_5089_50890402_50_dialog_content = "…",
  ui_story_5089_50890402_51_dialog_content = "<color=#e8d9bb>翌日</color>",
  ui_story_5089_50890402_52_dialog_content = "ちと邪魔するぞ、テンカン殿。",
  ui_story_5089_50890402_53_dialog_content = "やや…まだ夢の世界にでもいるんでしょうか？\n今とんでもないことを耳にしたような…",
  ui_story_5089_50890402_54_dialog_content = "タンドウ殿下、そんなに改まっていったい何事です？",
  ui_story_5089_50890402_55_dialog_content = "そうよのう…ちと占ってもらいことがあるのじゃ。",
  ui_story_5089_50890402_56_dialog_content = "こりゃあ珍しいこともあるもんですねぇ。",
  ui_story_5089_50890402_57_dialog_content = "天意か、それとも吉兆か、はたまた結婚運か。\nいったい何をお知りになりたいんです？",
  ui_story_5089_50890402_58_dialog_content = "行く末を…占ってもらいたい。",
  ui_story_5089_50890402_59_dialog_content = "なすべきかなさぬべきか、かなうかかなわぬか…分からんでのう。",
  ui_story_5089_50890402_60_dialog_content = "ふむ、承知しました。\nでは占いますんで、お手をちと拝借します。",
  ui_story_5089_50890402_61_dialog_content = "うむ。",
  ui_story_5089_50890402_62_dialog_content = "<color=#e8d9bb>パラッ…</color>",
  ui_story_5089_50890402_63_dialog_content = "<color=#e8d9bb>筮竹（ぜいちく）が2本タンドウの手のひらに転がり落ちた。\nしかし、じっくり見る間もなく――</color>",
  ui_story_5089_50890402_64_dialog_content = "<color=#e8d9bb>パラパラパラッ…テンカンが筒の中の筮竹をすべて出してしまった</color>",
  ui_story_5089_50890402_65_dialog_content = "テンカン殿、何のつもりじゃ？",
  ui_story_5089_50890402_66_dialog_content = "ははは、殿下にそんなふうに呼ばれるのはどうも慣れませんねぇ。\n「ペテン師」と呼ばれた方がよっぽどしっくりきます。",
  ui_story_5089_50890402_67_dialog_content = "卦なんてもんは大したもんじゃございませんがね、\nそれでも僕はこれで天下を渡り歩いてきたんですよ。",
  ui_story_5089_50890402_68_dialog_content = "信じる人は、災禍を免れる兆しと喜びますが…",
  ui_story_5089_50890402_69_dialog_content = "信じない人は一笑に付して終わりです。\n要は、信じれば何でも天意となるんでございますよ。",
  ui_story_5089_50890402_70_dialog_content = "でも殿下は占いたいと言いながら、疑ってますねぇ。\n天に行く末を聞きたいといいながら、天命に従う気もない…",
  ui_story_5089_50890402_71_dialog_content = "これが冷やかしじゃなくて何なんです？",
  ui_story_5089_50890402_72_dialog_content = "お主…ちと言葉が過ぎぬか？",
  ui_story_5089_50890402_73_dialog_content = "そうは思いませんねぇ。",
  ui_story_5089_50890402_74_dialog_content = "ならばお聞きしますが、最初の筮竹が落ちた時、\n殿下のお気持ちはすでに決まってたんじゃありませんか？",
  ui_story_5089_50890402_75_dialog_content = "…",
  ui_story_5089_50890402_76_dialog_content = "図星のようですねぇ。\n殿下はかの「灼華郡主」、天命など信じないことは誰もが知っています。",
  ui_story_5089_50890402_77_dialog_content = "決心がついてらっしゃるなら、暇つぶしは他でお願いしますよ。",
  ui_story_5089_50890402_78_dialog_content = "ただ、筮竹を筒に戻すのは手伝っていただきますがねぇ。",
  ui_story_5089_50890402_79_dialog_content = "テンカン殿。",
  ui_story_5089_50890402_80_dialog_content = "おやおや、タンドウ殿下。\nなんだってまだその呼び方なんです？",
  ui_story_5089_50890402_81_dialog_content = "もう一つ頼みがあるのじゃ。",
  ui_story_5089_50890402_82_dialog_content = "…ふむ、そうでしたか。\nでは先程の言葉は撤回するとしますかね。",
  ui_story_5089_50890402_83_dialog_content = "さあ、手をお出しください。\nもう一度占って、殿下をお止めしなきゃいけませんからね。",
  ui_story_5089_50890402_84_dialog_content = "悪いのう、わらわは灼華郡主じゃ。",
  ui_story_5089_50890402_85_dialog_content = "天命など信じぬ。お主もよく知っておろう？",
  ui_story_5089_50890402_86_dialog_content = "ざまあみろ、ざまあみろ。",
  ui_story_5089_50890402_87_dialog_content = "自分で自分のクビ締めた！",
  ui_story_5089_50890402_88_dialog_content = "はぁ…仕方ないですねぇ。\n命を助けてもらった恩もまだ返していませんし…",
  ui_story_5089_50890402_89_dialog_content = "で、何をすればよろしいんですか？",
  ui_story_5089_50890402_90_dialog_content = "タンドウ、言われた通り鏢局（ひょうきょく）に頼んできたよ。",
  ui_story_5089_50890402_91_dialog_content = "お世継ぎからもらった金は先に王都へ運んでもらう。",
  ui_story_5089_50890402_92_dialog_content = "後は何をすればいい？僕たちも出発する？",
  ui_story_5089_50890402_93_dialog_content = "まだよい。",
  ui_story_5089_50890402_94_dialog_content = "宿の主人が新茶をくれてのう。なかなかよい茶なのじゃ。\n一息ついてからでも遅くはなかろう。",
  ui_story_5089_50890402_95_dialog_content = "本当にこんなにゆっくりしてて大丈夫？",
  ui_story_5089_50890402_96_dialog_content = "構わぬ。そう長くはかからぬ。",
  ui_story_5089_50890402_97_dialog_content = "キュウ、おるな。",
  ui_story_5089_50890402_98_dialog_content = "…はい。",
  ui_story_5089_50890402_99_dialog_content = "お主も座って飲むがよい。その後で話したいことがあるのじゃ。",
  ui_story_5089_50890402_100_dialog_content = "承知いたしました。",
  ui_story_5089_50890402_101_dialog_content = "このお茶、本当においしいね。\nさっぱりとさわやかで、しかもフルーツみたいな香りがする。",
  ui_story_5089_50890402_102_dialog_content = "微毒の果物で作った「寒脈散」を加えたせいじゃ。",
  ui_story_5089_50890402_103_dialog_content = "…え？",
  ui_story_5089_50890402_104_dialog_content = "<color=#e8d9bb>ドンッ！</color>",
  ui_story_5089_50890402_105_dialog_content = "<color=#e8d9bb>キュウが突然片膝を地につけた</color>",
  ui_story_5089_50890402_106_dialog_content = "キ…キュウ！",
  ui_story_5089_50890402_107_dialog_content = "大事ない。寒脈散を飲むと、しびれが起こり、動けなくなってしまうが、\n臓腑が傷つくことはない。しばらくすれば元に戻る。",
  ui_story_5089_50890402_108_dialog_content = "ただ武芸に優れ、気の力の強い者ほど毒の巡りが速いのじゃ。\n効き目もその分長く続く。",
  ui_story_5089_50890402_109_dialog_content = "それで感覚がないのか…いや、違う。\n今はそんなことを言ってる場合じゃない！",
  ui_story_5089_50890402_110_dialog_content = "どうしてこんなことするの？",
  ui_story_5089_50890402_111_dialog_content = "もう時がないのじゃ。",
  ui_story_5089_50890402_112_dialog_content = "タンドウ殿下、タゲンとタゴによれば、\nすでに大勢の者がこちらへ向かっているそうですよ。",
  ui_story_5089_50890402_113_dialog_content = "明らかに、歓迎すべき客じゃなさそうですねぇ。",
  ui_story_5089_50890402_114_dialog_content = "テンカン、君まで…って誰？",
  ui_story_5089_50890402_115_dialog_content = "そりゃあ正真正銘、キュウでございますよ。",
  ui_story_5089_50890402_116_dialog_content = "いやいや、どこが「正真正銘」なの！？",
  ui_story_5089_50890402_117_dialog_content = "まあまあダンナ、こんな時にいちいち細かい事にこだわらないでくださいよ。",
  ui_story_5089_50890402_118_dialog_content = "ええ…僕が悪いの…？",
  ui_story_5089_50890402_119_dialog_content = "ダンナ、すみませんが、キュウさんをあっちの棚に隠すのを手伝ってくださいな。\nさあさあ、急ぎましょう。",
  ui_story_5089_50890402_120_dialog_content = "あ、うん…えっ？",
  ui_story_5089_50890402_121_dialog_content = "なぜ…",
  ui_story_5089_50890402_122_dialog_content = "<color=#e8d9bb>キュウの身体がかすかに震えた。\n薬に抗おうともがく骨や筋肉の音が聞えてくるようだ</color>",
  ui_story_5089_50890402_123_dialog_content = "<color=#e8d9bb>手の傷口が開き、鮮血が服を染める</color>",
  ui_story_5089_50890402_124_dialog_content = "<color=#e8d9bb>こわばった身体を懸命に動かし、\nキュウはやっとのことでタンドウの着物の裾をつかんだ</color>",
  ui_story_5089_50890402_125_dialog_content = "…",
  ui_story_5089_50890402_126_dialog_content = "<color=#e8d9bb>だが、タンドウは一歩後ろに下がり、\n着物の裾をキュウの手から引きはがした</color>",
  ui_story_5089_50890402_127_dialog_content = "この5年を共に過ごし、お主はわらわのため多くのことを成してくれた。\n心より礼を言う。",
  ui_story_5089_50890402_128_dialog_content = "お主はよき奴じゃ。かつては最も優秀な護衛でもあった。",
  ui_story_5089_50890402_129_dialog_content = "じゃがこれ以上はもう、われらの間のほころびを隠すことはできまい。",
  ui_story_5089_50890402_130_dialog_content = "お主にわらわを傷つけることはできぬ。\nじゃが、叔父の命令にも背けぬじゃろう？",
  ui_story_5089_50890402_131_dialog_content = "相反する2つの道を同時に進むことも、\n立場を異にする2人の手中の刃となることもできぬ。",
  ui_story_5089_50890402_132_dialog_content = "タンドウ…殿下…",
  ui_story_5089_50890402_133_dialog_content = "元来お主自らが選ぶべきことであって、\nわらわが決めることではないのじゃがのう。",
  ui_story_5089_50890402_134_dialog_content = "お主が選ぼうとせぬゆえ、わらわが決めることにした。",
  ui_story_5089_50890402_135_dialog_content = "自由に動けぬ今、お主も他人の意のままに動く人形となるしかあるまい。",
  ui_story_5089_50890402_136_dialog_content = "よく見てみよ。今のお主には何もできぬ。",
  ui_story_5089_50890402_137_dialog_content = "キュウ。",
  ui_story_5089_50890402_138_dialog_content = "今日をもって、灼華郡主の護衛の職を解く。",
  ui_story_5089_50890402_139_dialog_content = "！",
  ui_story_5089_50890402_140_dialog_content = "わらわにはもう必要ない。今のお主を側に置くのも危険じゃ。",
  ui_story_5089_50890402_141_dialog_content = "守られながら、監視されるのも御免なのじゃ。",
  ui_story_5089_50890402_142_dialog_content = "わらわは――",
  ui_story_5089_50890402_143_dialog_content = "<color=#e8d9bb>ドーン！</color>",
  ui_story_5089_50890402_144_dialog_content = "<color=#e8d9bb>タンドウの最後の言葉は外の大きな音にかき消されてしまった</color>",
  ui_story_5089_50890402_145_dialog_content = "さあ、お入りください。",
  ui_story_5089_50890402_146_dialog_content = "？",
  ui_story_5089_50890402_147_dialog_content = "<color=#e8d9bb>僕まで棚の中に押し込められてしまった</color>",
  ui_story_5089_50890402_148_dialog_content = "すまぬのう、PlayerName。\n我が儘を押し付けてしもうて。",
  ui_story_5089_50890402_149_dialog_content = "キュウを…後の事を頼んだぞ。",
  ui_story_5089_50890402_150_dialog_content = "待って、タンドウ！",
  ui_story_5089_50890402_151_dialog_content = "<color=#e8d9bb>棚の扉が閉まった</color>",
  ui_story_5089_50890402_152_dialog_content = "<color=#e8d9bb>次の瞬間、元居た部屋の扉が音を立てて勢いよく開けられた</color>",
  ui_story_5089_50890402_153_dialog_content = "ふぅ。郡主様とお目にかかるには、こんなに骨が折れるのですね。",
  ui_story_5089_50890402_154_dialog_content = "（この声は…！）",
  ui_story_5089_50890402_155_dialog_content = "テイト…",
  ui_story_5089_50890402_156_dialog_content = "璇璣卿の申しておった通りじゃな。\nお主、まだ生きておったか。",
  ui_story_5089_50890402_157_dialog_content = "最強のカラクリ獣をまだ造り出せていないのです。\n意地でも生き残るに決まっているでしょう？",
  ui_story_5089_50890402_158_dialog_content = "かねてより疑念は持っておったが、今や尋ねる必要もなさそうじゃのう。\nお主、やはり天命を受けし者の一人であったか。",
  ui_story_5089_50890402_159_dialog_content = "機巧術の研究を援助してくれるのなら、誰であろうと私は主と呼びますよ。\n人とはそういうものでしょう？",
  ui_story_5089_50890402_160_dialog_content = "ただ、ようやく燭陰火を取り戻し、\n蠍の次世代エネルギーシステムの調整に忙しいというのに――",
  ui_story_5089_50890402_161_dialog_content = "この人たちに郡主様のお迎えに来いと引っ張り出されてしまったのです。",
  ui_story_5089_50890402_162_dialog_content = "ただその代わり、一ついい条件を約束してくれたのです。",
  ui_story_5089_50890402_163_dialog_content = "殿下とお側の護衛が抵抗した場合、\n新しい武器の実験検証を行ってもよい、とね。",
  ui_story_5089_50890402_164_dialog_content = "ですから、お二人とも抵抗してくださいません？",
  ui_story_5089_50890402_165_dialog_content = "なにゆえ抵抗せねばならぬのじゃ？",
  ui_story_5089_50890402_166_dialog_content = "わらわは鄴の国の郡主。\nお主はさておき、他の者らはみな叔父麾下の兵士であろう。",
  ui_story_5089_50890402_167_dialog_content = "叔父麾下の者が出迎えとあらば、わらわを傷つけることもあるまい。\nさようであろう、キュウ？",
  ui_story_5089_50890402_168_dialog_content = "（うなずく）",
  ui_story_5089_50890402_169_dialog_content = "はぁ…まあいいとしましょう。\nだったら急いでください。工房に戻ってやるべき事が山ほどあるのです。",
  ui_story_5089_50890402_170_dialog_content = "お待ちください。郡主殿下のお側にはあと2人いたはずです。",
  ui_story_5089_50890402_171_dialog_content = "あのいかがわしい占い師ならば、\n物音を聞いてすぐに逃げおったわ。",
  ui_story_5089_50890402_172_dialog_content = "空の末裔については…あれは1人では何もできぬ。\n何を恐るることがあるのじゃ？",
  ui_story_5089_50890402_173_dialog_content = "それに叔父の命は「わらわ」を連れ帰ることじゃろう？",
  ui_story_5089_50890402_174_dialog_content = "はい…では郡主殿下、参りましょう。",
  ui_story_5089_50890402_175_dialog_content = "<color=#e8d9bb>部屋に再び静けさが戻った</color>",
  ui_story_5089_50890402_176_dialog_content = "<color=#e8d9bb>でももうここには僕とキュウの2人しかいない</color>",
  ui_story_5089_50890501_1_dialog_content = "…タンドウもテンカンもいったい何を考えてるの！？",
  ui_story_5089_50890501_2_dialog_content = "この前少しでも自由に動ける時間を稼ぎたいって言ってたばかりなのに、\n何もしないまま自分から網にかかるなんて…",
  ui_story_5089_50890501_3_dialog_content = "テイトみたいな危険人物がいるんじゃ、\nなおさら安全は保証できないよ。",
  ui_story_5089_50890501_4_dialog_content = "キュウもそう思うでしょ？",
  ui_story_5089_50890501_5_dialog_content = "私には…分かりません。",
  ui_story_5089_50890501_6_dialog_content = "殿下はもう私を信頼なさっていないのです。",
  ui_story_5089_50890501_7_dialog_content = "殿下がおっしゃったように、\n私は務めを果たせていなかったのでしょう。",
  ui_story_5089_50890501_8_dialog_content = "それに今やタンドウ殿下の護衛ではない私に何をしろと…",
  ui_story_5089_50890501_9_dialog_content = "何を言ってるの？\n少なくとも1つ絶対にやらなきゃいけないことがあるでしょ？",
  ui_story_5089_50890501_10_dialog_content = "何と？",
  ui_story_5089_50890501_11_dialog_content = "タンドウはもう時間がないって言ってた。",
  ui_story_5089_50890501_12_dialog_content = "でも船に乗ってた時は、まだそんなふうに焦ってなかった。\n君が迷うのも理解できるって言ってたんだよ。",
  ui_story_5089_50890501_13_dialog_content = "でも一晩明けたら、タンドウの態度が変わった。",
  ui_story_5089_50890501_14_dialog_content = "センキョクのあの人形に何か鍵になる情報が隠されてたのかもしれない。",
  ui_story_5089_50890501_15_dialog_content = "それに…何も言わずにただ「後の事を頼む」って…",
  ui_story_5089_50890501_16_dialog_content = "だから、今ある手がかりを元に何とかセンキョクを見つけ出せば、\nきっと真相が分かるはずだよ。",
  ui_story_5089_50890501_17_dialog_content = "それから…キュウ。君はタンドウとケンカするといいよ。",
  ui_story_5089_50890501_18_dialog_content = "タンドウ殿下と…？何をおっしゃるのですか！",
  ui_story_5089_50890501_19_dialog_content = "でも、もう主じゃないんでしょ？",
  ui_story_5089_50890501_20_dialog_content = "たとえそうだとしても…",
  ui_story_5089_50890501_21_dialog_content = "何か事情があるんだろうし、タンドウだって悩んだと思う。\nでも、こんな一方的に何もかも決めちゃうなんてひどいよ。",
  ui_story_5089_50890501_22_dialog_content = "正直言うと、僕も少し怒ってるんだ。",
  ui_story_5089_50890501_23_dialog_content = "慣れない土地に放り出されたうえに…",
  ui_story_5089_50890501_24_dialog_content = "何も分からないまま、大切な友だちが命の危険を犯して、\n何かしようとしてるのをただ見てるだけなんて…",
  ui_story_5089_50890501_25_dialog_content = "だから、このゴタゴタが解決したら一緒に行こう。",
  ui_story_5089_50890501_26_dialog_content = "ワガママな郡主様に文句の一つや二つ言ってやらなきゃ！",
  ui_story_5089_50890501_27_dialog_content = "PlayerName様…",
  ui_story_5089_50890501_28_dialog_content = "ただその前に力を貸してくれない？",
  ui_story_5089_50890501_29_dialog_content = "僕一人じゃできることは少ないんだ。",
  ui_story_5089_50890501_30_dialog_content = "私は幼い頃より鄴王殿下の元で育ち、\n刀を振るい、命令に忠実たることにのみ努めてきました。",
  ui_story_5089_50890501_31_dialog_content = "かような私でもお力になれるというのならば、\nPlayerName様、どうぞご下命を。",
  ui_story_5089_50890501_32_dialog_content = "じゃあ、まずは命令とかそういう考え方はやめて。\nその代わり…",
  ui_story_5089_50890501_33_dialog_content = "僕たちは「共に助け合う友だち」なんだってことを覚えておいて。",
  ui_story_5089_50890501_34_dialog_content = "…私に友などいたことはありません。",
  ui_story_5089_50890501_35_dialog_content = "タンドウが今の言葉を聞いたら、きっと僕より怒ると思うよ。",
  ui_story_5089_50890501_36_dialog_content = "殿下は郡主様であらせられます。\n私のような者が友など…もってのほか！うっ――",
  ui_story_5089_50890501_37_dialog_content = "はぁ、もう…とにかくまずはここを出よう。\n無理はしないでね。僕につかまってゆっくり進むんだ。",
  ui_story_5089_50890501_38_dialog_content = "一緒に王都へ行こう。",
  ui_story_5089_50890502_1_dialog_content = "グアォオオ――",
  ui_story_5089_50890502_2_dialog_content = "PlayerName様、妖魔はすべて片付けました。",
  ui_story_5089_50890502_3_dialog_content = "街からそう遠くない所まで来たんだよね？",
  ui_story_5089_50890502_4_dialog_content = "王都まであと1時間ほどで到着いたします。\n周りには村も多く点在しております。",
  ui_story_5089_50890502_5_dialog_content = "でも…龍州は毎年邪気祓いをしてるから、\n人が暮らす所に暗鬼は出ないんじゃなかったの？",
  ui_story_5089_50890502_6_dialog_content = "それは…",
  ui_story_5089_50890502_7_dialog_content = "前にテンカンも暗鬼に襲われたって言ってた。",
  ui_story_5089_50890502_8_dialog_content = "ただの偶然だといいけど…\nとにかく今はできるだけ面倒を避けたいし、先を急ごう。",
  ui_story_5089_50890502_9_dialog_content = "はい。",
  ui_story_5089_50890502_10_dialog_content = "そっちに何かあるの？",
  ui_story_5089_50890502_11_dialog_content = "？",
  ui_story_5089_50890502_12_dialog_content = "さっきからずっと向こうを見てる気がして。",
  ui_story_5089_50890502_13_dialog_content = "あちらには私が幼い頃暮らしていた村があるのです。",
  ui_story_5089_50890502_14_dialog_content = "キュウの故郷ってこと？ちょっと寄ってから行こうか？",
  ui_story_5089_50890502_15_dialog_content = "いいえ、その必要はありません。\n家族はもうおりませんし、村の方々とも深い親交があるわけではないので。",
  ui_story_5089_50890502_16_dialog_content = "村にはボロ家が残っているだけで、それももう家とは呼べません。",
  ui_story_5089_50890502_17_dialog_content = "今やるべき事に集中しましょう。",
  ui_story_5089_50890502_18_dialog_content = "ご覧ください。\nこの先に見えるのが鄴の国の王都「璟良（けいりょう）」です。",
  ui_story_5089_50890502_19_dialog_content = "…",
  ui_story_5089_50890502_20_dialog_content = "（済の国のきらびやかな王宮を見た後は、\nどんな光景を見ても驚くことはないだろうって思ってた…）",
  ui_story_5089_50890502_21_dialog_content = "（でも、この璟良城はすごい…屋根に飾られた龍のカラクリが雲を吐き、\n銅製の鳳凰が宙を飛び交って、街じゅうに情報を伝えてる）",
  ui_story_5089_50890502_22_dialog_content = "<color=#e8d9bb>道が縦横無尽に走り、幾千もの工房が立ち並んでいる。\n多くの人々が行き交い、あちこちから人の声や物作りの音が聞こえてくる</color>",
  ui_story_5089_50890502_23_dialog_content = "<color=#e8d9bb>皓津のように金や宝石と美しい動植物に彩られたきらびやかさとは違い、\n街じゅうに広がる金属色がこの国の工業の力を見せつけている</color>",
  ui_story_5089_50890502_24_dialog_content = "<color=#e8d9bb>ドドドド……</color>",
  ui_story_5089_50890502_25_dialog_content = "何の音！？",
  ui_story_5089_50890502_26_dialog_content = "火龍輿です。",
  ui_story_5089_50890502_27_dialog_content = "PlayerName様、この街の地面には、\n変わった点があることにお気づきになりませんか？",
  ui_story_5089_50890502_28_dialog_content = "地面に埋め込まれてる金属のレールのこと？\nここに来るまでにも何度か見かけた気がするけど…",
  ui_story_5089_50890502_29_dialog_content = "どこかで見たような…\n僕も知ってる何かに似てる…",
  ui_story_5089_50890502_30_dialog_content = "火龍輿は何年も前に朝廷の「候風」という大臣が造ったカラクリ車です。",
  ui_story_5089_50890502_31_dialog_content = "水と火が互いに影響し合い生まれる力を動力源として、\n大量の貨物を載せた状態でも走行することができるのです。",
  ui_story_5089_50890502_32_dialog_content = "ただ動力源の消耗が激しいことが欠点でして、\nしかもこうした専用の軌道の上しか走れません。",
  ui_story_5089_50890502_33_dialog_content = "ですから、今は王宮がほぼ一手にその建設計画を担い、\n大きな工房の主が出資して建設を進めております。",
  ui_story_5089_50890502_34_dialog_content = "軌道の建設を請け負う工房は優先的に火龍輿を借用し、\n資材の運搬に使えることになっています。",
  ui_story_5089_50890502_35_dialog_content = "やっぱり！蒸気機関車だね！？",
  ui_story_5089_50890502_36_dialog_content = "それは何ですか？",
  ui_story_5089_50890502_37_dialog_content = "アストラにも同じような物があるんだよ。\nでも1人であんなものを造るなんて、候風さんって大臣はすごいなぁ。",
  ui_story_5089_50890502_38_dialog_content = "郡主殿下も同じことをおっしゃっていました。",
  ui_story_5089_50890502_39_dialog_content = "卿の造り出した物から見るに、候風卿は極めて優秀な人物であり、\nその才能はセンキョク様に勝るとも劣らないだろうと。",
  ui_story_5089_50890502_40_dialog_content = "しかも聞いたところでは、\n候風卿はかつて人を載せて飛ぶ巨大なワシを試作したことがあるとか…",
  ui_story_5089_50890502_41_dialog_content = "ただ残念なことに、卿は派閥争いに巻き込まれ、罪人となり、\n行方知れずとなったため、研究も止まってしまいました。",
  ui_story_5089_50890502_42_dialog_content = "それは残念だな。\n研究を続けてれば、きっとものすごい物が出来てただろうに…",
  ui_story_5089_50890502_43_dialog_content = "それにしてもキュウは色々と詳しいんだね。\nこういう事には興味がないのかと思ってた。",
  ui_story_5089_50890502_44_dialog_content = "タンドウ殿下がおっしゃっていたのです。",
  ui_story_5089_50890502_45_dialog_content = "当時もし殿下がすでに成人されており、政にも明るかったならば、\n候風卿を留めておいたのに、と。",
  ui_story_5089_50890502_46_dialog_content = "ははは、タンドウらしいね。",
  ui_story_5089_50890502_47_dialog_content = "よし！じゃあ僕たちも頑張らなきゃ！",
  ui_story_5089_50890502_48_dialog_content = "鄴の国がセンキョクみたいな優秀な人材と\n国のために尽力を惜しまない郡主様を失わないように！",
  ui_story_5089_50890502_49_dialog_content = "まずは何とかして2人に会わないと…",
  ui_story_5089_50890502_50_dialog_content = "鄴王殿下が自ら命を下し、捕らえられた罪人は、\n通常王宮外縁の天牢に入れられます。",
  ui_story_5089_50890502_51_dialog_content = "厳重な警備が敷かれていますが、PlayerName様の力をお借りできるならば、\n牢内で果てようとも私が必ずセンキョク様を助け出してみせます。",
  ui_story_5089_50890502_52_dialog_content = "ええっ…いきなりそんな過激な方法でいくの！？",
  ui_story_5089_50890502_53_dialog_content = "PlayerName様が私の力を借りたいとおっしゃったのは、\nそういう意味ではないのですか？",
  ui_story_5089_50890502_54_dialog_content = "まさか！朝廷を敵に回すつもりはないし、\n君に命の危険を冒させるつもりもないよ！",
  ui_story_5089_50890502_55_dialog_content = "きっと他に方法があるはずだよ。\nとにかくまずはその天牢とかいう所へ行ってみよう。",
  ui_story_5089_50890502_56_dialog_content = "もし向こうがセンキョクを傷つけるようなら…\nその時は最後の手段も考えよう…",
  ui_story_5089_50890502_57_dialog_content = "それはそうと、璟良にはキュウを知ってる人もたくさんいるんだよね。",
  ui_story_5089_50890502_58_dialog_content = "鄴王殿下のおそばにいた時も影で護衛するのが私の務めでした。\n顔を出すことはほとんどなく、接触があったのは同僚くらいです。",
  ui_story_5089_50890502_59_dialog_content = "しかも同僚の多くもこの面しか覚えていないでしょう。\n男か女かも知らないかもしれません。",
  ui_story_5089_50890502_60_dialog_content = "何しろ皆は陰で私を「鬼面閻羅」と呼んでいましたから。",
  ui_story_5089_50890502_61_dialog_content = "ですから、ご心配とあらば…",
  ui_story_5089_50890502_62_dialog_content = "こうすればよいのです。",
  ui_story_5089_50890502_63_dialog_content = "うん、そうだね…ある意味その方が目立つとは思うけど。",
  ui_story_5089_50890502_64_dialog_content = "やはりお見苦しいですか…\nすぐに顔を覆う布を探してまいりましょう。",
  ui_story_5089_50890502_65_dialog_content = "いやいや大丈夫だって！もうっ…どうしてそんなふうに考えるかな？\n逆だよ、逆！君の顔はその…すごく…",
  ui_story_5089_50890502_66_dialog_content = "きれいだ。",
  ui_story_5089_50890502_67_dialog_content = "？",
  ui_story_5089_50890502_68_dialog_content = "い、いいから…気にしないで。急ごう。",
  ui_story_5089_50890502_69_dialog_content = "ここは王宮だ。用のない者は立ち去れ。",
  ui_story_5089_50890502_70_dialog_content = "やっぱり正面から入るのは無理だね。",
  ui_story_5089_50890502_71_dialog_content = "では、私がひそかに潜入し…",
  ui_story_5089_50890502_72_dialog_content = "だから、それは最後の手段なんだって…",
  ui_story_5089_50890502_73_dialog_content = "そうだ、センキョクのカラクリ鳥を持ってきてたんだ。\n警備兵をここから引き離せたら、カラクリ鳥で連絡を取れるかもしれない。",
  ui_story_5089_50890502_74_dialog_content = "では、私が警備兵を――",
  ui_story_5089_50890502_75_dialog_content = "待って！大変だ！",
  ui_story_5089_50890502_76_dialog_content = "<color=#e8d9bb>カラクリ鳥がほんの一瞬気を抜いた隙に、手から離れてしまった</color>",
  ui_story_5089_50890502_77_dialog_content = "<color=#e8d9bb>そして前もって設定していた通り、\nセンキョクを探しにまっすぐ宮殿の門へ向かって飛んで行った――</color>",
  ui_story_5089_50890502_78_dialog_content = "お、終わった…って、あれ？",
  ui_story_5089_50890502_79_dialog_content = "<color=#e8d9bb>どこからともなく一筋の金色の光が射した</color>",
  ui_story_5089_50890502_80_dialog_content = "<color=#e8d9bb>2名の警備兵は何も気づいていない様子で、\nカラクリ鳥はそのまま門の上を越えて行く</color>",
  ui_story_5089_50890502_81_dialog_content = "…警備兵を引き離しますか？",
  ui_story_5089_50890502_82_dialog_content = "いや…",
  ui_story_5089_50890502_83_dialog_content = "<color=#e8d9bb>宮殿の門の中から突然大きな音が聞こえてきた</color>",
  ui_story_5089_50890502_84_dialog_content = "失礼ですが、PlayerName様でございますか？",
  ui_story_5089_50890502_85_dialog_content = "あなたは？",
  ui_story_5089_50890502_86_dialog_content = "どうぞこちらへ。",
  ui_story_5089_50890502_87_dialog_content = "センキョク様がお待ちです。",
  ui_story_5089_50890502_88_dialog_content = "PlayerName、お久しぶり。春新節以来じゃない？",
  ui_story_5089_50890502_89_dialog_content = "キュウさんもお久しぶり。元気にしてた？",
  ui_story_5089_50890502_90_dialog_content = "それはこっちのセリフだよ。\n大丈夫？元気にしてた？ひどい仕打ちを受けてたりしない？",
  ui_story_5089_50890502_91_dialog_content = "もちろん大丈夫…って、もうっ。\n柵がジャマね。外しちゃいましょ。",
  ui_story_5089_50890502_92_dialog_content = "…えっ？",
  ui_story_5089_50890502_93_dialog_content = "さあさあ、入って。座って話すとしましょ。\n2人ともお昼ご飯食べてないでしょ？ちょうどよかった。",
  ui_story_5089_50890502_94_dialog_content = "チエ、チコ。ちょっと尚膳局に行ってきて。",
  ui_story_5089_50890502_95_dialog_content = "この前桔杆卿と賭けをして、私が勝ったの。\n今日お魚が届いてるはずだから…",
  ui_story_5089_50890502_96_dialog_content = "蒸し魚を作ってもらって。",
  ui_story_5089_50890502_97_dialog_content = "はい。",
  ui_story_5089_50890502_98_dialog_content = "センキョク…どういうこと…？",
  ui_story_5089_50890502_99_dialog_content = "ああ、ごめんなさい。宮殿内は何もかも素晴らしいんだけど、\n食事だけは、なかなか難しくて。",
  ui_story_5089_50890502_100_dialog_content = "…",
  ui_story_5089_50890502_101_dialog_content = "いや…獄破りする覚悟で来たんだけど…\n何だかバカらしくなってきた…",
  ui_story_5089_50890502_102_dialog_content = "君…本当に捕まったの？ここ本当に牢獄？",
  ui_story_5089_50890502_103_dialog_content = "あっははは、もちろんでしょ。\nほら、お酒が空っぽなのに気づかない？",
  ui_story_5089_50890502_104_dialog_content = "曲がりなりにも昔は朝廷で官職に就いてたし、ここではお友達もたくさんできたの。\n門派の同期もいろいろ面倒を見てくれてるしね。",
  ui_story_5089_50890502_105_dialog_content = "大王様がいくら腹を立てていようと、\n正式に罪が決まるまでは、どうこうできやしないわ。",
  ui_story_5089_50890502_106_dialog_content = "ただ一応罪人だから、お酒だけはもらえないのよ。\nだから今日はお茶で我慢して。",
  ui_story_5089_50890502_107_dialog_content = "PlayerName、キュウさん。",
  ui_story_5089_50890502_108_dialog_content = "ここへ来るまで、きっといろいろ大変だったでしょ？\nお茶だけど、敬意を表して乾杯させて。",
  ui_story_5089_50890502_109_dialog_content = "私のこと、気に掛けてくれてありがとう。",
  ui_story_5089_50890502_110_dialog_content = "アストラの旅の最大の収穫は、\n燭陰火じゃなく、大事なお友達だったわけね。",
  ui_story_5089_50890502_111_dialog_content = "そ…そんな、かしこまらないでよ。",
  ui_story_5089_50890502_112_dialog_content = "それより燭陰火が今、誰の手にあるか知ってる？\nそれとタンドウと…",
  ui_story_5089_50890502_113_dialog_content = "シーッ。",
  ui_story_5089_50890502_114_dialog_content = "一介の囚人にすぎない私に外の事を話してどうするの？",
  ui_story_5089_50890502_115_dialog_content = "それに見てよ。私は今何不自由ない生活をしてるのよ。\n気ままで楽しすぎて、国がどうとか、どうでもよくなっちゃったわ。",
  ui_story_5089_50890502_116_dialog_content = "外の事なんて、どうでもいいわ。",
  ui_story_5089_50890502_117_dialog_content = "ウソだよ。",
  ui_story_5089_50890502_118_dialog_content = "あら？",
  ui_story_5089_50890502_119_dialog_content = "ここにはカラクリの部品さえないでしょ？",
  ui_story_5089_50890502_120_dialog_content = "そんな環境にいて君が楽しいなんて、誰が信じるの？",
  ui_story_5089_50890502_121_dialog_content = "あははは、PlayerNameは相変わらずまっすぐね。",
  ui_story_5089_50890502_122_dialog_content = "じゃあ、よく聞いて。",
  ui_story_5089_50890502_123_dialog_content = "私はね、大王様の命で捕まったの。\nだからこの先生きられるかどうかも大王様の意志次第なの。",
  ui_story_5089_50890502_124_dialog_content = "つまり、キュウさんの秀でた武術のおかげで\n牢から出られたとしても罪は消えないってことよ。",
  ui_story_5089_50890502_125_dialog_content = "でもセンキョクはきっと何か知ってるよね？\n僕たちは何をすればいいの？",
  ui_story_5089_50890502_126_dialog_content = "今はまだ「何をするか」を考える時じゃないわ。",
  ui_story_5089_50890502_127_dialog_content = "外で起こってる事にどうこう言える立場じゃないけど、\nこれでも昔は相談役だったから、経験をちょっと分けてあげる。",
  ui_story_5089_50890502_128_dialog_content = "何かを成そうとする時、浅はかで力のない者は策に頼る。",
  ui_story_5089_50890502_129_dialog_content = "でも、最上の策って実は情勢の波に乗ることなの。",
  ui_story_5089_50890502_130_dialog_content = "情勢の波に乗れば、天の助けが得られる。",
  ui_story_5089_50890502_131_dialog_content = "ただし前提は広い視野をもって、\n密かにやってくる波の動向をきちんと見極めること。",
  ui_story_5089_50890502_132_dialog_content = "それでようやく「波」が来た時、うまく乗れるのよ。",
  ui_story_5089_50890502_133_dialog_content = "ひとたび起動装置を入れれば、きっちり動くカラクリみたいにね。",
  ui_story_5089_50890502_134_dialog_content = "しごく簡単な動きも、いくつもの構造が同時に動かなきゃ、\n正しい動きはしてくれない。",
  ui_story_5089_50890502_135_dialog_content = "小さな部品が一つ動かなくなっただけでも、\nカラクリは動かなくなるの。",
  ui_story_5089_50890502_136_dialog_content = "でも…僕には何を見ればいいのかさえ分からない…",
  ui_story_5089_50890502_137_dialog_content = "だったら近くを見てみれば？",
  ui_story_5089_50890502_138_dialog_content = "たとえば、今2人が私の前にいるのは偶然かしら？",
  ui_story_5089_50890502_139_dialog_content = "！",
  ui_story_5089_50890502_140_dialog_content = "それから、キュウさんとは以前から知り合いだけど…",
  ui_story_5089_50890502_141_dialog_content = "キュウさんがどこの人か、知ってる？",
  ui_story_5089_50890502_142_dialog_content = "センキョク様、お料理の準備ができました。",
  ui_story_5089_50890502_143_dialog_content = "ただ…今さっき大王様の影の護衛が見えまして、\n何やらものすごい勢いでセンキョク様をお呼びになっています。",
  ui_story_5089_50890502_144_dialog_content = "チコが今足止めしておりますが、そう長くは…",
  ui_story_5089_50890502_145_dialog_content = "分かったわ。",
  ui_story_5089_50890502_146_dialog_content = "どうして明日でも明後日でもなく、今日なのかしらね。",
  ui_story_5089_50890502_147_dialog_content = "PlayerNameとキュウさんに食事を振る舞えなくなったじゃない。",
  ui_story_5089_50890502_148_dialog_content = "はぁ…でも仕方ないわ。",
  ui_story_5089_50890502_149_dialog_content = "…センキョク、やっぱり僕たちと一緒に行こう。",
  ui_story_5089_50890502_150_dialog_content = "ここへ来る前に見たんだ。\n鄴王様の部下とテイトが一緒にいた。だから…",
  ui_story_5089_50890502_151_dialog_content = "チエ、お客様をお送りして。",
  ui_story_5089_50890502_152_dialog_content = "センキョク！",
  ui_story_5089_50890502_153_dialog_content = "いいから急いで。私には片付けなきゃいけない面倒事があるし、\nあなたにもやらなきゃいけない事があるでしょ？",
  ui_story_5089_50890502_154_dialog_content = "PlayerName、信じてるわよ。",
  ui_story_5089_50890502_155_dialog_content = "あなたならきっと「波」を見極められる。",
  ui_story_5089_50890601_1_dialog_content = "<color=#e8d9bb>チエは馬車で僕たちを城外に送ると、また戻って行った</color>",
  ui_story_5089_50890601_2_dialog_content = "結局また2人になっちゃったね。",
  ui_story_5089_50890601_3_dialog_content = "センキョクの言ってたこと…どういう意味だったんだろう…",
  ui_story_5089_50890601_4_dialog_content = "<color=#e8d9bb>グゥ～…</color>",
  ui_story_5089_50890601_5_dialog_content = "…",
  ui_story_5089_50890601_6_dialog_content = "そういえば、今日はまだ何も食べてなかったね。",
  ui_story_5089_50890601_7_dialog_content = "村の人に食事を作ってもらえないか聞いてきましょう。",
  ui_story_5089_50890601_8_dialog_content = "PlayerName様、ここで少々お待ちください。",
  ui_story_5089_50890601_9_dialog_content = "うん…あ、え？",
  ui_story_5089_50890601_10_dialog_content = "この辺りに村なんてあるの？",
  ui_story_5089_50890601_11_dialog_content = "ここんとこ米が値上がりしててねぇ。いい機会だってんで家にあったマシな穀物は\n全部通りがかりの済の国の商人に売っちまったんです。",
  ui_story_5089_50890601_12_dialog_content = "家に少し残ってた古米で粥を作ってはみたが、\nお二人みてえな貴人様のお口に合うかどうか…",
  ui_story_5089_50890601_13_dialog_content = "気にしないでください。\n何も食べてなかったので、食べ物をいただけるだけでありがたいです。",
  ui_story_5089_50890601_14_dialog_content = "そちらの方はお座りにならねえんで？\n何かお気に召さねぇ事でもありましたかねぇ？",
  ui_story_5089_50890601_15_dialog_content = "私は結構です。",
  ui_story_5089_50890601_16_dialog_content = "少しでも食べないと、身体が持たないよ。",
  ui_story_5089_50890601_17_dialog_content = "大丈夫です。以前任務で3日間何も食べなかったことがありましたが、\n刀を振るうのに問題はありませんでした。",
  ui_story_5089_50890601_18_dialog_content = "それに私は夜叉のような顔をしているので、\n周りの方を怖がらせてしまいます。",
  ui_story_5089_50890601_19_dialog_content = "ええっと、だからそれは…",
  ui_story_5089_50890601_20_dialog_content = "その台詞…それに、その面…まさか…きゅうちゃんかい？",
  ui_story_5089_50890601_21_dialog_content = "え？",
  ui_story_5089_50890601_22_dialog_content = "…はい。",
  ui_story_5089_50890601_23_dialog_content = "ご無沙汰しております、李じい様。",
  ui_story_5089_50890601_24_dialog_content = "おお、よかった、生きてたか！",
  ui_story_5089_50890601_25_dialog_content = "お父ちゃんもお母ちゃんもひどい死に方したろう？\nお役人まで死んじまったし、みんなお前さんもきっと駄目だろうって…",
  ui_story_5089_50890601_26_dialog_content = "あん時はいくつだったかねぇ。こんなに大きくなって…",
  ui_story_5089_50890601_27_dialog_content = "女の子一人で、さぞかし苦労したろう…",
  ui_story_5089_50890601_28_dialog_content = "ある恩人に助けられ、元気に暮らしておりました。",
  ui_story_5089_50890601_29_dialog_content = "そうか…それはよかった、本当によかった…",
  ui_story_5089_50890601_30_dialog_content = "ちょっと待ってるんだよ。\nじい様が今漬物を持ってきてやるからねぇ。お前さんも座って食べな。",
  ui_story_5089_50890601_31_dialog_content = "ここってキュウの故郷だったんだ！",
  ui_story_5089_50890601_32_dialog_content = "そうとも言えるでしょう。",
  ui_story_5089_50890601_33_dialog_content = "もともとはさらに片田舎の村に住んでいたのです。\nここへは禍を避けるために越してきました。",
  ui_story_5089_50890601_34_dialog_content = "禍？",
  ui_story_5089_50890601_35_dialog_content = "当時はまだ10歳にもならなかったので、詳しいことはあまり覚えていません。",
  ui_story_5089_50890601_36_dialog_content = "確か変わった趣味の高官が私の顔を見て気に入り、\n側に置くため、大金で買おうと持ち掛けてきたのです。",
  ui_story_5089_50890601_37_dialog_content = "しかし父と母が断ったところ、\n幾度となく嫌がらせを受けるようになり、この村に逃れてきました。",
  ui_story_5089_50890601_38_dialog_content = "それ以降、父と母は私に面をかぶらせるようになりました。\n周りには夜叉のような顔をしているからだと言うよう教えられました。",
  ui_story_5089_50890601_39_dialog_content = "そんな…",
  ui_story_5089_50890601_40_dialog_content = "構いません。面をかぶるようになったおかげで、家族に迷惑をかけずに済みましたし、\n私自身あまり人と話すのが得意ではないので。",
  ui_story_5089_50890601_41_dialog_content = "ただ父と母がいつも申し訳なさそうにしていました。",
  ui_story_5089_50890601_42_dialog_content = "村の子どもたちに夜叉だの、バケモノだのと言われるたび、\n母は私を抱きしめ、歌を歌ってくれました。",
  ui_story_5089_50890601_43_dialog_content = "父も自分は滅多に食べない瓜を食べさせてくれました。",
  ui_story_5089_50890601_44_dialog_content = "あ、キュウが前に歌ってた歌…？あれは君のために作った歌だったんだね。\nお父さんもお母さんも君のことを本当に大切に思ってたんだね。",
  ui_story_5089_50890601_45_dialog_content = "その後どうなったの？",
  ui_story_5089_50890601_46_dialog_content = "PlayerName様もご覧になったでしょう？\nこの村の西側に山があります。",
  ui_story_5089_50890601_47_dialog_content = "ええと…どの山？",
  ui_story_5089_50890601_48_dialog_content = "外で話しましょう。",
  ui_story_5089_50890601_49_dialog_content = "きゅうちゃん…もう行っちまうのかい？",
  ui_story_5089_50890601_50_dialog_content = "鉱山を見に行ってまいります。",
  ui_story_5089_50890601_51_dialog_content = "そうかい。でもあそこはとっくに採掘をやめてね。\n労働者収容施設もなくなっちまったよ。",
  ui_story_5089_50890601_52_dialog_content = "跡地に大きな工房が出来たんだが、何を作っているのやら。",
  ui_story_5089_50890601_53_dialog_content = "村の若いもんが働き手を募集してないか聞きに行ったんだが、人っ子一人いなかったらしくてね。\nおそらく廃墟になってるんだろう、何も見るもんはないよ。",
  ui_story_5089_50890601_54_dialog_content = "ただね、きゅうちゃん…",
  ui_story_5089_50890601_55_dialog_content = "はい、何でしょう？",
  ui_story_5089_50890601_56_dialog_content = "い、いやね…ここんとこ、みんな暮らしがきつくてねぇ。",
  ui_story_5089_50890601_57_dialog_content = "お前さんはちゃんとやってるようじゃないか。しっかり生きていくんだよ。",
  ui_story_5089_50890601_58_dialog_content = "お父ちゃんもお母ちゃんも草葉の陰から見守ってるよ。",
  ui_story_5089_50890601_59_dialog_content = "…はい。",
  ui_story_5089_50890601_60_dialog_content = "さっき言ってた山って、あのハゲ山のこと？",
  ui_story_5089_50890601_61_dialog_content = "はい。今の鄴王殿下が即位される前、\n鉱山を含む辺り一帯は鄴王殿下の領地でした。",
  ui_story_5089_50890601_62_dialog_content = "麓に労働者収容施設を造り、家を失った者や罪人を集めて働かせていたのです。",
  ui_story_5089_50890601_63_dialog_content = "ある日2人の兵士が死刑囚を収容施設に押送しにきたのですが、\n途中疲労もあってか、怠け癖が出て、私の家に泊まることになりました。",
  ui_story_5089_50890601_64_dialog_content = "父と母は彼らをもてなすため、家にあった食糧をお酒に換えました。\nそれだけでなく、押送中の死刑囚にも食事を運ぶよう言われました。",
  ui_story_5089_50890601_65_dialog_content = "挙句の果てには、酔った彼らは顔を見ようと無理やり私の面を引きはがし、\nさらには侮辱しようとしたのです。",
  ui_story_5089_50890601_66_dialog_content = "幸い通りかかった人が気づいて生け垣を倒し、\n兵士2人はその下敷きになって死にました。",
  ui_story_5089_50890601_67_dialog_content = "助けてくれた方は面倒な事に巻き込まれるのが嫌だったのでしょう。\n影に隠れたまま姿を見せず、私もその時は他の事を考える余裕がありませんでした。",
  ui_story_5089_50890601_68_dialog_content = "大変な事になったと、ただそれだけで頭がいっぱいで、\n父と母の元へと急いだのですが…",
  ui_story_5089_50890601_69_dialog_content = "そこにあったのは、血だまりの中に倒れた両親の死体でした。",
  ui_story_5089_50890601_70_dialog_content = "両親の傍らには、こぼれた粥が湯気を立てていて、\nしかし死刑囚の姿はなく…すでに鎖を解いて逃げていたのです。",
  ui_story_5089_50890601_71_dialog_content = "その時思いました。「運命にもてあそばれる」とはこういう事なのだろうと。",
  ui_story_5089_50890601_72_dialog_content = "周りからバケモノだ、妖魔だと罵られ、叩かれた時も、\n恐怖など感じたことはありませんでした。",
  ui_story_5089_50890601_73_dialog_content = "しかしあの日、父と母の遺体を見た時…私は恐怖を感じました。",
  ui_story_5089_50890601_74_dialog_content = "しかし唯一恐怖を感じたあの夜…\n歌を歌ってくれる母がいなくなってしまったのです。",
  ui_story_5089_50890601_75_dialog_content = "申し訳ありません。話が反れてしまいました。\nその後は――",
  ui_story_5089_50890601_76_dialog_content = "キュウ！",
  ui_story_5089_50890601_77_dialog_content = "？",
  ui_story_5089_50890601_78_dialog_content = "辛いなら、無理して話してくれなくていいんだよ。",
  ui_story_5089_50890601_79_dialog_content = "辛くはありません。",
  ui_story_5089_50890601_80_dialog_content = "センキョク様の言葉の真意は分かりかねますが、\nあの方の言葉には必ず何か意味があると思うのです。",
  ui_story_5089_50890601_81_dialog_content = "そのセンキョク様が私の出身について触れたからには、\nお話しするべきだと思います。",
  ui_story_5089_50890601_82_dialog_content = "取り留めのない話を聞いてくださって、ありがとうございます。",
  ui_story_5089_50890601_83_dialog_content = "…そんな話…辛くないはずないよ。",
  ui_story_5089_50890601_84_dialog_content = "もし本当にまったく気にしてないなら…",
  ui_story_5089_50890601_85_dialog_content = "地面にこぼれたお粥がまだ湯気を立ててたことを\n今も覚えてるはずない…",
  ui_story_5089_50890601_86_dialog_content = "PlayerName様…怒っているのですか？",
  ui_story_5089_50890601_87_dialog_content = "ちゃんと分かるんだね。",
  ui_story_5089_50890601_88_dialog_content = "そうだよ、すごく怒ってる。",
  ui_story_5089_50890601_89_dialog_content = "申し訳ありません。不愉快な話でした。",
  ui_story_5089_50890601_90_dialog_content = "しかし…その後すぐに仇を討てました。",
  ui_story_5089_50890601_91_dialog_content = "私は兵士が身に付けていた小太刀を手に取り、\n一晩中死刑囚を追いました。",
  ui_story_5089_50890601_92_dialog_content = "結果、その者はなんと鉱山の収容施設に押し入り、\n当時の鄴王殿下を殺めようとしたのです。",
  ui_story_5089_50890601_93_dialog_content = "しかし私が追いついた時には、死刑囚はすでに処刑されていました。",
  ui_story_5089_50890601_94_dialog_content = "鄴王殿下はなぜ死刑囚を追ってきたのかとお尋ねになり、家族を失ったことを知ると、\n私を引き取ってくださいました。その時「キュウ」という名を賜ったのです。",
  ui_story_5089_50890601_95_dialog_content = "代わりに仇を討ってくださっただけでなく、\n王府に迎え、学問と武芸を授けてくださいました。",
  ui_story_5089_50890601_96_dialog_content = "ですから、どうあってもご恩に報いなければなりません。",
  ui_story_5089_50890601_97_dialog_content = "それ以外に私には刀を振る理由も…生きていく理由もないのです。",
  ui_story_5089_50890601_98_dialog_content = "僕が言ってるのはその事じゃないよ。",
  ui_story_5089_50890601_99_dialog_content = "仇を討つとか、恩に報いるとか、君はそればっかりだけど…",
  ui_story_5089_50890601_100_dialog_content = "君自身の気持ちはどうなの？やりたいこと、本当に一つもないの？",
  ui_story_5089_50890601_101_dialog_content = "僕の代わりに攻撃を受けたり、淡々と獄破りを買って出たり、\n自分の気持ちは重要じゃないって思ってることも…",
  ui_story_5089_50890601_102_dialog_content = "どうしてキュウはいつも、\n自分が犠牲になることを当たり前みたいに言うの？",
  ui_story_5089_50890601_103_dialog_content = "いくら強くても君は機械じゃない。ケガもするし、痛みも感じる、辛いって思うことだってある。\nほんの少しの不注意で命を落とすことだってあるんだ。",
  ui_story_5089_50890601_104_dialog_content = "さようなことを考えたことはありません。\n私はただ任務を果たすためならば…",
  ui_story_5089_50890601_105_dialog_content = "分かった、もういいよ。\n君とどう話せばいいのか、やっと分かってきた気がする。",
  ui_story_5089_50890601_106_dialog_content = "ごめん、タンドウ。僕が間違ってた。\nキュウがどんなに頑固者か、僕も今身に染みて分かったよ。",
  ui_story_5089_50890601_107_dialog_content = "じゃあ今から君にもよく分かる方法で話すね。",
  ui_story_5089_50890601_108_dialog_content = "？",
  ui_story_5089_50890601_109_dialog_content = "君のその自分を顧みない自己犠牲の精神には、\nほとほと困り果ててる。",
  ui_story_5089_50890601_110_dialog_content = "空の末裔は平和を愛する種族なんだ。\nだから血を見るのは嫌だ。君が傷つくところも見たくない。",
  ui_story_5089_50890601_111_dialog_content = "傷一つないまま、君をタンドウの所へ返したい。",
  ui_story_5089_50890601_112_dialog_content = "だから、まだ僕の命令を聞く気があるなら、\nこれから言う事を必ず守って。",
  ui_story_5089_50890601_113_dialog_content = "「どんな状況でも、まずは自分を守ること」。",
  ui_story_5089_50890601_114_dialog_content = "それは…",
  ui_story_5089_50890601_115_dialog_content = "今「はい」以外の答えは聞きたくないし、必要もない。",
  ui_story_5089_50890601_116_dialog_content = "はい、肝に銘じます。",
  ui_story_5089_50890601_117_dialog_content = "ただ…その御命令に期限はあるのでしょうか？",
  ui_story_5089_50890601_118_dialog_content = "もうっ…まだ分からないの？",
  ui_story_5089_50890601_119_dialog_content = "まあ、仕方ないか。期限か…そうだな…",
  ui_story_5089_50890601_120_dialog_content = "君が「恩返しや仇討ちのために刀を振るうことがなくなるまで」にしよう。",
  ui_story_5089_50890601_121_dialog_content = "はい？",
  ui_story_5089_50890601_122_dialog_content = "異論は認めないよ。",
  ui_story_5089_50890601_123_dialog_content = "いいえ、今の言葉は昔師匠にも言われたことがあります。",
  ui_story_5089_50890601_124_dialog_content = "師匠？",
  ui_story_5089_50890601_125_dialog_content = "私は天下一の剣客に剣術を学びました。",
  ui_story_5089_50890601_126_dialog_content = "師匠は私を頑固者だと言い、正式な弟子にはしてくださいませんでしたが、\n多くの事を教えてくださいました。",
  ui_story_5089_50890601_127_dialog_content = "ただ師匠自ら考案した、山をも拓き海をも分かつと言われた「驚霆剣（きょうていけん）」だけは\nどうしても教えてくださいませんでした。",
  ui_story_5089_50890601_128_dialog_content = "師匠いわく、実の技ではなく、教えられないのだ、と。",
  ui_story_5089_50890601_129_dialog_content = "私が恩返しや仇討ち以外の目的で刀剣を振るうようになった時、\nようやくその技が何たるか分かるだろうともおっしゃいました。",
  ui_story_5089_50890601_130_dialog_content = "何だかずいぶん謎めいてるね。他に手がかりは…うぐっ！？",
  ui_story_5089_50890601_131_dialog_content = "申し訳ありません。誰か来ました。",
  ui_story_5089_50890601_132_dialog_content = "うっ…テイト！？",
  ui_story_5089_50890601_133_dialog_content = "どうしてここに…？キュウ、付いていこう！",
  ui_story_5089_50890601_134_dialog_content = "工房の中に入ったの？じゃあ僕たちも――",
  ui_story_5089_50890601_135_dialog_content = "グア！",
  ui_story_5089_50890601_136_dialog_content = "カラクリ獣だ！キュウ、気を付けて！",
  ui_story_5089_50890602_1_dialog_content = "この工房って廃墟になったんじゃ…\nどうしてこんなに厳重な警備がしかれてるの？",
  ui_story_5089_50890602_2_dialog_content = "しかも、かなり大勢の人が活動した痕跡がある。\nそこにテイトまで現れたとなると…",
  ui_story_5089_50890602_3_dialog_content = "おそらく天命を受けし者の拠点だろうね。",
  ui_story_5089_50890602_4_dialog_content = "お気を付けください。ここはかなり大きな工房のようです。\n地下も広く、通路がかなり入り組んでおります。",
  ui_story_5089_50890602_5_dialog_content = "一度迷えば、面倒な事になります。",
  ui_story_5089_50890602_6_dialog_content = "ふふん、僕はこういう建物には慣れっこなんだ。\n感知能力で道を探ればいい。",
  ui_story_5089_50890602_7_dialog_content = "感知――",
  ui_story_5089_50890602_8_dialog_content = "！！武器がたくさん保管されてる！",
  ui_story_5089_50890602_9_dialog_content = "いったい何を企んでるの…あれ？",
  ui_story_5089_50890602_10_dialog_content = "この先の隅の部屋に誰か閉じ込められてるみたい。",
  ui_story_5089_50890602_11_dialog_content = "！",
  ui_story_5089_50890602_12_dialog_content = "<color=#e8d9bb>中に入った瞬間、ひどい悪臭が襲ってきた</color>",
  ui_story_5089_50890602_13_dialog_content = "<color=#e8d9bb>隅に縮こまっていた人影はぶるっと身を震わせ、\nさらに壁際に寄って縮こまった</color>",
  ui_story_5089_50890602_14_dialog_content = "周りの状態からして、\nかなり長いこと閉じ込められてるみたいだ。",
  ui_story_5089_50890602_15_dialog_content = "あの…あなたは誰ですか？どうして閉じ込められてるんですか？",
  ui_story_5089_50890602_16_dialog_content = "ああ…あ…",
  ui_story_5089_50890602_17_dialog_content = "うう…ははは…うわああああ――",
  ui_story_5089_50890602_18_dialog_content = "ダメだ、話が通じない。精神に問題があるみたいだ…",
  ui_story_5089_50890602_19_dialog_content = "まずは奥に進んで、この工房を調べよう。\nそれからこの人を助け出す方法を考えて…",
  ui_story_5089_50890602_20_dialog_content = "キュウ？どうしたの？行くよ。",
  ui_story_5089_50890602_21_dialog_content = "な、なぜ…なぜここに…",
  ui_story_5089_50890602_22_dialog_content = "鄴王殿下！",
  ui_story_5089_50890602_23_dialog_content = "え…？この人、鄴王様なの…！？",
  ui_story_5089_50890700_1_dialog_content = "<color=#e8d9bb>翌日</color>",
  ui_story_5089_50890700_2_dialog_content = "…殿下、タンドウ殿下？",
  ui_story_5089_50890700_3_dialog_content = "ん？何用じゃ？",
  ui_story_5089_50890700_4_dialog_content = "いやいやいや、殿下が芳澤郡主と韶欽郡主の近況を調べるようおっしゃったんでしょう？",
  ui_story_5089_50890700_5_dialog_content = "ああ、そうじゃったな。\n2人とも元気にしておったか？",
  ui_story_5089_50890700_6_dialog_content = "それがですね、少し前にお二人とも鄴王から先祖を祭るよう命を受けたらしく、\nしばらくは離宮で過ごし、璟良には戻らないそうです。",
  ui_story_5089_50890700_7_dialog_content = "やはりな…",
  ui_story_5089_50890700_8_dialog_content = "おや、殿下。朝食も召し上がらず、ずっと考え事ですか？\nせっかくの料理が冷めてしまってますねぇ。",
  ui_story_5089_50890700_9_dialog_content = "食欲がなくてのう。",
  ui_story_5089_50890700_10_dialog_content = "心配事があろうと、お身体を壊しちゃ元も子もありません。",
  ui_story_5089_50890700_11_dialog_content = "それに今は宮殿から出られるわけでもなし、心配したところで何にもなりません。\nPlayerNameのダンナとキュウさんに任せるしかありませんよ。",
  ui_story_5089_50890700_12_dialog_content = "昨日使いの者が2人とも無事だと知らせて来たんでしょう？",
  ui_story_5089_50890700_13_dialog_content = "それとも何ですか、2人を信じられませんか？",
  ui_story_5089_50890700_14_dialog_content = "信じておるに決まっておろう。それよりもお主…",
  ui_story_5089_50890700_15_dialog_content = "早々に逃げ出すものと思うておった…",
  ui_story_5089_50890700_16_dialog_content = "何をおっしゃるんです？\n宮殿では食べる物も寝所も極上なんです。",
  ui_story_5089_50890700_17_dialog_content = "どうも離れがたくなってしまいましてね、今さっきいつまでいられるか占ってみたんです。\n結果、何が出たと思います？",
  ui_story_5089_50890700_18_dialog_content = "卦象によりますとね、殿下には僕が必要らしいんです。",
  ui_story_5089_50890700_19_dialog_content = "キュウの身代わりになるだけでも十分無茶な頼みだというに、\nこの上さらに面倒を掛けることになるのか？",
  ui_story_5089_50890700_20_dialog_content = "此度のことが片付いたら、相応の報酬を――",
  ui_story_5089_50890700_21_dialog_content = "<color=#e8d9bb>ドーン！！</color>",
  ui_story_5089_50890700_22_dialog_content = "何事じゃ！？",
  ui_story_5089_50890700_23_dialog_content = "殿下、何者かが宮廷に侵入しました。\nどうかここから…うっ！",
  ui_story_5089_50890700_24_dialog_content = "テンカン、何をするのじゃ？",
  ui_story_5089_50890700_25_dialog_content = "ほら、僕が必要だったでしょう？",
  ui_story_5089_50890700_26_dialog_content = "あ…あああ…",
  ui_story_5089_50890700_27_dialog_content = "ふわぁ～っ…もう夜が明けたの？",
  ui_story_5089_50890700_28_dialog_content = "一晩中眠れなかった…",
  ui_story_5089_50890700_29_dialog_content = "あ、あああ…",
  ui_story_5089_50890700_30_dialog_content = "はぁ…危険を承知で、夜通し何人ものお医者さんの所を回ったんですけど…",
  ui_story_5089_50890700_31_dialog_content = "どのお医者さんも毒のせいだって言うんです。\nしかも毒が骨の髄まで回ってて、もう手の施しようがないって…",
  ui_story_5089_50890700_32_dialog_content = "うあああ、うう、ああ…",
  ui_story_5089_50890700_33_dialog_content = "本当に鄴王様本人なんですか？もしそうなら…",
  ui_story_5089_50890700_34_dialog_content = "ただの面倒じゃすまない事態です。",
  ui_story_5089_50890700_35_dialog_content = "それに昨日キュウが言ってたこと…\nどうしても嫌な予感がするんです。",
  ui_story_5089_50890700_36_dialog_content = "ここもダメって？",
  ui_story_5089_50890700_37_dialog_content = "キュウ、気を落とすことないよ。他のお医者さんなら何とかできるかもしれない。\nリンセイに手紙を出して聞いてみようよ。",
  ui_story_5089_50890700_38_dialog_content = "もしくはタンドウの言ってた名医の「卜存子」を見つけ出せれば…",
  ui_story_5089_50890700_39_dialog_content = "PlayerName様。",
  ui_story_5089_50890700_40_dialog_content = "もし宮殿にいる鄴王殿下が本物でないとしたら、\nタンドウ殿下はどうなるのでしょう？",
  ui_story_5089_50890700_41_dialog_content = "それは……",
  ui_story_5089_50890700_42_dialog_content = "鄴王殿下に深い恩があるだけでなく、\n私はタンドウ殿下にも本当によくしていただいたのです。",
  ui_story_5089_50890700_43_dialog_content = "殿下自ら護衛の職を解かれたからには、\n私が殿下の事で何か言う資格はないのかもしれません。",
  ui_story_5089_50890700_44_dialog_content = "しかしPlayerName様。\nもし私が殿下をお守りできなくなった時には、どうか…",
  ui_story_5089_50890700_45_dialog_content = "タンドウ殿下をお願いいたします。",
  ui_story_5089_50890700_46_dialog_content = "申し訳ありません。",
  ui_story_5089_50890700_47_dialog_content = "あ、そういえば…キュウはどこ行ったの！？",
  ui_story_5089_50890700_48_dialog_content = "うう…こうなると思ってたんだ。",
  ui_story_5089_50890700_49_dialog_content = "よかった、準備しておいて…",
  ui_story_5089_50890700_50_dialog_content = "李おじいさん！ごめんなさい、この人を少しの間お願いしてもいいですか？",
  ui_story_5089_50890700_51_dialog_content = "ああ？いいことはいいけど、そんなに急いでどこへ行くつもりだい？",
  ui_story_5089_50890700_52_dialog_content = "璟良です！",
  ui_story_5089_50890700_53_dialog_content = "あ、あああ…",
  ui_story_5089_50890700_54_dialog_content = "大王様、刺客が宮殿に押し入り、近衛兵では太刀打ちできません。\n間もなくこちらへやってきます！",
  ui_story_5089_50890700_55_dialog_content = "殿下、刺客は霜刃です。",
  ui_story_5089_50890700_56_dialog_content = "迎え撃ちますか？",
  ui_story_5089_50890700_57_dialog_content = "必要ない。ここで待つとしよう。",
  ui_story_5089_50890700_58_dialog_content = "<color=#e8d9bb>ドーン！</color>",
  ui_story_5089_50890700_59_dialog_content = "止まれ！大王様の御前であるぞ、慎まぬか！",
  ui_story_5089_50890700_60_dialog_content = "どけ。",
  ui_story_5089_50890700_61_dialog_content = "うっ――",
  ui_story_5089_50890700_62_dialog_content = "<color=#e8d9bb>キュウは宮殿に足を踏み入れると、さっと顔を上げ、\n王座に座する者と視線を合わせた</color>",
  ui_story_5089_50890700_63_dialog_content = "ほう、確かに余の育てた刀だ。",
  ui_story_5089_50890700_64_dialog_content = "ここにそちに敵う者は1人もおらぬ。",
  ui_story_5089_50890700_65_dialog_content = "芝居はそこまでにしろ。",
  ui_story_5089_50890700_66_dialog_content = "本物の鄴王殿下に会ってきた。貴様、このまがいものめ――",
  ui_story_5089_50890700_67_dialog_content = "王座から降りろ！",
  ui_story_5089_50890700_68_dialog_content = "ほう、あの呆けに会ったか。",
  ui_story_5089_50890700_69_dialog_content = "<color=#e8d9bb>カンッ――</color>",
  ui_story_5089_50890700_70_dialog_content = "<color=#e8d9bb>刃がぶつかり合う高く鋭い音が響いた</color>",
  ui_story_5089_50890700_71_dialog_content = "鄴王殿下に何たる無礼！",
  ui_story_5089_50890700_72_dialog_content = "ははは、威勢がよいな。",
  ui_story_5089_50890700_73_dialog_content = "さすがは余の麾下一の剣客である。",
  ui_story_5089_50890700_74_dialog_content = "貴様――！",
  ui_story_5089_50890700_75_dialog_content = "皆の者、出てこい。頭に手合わせを願うがよい。",
  ui_story_5089_50890700_76_dialog_content = "はい！",
  ui_story_5089_50890700_77_dialog_content = "<color=#e8d9bb>影の護衛たちが両側から迫り、\n鋭い金属の糸が宙を斬って襲いかかってきた</color>",
  ui_story_5089_50890700_78_dialog_content = "<color=#e8d9bb>キュウは攻撃をかわす瞬間、\n視線の隅で偽物の鄴王が見せたほころびを捉えた</color>",
  ui_story_5089_50890700_79_dialog_content = "――！",
  ui_story_5089_50890700_80_dialog_content = "<color=#e8d9bb>金属の糸がキュウのふくらはぎを貫いた。\nしかしキュウは足を止めることなく、刀を偽物の鄴王の胸に突き刺した！</color>",
  ui_story_5089_50890700_81_dialog_content = "幼き頃の習慣とはなかなか直らぬものだな。",
  ui_story_5089_50890700_82_dialog_content = "<color=#e8d9bb>カンッ――</color>",
  ui_story_5089_50890700_83_dialog_content = "<color=#e8d9bb>鄴王が着物の下に着こんでいた鎖帷子に当たり、刀の勢いが止まる</color>",
  ui_story_5089_50890700_84_dialog_content = "クッ――",
  ui_story_5089_50890700_85_dialog_content = "<color=#e8d9bb>キュウはすぐさま刀を抜き、再び振りかぶった</color>",
  ui_story_5089_50890700_86_dialog_content = "そちの刃は鋭い。だが鋭さは究極まで達した時、\nもろく、砕けやすくなるのだ。",
  ui_story_5089_50890700_87_dialog_content = "そちに「玖（キュウ）」の名を授けたのは、\n無謀な戦いをさせるためではないぞ。",
  ui_story_5089_50890700_88_dialog_content = "！",
  ui_story_5089_50890700_89_dialog_content = "<color=#e8d9bb>10年前――</color>",
  ui_story_5089_50890700_90_dialog_content = "仇を討つため、1人裸足のまま飲まず食わずでここまで追ってきたというのか？",
  ui_story_5089_50890700_91_dialog_content = "はははは、まだ幼いというに、なかなかの気骨の持ち主だ。",
  ui_story_5089_50890700_92_dialog_content = "だがよく見よ。今そちは腹を空かせ、\n手足は血にまみれ、今にも倒れそうである。",
  ui_story_5089_50890700_93_dialog_content = "かような有様では、たとえ仇に追いついたとて、\nせいぜい相打ちであろう。それではいかん。",
  ui_story_5089_50890700_94_dialog_content = "…いや、そうとも言えぬか。\nそちは今や仇を討つ以外に生きる意味を見出せぬのであろう？",
  ui_story_5089_50890700_95_dialog_content = "ならば仕方ない。代わりに仇を討ったついでだ、最後まで面倒を見てやろう。\nそちの命も余が引き受ける。",
  ui_story_5089_50890700_96_dialog_content = "確か「きゅう」と申したな。\nその名に文字を授けてやる。",
  ui_story_5089_50890700_97_dialog_content = "今日から「玉」に「久」と書いて「キュウ」と名乗るがよい。",
  ui_story_5089_50890700_98_dialog_content = "玉のように美しく硬くあり続けるという意味だ。",
  ui_story_5089_50890700_99_dialog_content = "そちには我が剣となってもらおう。これからは己を磨くがよい。\nだが、決してもろくなってはならぬ。",
  ui_story_5089_50890700_100_dialog_content = "<color=#e8d9bb>キュウにわずかな迷いが見えた瞬間、無数の金属の糸が網となり、\nその身体を地に押し付け、捕らえてしまった</color>",
  ui_story_5089_50890700_101_dialog_content = "<color=#e8d9bb>面が地に転げ落ち、キュウはその視線を偽物の鄴王に向けた</color>",
  ui_story_5089_50890700_102_dialog_content = "貴様…いったい何者だ？",
  ui_story_5089_50890700_103_dialog_content = "宮殿に曲者が侵入したってのに、\nなんだって大勢の護衛がここを見張ってるんでしょうかねぇ？",
  ui_story_5089_50890700_104_dialog_content = "突然逃げろと申すゆえ、何か企みでもあるのかと思うたわ。",
  ui_story_5089_50890700_105_dialog_content = "臨機応変も計画ですよ。",
  ui_story_5089_50890700_106_dialog_content = "タンドウ殿下は僕の占いを信じませんがね、\n僕は信じてるんです。",
  ui_story_5089_50890700_107_dialog_content = "PlayerNameのダンナがこの間引いた陰の辰と陰の子の卦象ってのが、\nまさにこの状況と合致してるんです。",
  ui_story_5089_50890700_108_dialog_content = "ただですねぇ、僕の予測が正しければ、PlayerNameのダンナとキュウさんだけじゃ、\nこの窮地は打開できそうもないですねぇ。",
  ui_story_5089_50890700_109_dialog_content = "どういう意味じゃ？",
  ui_story_5089_50890700_110_dialog_content = "僕が警備兵を引き付けますんで、\n殿下はその機に乗じて宮殿から抜け出してください。",
  ui_story_5089_50890700_111_dialog_content = "その後は、臨機応変でお願いしますよ。",
  ui_story_5089_50890700_112_dialog_content = "待て、テンカン！",
  ui_story_5089_50890700_113_dialog_content = "何者だ！",
  ui_story_5089_50890700_114_dialog_content = "追え！",
  ui_story_5089_50890700_115_dialog_content = "テンカンめ、話の途中で立ち去りおって！",
  ui_story_5089_50890700_116_dialog_content = "じゃが今は――",
  ui_story_5089_50890700_117_dialog_content = "郡主殿下、どちらへ行かれるのですか？",
  ui_story_5089_50890700_118_dialog_content = "…",
  ui_story_5089_50890700_119_dialog_content = "センキョク様、外が何やら…",
  ui_story_5089_50890700_120_dialog_content = "静かにして。今取り込み中なの。",
  ui_story_5089_50890700_121_dialog_content = "このような時にまだ瓦をいじっているのですか？",
  ui_story_5089_50890700_122_dialog_content = "これはね、ただの瓦じゃないの。\n私が何日も苦労して造った琉璃瓦のカラクリなのよ。",
  ui_story_5089_50890700_123_dialog_content = "PlayerNameもずいぶん成長したけど、裏のかき合いっこはまだまだねぇ。",
  ui_story_5089_50890700_124_dialog_content = "何の話です？",
  ui_story_5089_50890700_125_dialog_content = "つまり、この牢には一見何のカラクリ部品もないようだけど――",
  ui_story_5089_50890700_126_dialog_content = "真の機巧師の手にかかれば、\n机や椅子、梁も瓦も全てカラクリ部品に一変するってことよ。",
  ui_story_5089_50890700_127_dialog_content = "ほら見て。これは空の末裔に着想を得て、\n牢内にある物だけを使って造った即席カラクリ――「移光霊瓦」よ！",
  ui_story_5089_50890700_128_dialog_content = "ご冗談でしょう？それがいったい何の役に立つのです？",
  ui_story_5089_50890700_129_dialog_content = "これはね、差し込んできた光や光力を、\n自分の好きな場所に導くことができるの。",
  ui_story_5089_50890700_130_dialog_content = "そのような装置、何に使うのですか？",
  ui_story_5089_50890700_131_dialog_content = "そうねぇ、何に使おうかしら？",
  ui_story_5089_50890700_132_dialog_content = "10年前、ある朝廷の高官が政争の末罪人となり、\n死ぬまで鉱山の重労働を強いられることとなった。",
  ui_story_5089_50890700_133_dialog_content = "だが天は彼を見放さなかった。\n押送の役目を仰せつかった兵士らは怠け者で、途中村で宿を取ろうと言い出した。",
  ui_story_5089_50890700_134_dialog_content = "その家の夫婦はごく普通の村人、彼は2人に襲いかかり、\nいともたやすく逃げ出すことができた。",
  ui_story_5089_50890700_135_dialog_content = "だが庭を出ようとした時、\nあの畜生にも劣る兵士らは夫婦の娘を侮辱しようとしていたのだ。",
  ui_story_5089_50890700_136_dialog_content = "そこで彼は事のついでに2人の畜生を片付け、\nその後予定通り、収容施設へと向かった。",
  ui_story_5089_50890700_137_dialog_content = "当時その労働者収容施設を仕切っていた親王は確かに人は良かったが、さしたる能力もない凡人。\n薬を一服飲ませると呆けになってしまった。",
  ui_story_5089_50890700_138_dialog_content = "それから互いの顔を入れ替え、\nかの囚人は王に成り替わったのだよ。",
  ui_story_5089_50890700_139_dialog_content = "王の周りの者たちは忠心の欠片もあったものではなかった。\n主がいつの間にか入れ替わっているのにも気づかぬのだからな。",
  ui_story_5089_50890700_140_dialog_content = "ちょうどその時、村の夫婦の娘が追ってきて、\n両親の仇を討つのだと言った。",
  ui_story_5089_50890700_141_dialog_content = "そこで囚人は初めて己の力が過ぎ、夫婦を殺してしまったことに気づいたのだ。",
  ui_story_5089_50890700_142_dialog_content = "そこで彼は夫婦の娘を引き取ることにし、\n己に忠義を尽くす手中の刃に育てあげたのだよ。",
  ui_story_5089_50890700_143_dialog_content = "き、き…貴様が――！",
  ui_story_5089_50890700_144_dialog_content = "<color=#e8d9bb>キュウは目を血走らせ、全身の力を振り絞って身体を起こそうとした。\nキュウを押さえつける金属の糸が鋭く高い音を放ち、今にも断ち切れそうだった</color>",
  ui_story_5089_50890700_145_dialog_content = "この話はもっと早くにするべきだったな。",
  ui_story_5089_50890700_146_dialog_content = "真相を知った今、そちは余を殺し、両親の仇を討つか？",
  ui_story_5089_50890700_147_dialog_content = "それとも、そちの命を救い、今日まで育ててきた恩人に報いるか？",
  ui_story_5089_50890700_148_dialog_content = "私は…",
  ui_story_5089_50890700_149_dialog_content = "<color=#e8d9bb>キュウの刀を握る手が初めて震えていた</color>",
  ui_story_5089_50890700_150_dialog_content = "恩返しや仇討ちへの執念がそちを支えてきたと？\nそれが何だというのだ？",
  ui_story_5089_50890700_151_dialog_content = "はあっ――！",
  ui_story_5089_50890700_152_dialog_content = "<color=#e8d9bb>一筋の光がさっと走る</color>",
  ui_story_5089_50890700_153_dialog_content = "<color=#e8d9bb>金属の糸がことごとく断ち切られ、その破片が宙に舞う中、\nキュウは一切を顧みず最後の一撃を振り下ろした</color>",
  ui_story_5089_50890700_154_dialog_content = "<color=#e8d9bb>ドーン！</color>",
  ui_story_5089_50890700_155_dialog_content = "<color=#e8d9bb>振るった刀が風を起こして光力をまとい、宮殿を真っ二つに切り裂いた。\n風はその勢いのまま足下のレンガの地面にも深い溝を残した</color>",
  ui_story_5089_50890700_156_dialog_content = "<color=#e8d9bb>しかし鄴王はいっさい身をかわすことなく、\nその身体には傷一つなかった</color>",
  ui_story_5089_50890700_157_dialog_content = "心に迷いがあるな。刀もろくに握れていないではないか。",
  ui_story_5089_50890700_158_dialog_content = "<color=#e8d9bb>カタン――</color>",
  ui_story_5089_50890700_159_dialog_content = "<color=#e8d9bb>キュウの刀が鄴王に弾き飛ばされ、宮殿の隅に落ちた</color>",
  ui_story_5089_50890700_160_dialog_content = "<color=#e8d9bb>その少し前――</color>",
  ui_story_5089_50890700_161_dialog_content = "殿下、どうしても宮殿を出るとおっしゃるのなら、\n私どももただ見ているわけには参りません。",
  ui_story_5089_50890700_162_dialog_content = "まさか鄴の国の王宮で、己の護衛と戦うことになるとはのう。",
  ui_story_5089_50890700_163_dialog_content = "じゃが今引き下がるわけにはいかぬ。",
  ui_story_5089_50890700_164_dialog_content = "わらわを待っている者がおるのじゃ。",
  ui_story_5089_50890700_165_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5089_50890700_166_dialog_content = "<color=#e8d9bb>そう遠くない所にある正殿が突然強大な光によって真っ二つになった</color>",
  ui_story_5089_50890700_167_dialog_content = "<color=#e8d9bb>続いて一筋の光が走り、強大な光力が突然狙いを定めたかのように、\n真っすぐこちらに向かってきた</color>",
  ui_story_5089_50890700_168_dialog_content = "<color=#e8d9bb>ドーン！</color>",
  ui_story_5089_50890700_169_dialog_content = "<color=#e8d9bb>城門のやぐらが真ん中から二つに割れ、宮廷の護衛とタンドウを分かった</color>",
  ui_story_5089_50890700_170_dialog_content = "<color=#e8d9bb>再度光が走ったかと思うと、今度は宮殿の外へと続く道を照らしている</color>",
  ui_story_5089_50890700_171_dialog_content = "あれは…璇璣卿か？",
  ui_story_5089_50890700_172_dialog_content = "大人しく捕まっておる奴ではないと思うてはいたが…",
  ui_story_5089_50890700_173_dialog_content = "お主もここを出よと申すか…",
  ui_story_5089_50890700_174_dialog_content = "大王様。",
  ui_story_5089_50890700_175_dialog_content = "何事か？",
  ui_story_5089_50890700_176_dialog_content = "郡主殿下が逃亡しました。",
  ui_story_5089_50890700_177_dialog_content = "郡主殿下と共に宮廷に入った正体不詳の者も行方知れずとなっております。",
  ui_story_5089_50890700_178_dialog_content = "追跡した護衛が申すには、その者は確かに草むらに逃げ込んだのですが、\nそこに人影はなく、アメ細工だけが残されていたそうです。",
  ui_story_5089_50890700_179_dialog_content = "それから…",
  ui_story_5089_50890700_180_dialog_content = "「それから」何だ。はっきりと申せ。",
  ui_story_5089_50890700_181_dialog_content = "「あちら」からの知らせによりますと、\n間もなく行動を起こすそうです。",
  ui_story_5089_50890700_182_dialog_content = "3日以内に必ず火器を届けるように、とのことです。",
  ui_story_5089_50890700_183_dialog_content = "ただ量があまりにも多すぎるため、工房も間に合わせるのは無理だと申しておりまして、\nしかも済の国からも取引の催促が来ており…",
  ui_story_5089_50890700_184_dialog_content = "分かった。",
  ui_story_5089_50890700_185_dialog_content = "その件は後で話すとしよう。",
  ui_story_5089_50890700_186_dialog_content = "今はまず頭を連れて行け。頭を冷やす時間をやるのだ。",
  ui_story_5089_50890700_187_dialog_content = "はい。",
  ui_story_5089_50890700_188_dialog_content = "<color=#e8d9bb>ドサッ</color>",
  ui_story_5089_50890700_189_dialog_content = "<color=#e8d9bb>影の護衛はキュウを空き部屋に放り込むと、そのまま立ち去った</color>",
  ui_story_5089_50890700_190_dialog_content = "あら、キュウさんじゃない。",
  ui_story_5089_50890700_191_dialog_content = "お隣さんになったわね。",
  ui_story_5089_50890700_192_dialog_content = "…",
  ui_story_5089_50890802_1_dialog_content = "悪党が侵入し、郡主殿下をさらっていった。\n全地域に厳戒態勢をしく！",
  ui_story_5089_50890802_2_dialog_content = "街を隅々まで探せ！怪しい者を見かけたら、すぐに報告するのだ！",
  ui_story_5089_50890802_3_dialog_content = "了解です！",
  ui_story_5089_50890802_4_dialog_content = "衛兵がこんなに…璟良城全体が物々しい空気に包まれてる…",
  ui_story_5089_50890802_5_dialog_content = "それに…「怪しい者」ってたぶん、僕もその中に入ってるよね？",
  ui_story_5089_50890802_6_dialog_content = "そこにいるのは誰だ！出てこい！",
  ui_story_5089_50890802_7_dialog_content = "あ、大変…うう！だ、誰…",
  ui_story_5089_50890802_8_dialog_content = "シーッ、わらわじゃ。",
  ui_story_5089_50890802_9_dialog_content = "タンドウ！",
  ui_story_5089_50890802_10_dialog_content = "付いてくるのじゃ。",
  ui_story_5089_50890802_11_dialog_content = "ここはどこ？",
  ui_story_5089_50890802_12_dialog_content = "金の輸送を頼んだ鏢局が用意した場所じゃ。",
  ui_story_5089_50890802_13_dialog_content = "鏢局は世渡りに長けた生業でのう。\nその世界の義理も決まりもあるのじゃ。",
  ui_story_5089_50890802_14_dialog_content = "われらのように大きな依頼主ともなれば、\n当然相応の便宜を図ってくれるのじゃよ。",
  ui_story_5089_50890802_15_dialog_content = "そんな先の事まで考えて鏢局を頼んだの！？",
  ui_story_5089_50890802_16_dialog_content = "だったら、僕たちを宿に置きざりにしたのも理由があるんだよね？",
  ui_story_5089_50890802_17_dialog_content = "あの時はまだ確信を持てておらんかったのじゃ。\n璇璣卿も暗示程度の手がかりしか残しておらんかったしのう。",
  ui_story_5089_50890802_18_dialog_content = "じゃがほんのわずかな可能性だとしても、\n国の大事に関わることには違いなかった。",
  ui_story_5089_50890802_19_dialog_content = "それに…穀物の値が上がりすぎておる。",
  ui_story_5089_50890802_20_dialog_content = "ご老人が言っておったであろう。\n済の国の商人がこのところ高値で穀物を買い集めておると。",
  ui_story_5089_50890802_21_dialog_content = "…春新節の動乱の背景には、\n鄴の国がいつまでも済の国に沿岸砲を納めていないことがあった。",
  ui_story_5089_50890802_22_dialog_content = "済の国が黙っているはずもあるまい。",
  ui_story_5089_50890802_23_dialog_content = "つまり…済の国がわざと穀物の値を上げてるってこと？",
  ui_story_5089_50890802_24_dialog_content = "食糧の値が上がれば、民が苦しむ。\n民が苦しめば、国は乱れる。",
  ui_story_5089_50890802_25_dialog_content = "鄴では近年工房の数を大幅に増やしたせいで、\n働き盛りが大量に田畑を離れ、工房で働くようになっておる。",
  ui_story_5089_50890802_26_dialog_content = "じゃが、鄴の国にはかような変化に応じられるだけの十分な食糧備蓄がないのじゃ。",
  ui_story_5089_50890802_27_dialog_content = "穀物の値が上がるということは他の産業でも原価が上がるということじゃ。\nつまり悪い影響の連鎖反応が起こるのじゃよ。",
  ui_story_5089_50890802_28_dialog_content = "済の国は金銭には事欠かぬ。\n済の国がひとたび持久戦の意を決すれば、必ずや乱が起こるじゃろう。",
  ui_story_5089_50890802_29_dialog_content = "とはいえ済の国もそのつもりはないじゃろうな。\nちと痛い目に遭わせようとしているにすぎぬ。ただ…",
  ui_story_5089_50890802_30_dialog_content = "時機が悪すぎるのう。",
  ui_story_5089_50890802_31_dialog_content = "時機が悪すぎる？",
  ui_story_5089_50890802_32_dialog_content = "PlayerName、「国」とは何だと思うか？",
  ui_story_5089_50890802_33_dialog_content = "え？そ、そうだな…皆がより良い暮らしを求めて、一緒に暮らすってことだと思う。",
  ui_story_5089_50890802_34_dialog_content = "それぞれが努力しながら、助け合うのが「国」じゃないかな。",
  ui_story_5089_50890802_35_dialog_content = "それは天空ノ谷の思想か？まるで桃源郷のようじゃのう。",
  ui_story_5089_50890802_36_dialog_content = "ま、間違ってるかな？",
  ui_story_5089_50890802_37_dialog_content = "いいや、PlayerNameはそれでよい。",
  ui_story_5089_50890802_38_dialog_content = "同じく兆に属すといえど、\n龍州の諸侯国はそれぞれ国という概念を異にしておる。",
  ui_story_5089_50890802_39_dialog_content = "たとえば済の国は「治国は商いのごとし」と考え、\n鄴の国では、こう教えられる――",
  ui_story_5089_50890802_40_dialog_content = "「国」とは大きく形のない機巧装置であり、\n昼夜を問わず、止まることなく動き続けるものじゃ、と。",
  ui_story_5089_50890802_41_dialog_content = "君主が軸となり、臣下は歯車、匠は潤滑油となって、\n民が動力を提供する。",
  ui_story_5089_50890802_42_dialog_content = "それぞれが役目を果たし、正常に動くことができれば、\n国はおのずと栄える、とな。",
  ui_story_5089_50890802_43_dialog_content = "じゃが今はどうじゃ？",
  ui_story_5089_50890802_44_dialog_content = "君主はまがいもの、臣下の中には天命を受けし者もおろう。\n匠は自由を得られず、民は争いの災禍に悩まされるばかり。",
  ui_story_5089_50890802_45_dialog_content = "かような局面は、両断するほかに打開の術はない。",
  ui_story_5089_50890802_46_dialog_content = "ゆえに宮廷に戻り、内側からほころびを見つけようと思うたのじゃ。",
  ui_story_5089_50890802_47_dialog_content = "さすればお主らも追っ手から逃れられるしのう。\n自由に証拠探しもできる。",
  ui_story_5089_50890802_48_dialog_content = "すべて話してしまえば、キュウが承知せぬのは分かりきっておった。\nゆえにかような手を使うしかなかったのじゃ…PlayerName、すまんかったのう。",
  ui_story_5089_50890802_49_dialog_content = "いやいや、僕もキュウの石頭ぶりにはほとほと悩まされたから、よく分かる。",
  ui_story_5089_50890802_50_dialog_content = "実は僕もある事を…",
  ui_story_5089_50890802_51_dialog_content = "坊ちゃん、お嬢さん、お荷物をもってまいりましたよ。\n調べてください。",
  ui_story_5089_50890802_52_dialog_content = "あ、ありがとう。",
  ui_story_5089_50890802_53_dialog_content = "それとお嬢さんに聞き込みを頼まれていた件ですが、だいたい分かりました。",
  ui_story_5089_50890802_54_dialog_content = "城外にいる仲間の話では、火龍輿は確かにその方角の軌道に集まってるそうです。\nその様子からして、何やら大量の荷物を運ぶ準備をしているようです。",
  ui_story_5089_50890802_55_dialog_content = "さようか、ありがとう。",
  ui_story_5089_50890802_56_dialog_content = "いいえ、これが私たちの仕事ですから。\nでは失礼します。",
  ui_story_5089_50890802_57_dialog_content = "もしかして、あの秘密の工房のこと？",
  ui_story_5089_50890802_58_dialog_content = "そうじゃ。宮廷で小耳にはさんでのう。",
  ui_story_5089_50890802_59_dialog_content = "「叔父」は鄴の国を利用して、天命を受けし者らに武器を造り続けておる。",
  ui_story_5089_50890802_60_dialog_content = "済の国に沿岸砲を送らぬのは、一つには天命を受けし者の企みに協力するため、\n二つには済の国に送るはずの沿岸砲を天命を受けし者がわが物にせんとしているゆえじゃ。",
  ui_story_5089_50890802_61_dialog_content = "そしてつい先頃、さらに多くの武器を求めてきた。",
  ui_story_5089_50890802_62_dialog_content = "催促は幾度にもわたり、\n挙句の果てには「叔父」を脅迫するまでになった。",
  ui_story_5089_50890802_63_dialog_content = "ここへ来る途中、PlayerNameから例の工房の話が出たのでのう。\n偵察に行かせたのじゃ。",
  ui_story_5089_50890802_64_dialog_content = "じゃが…まさかこうも早く動きがあるとは思わなんだが…",
  ui_story_5089_50890802_65_dialog_content = "天命を受けし者みたいな組織にそんなたくさんの武器を渡しちゃいけない！",
  ui_story_5089_50890802_66_dialog_content = "わらわも同じ気持ちじゃ。",
  ui_story_5089_50890802_67_dialog_content = "じゃが今のわれらでは何もできまい。",
  ui_story_5089_50890802_68_dialog_content = "PlayerNameらのおかげでようやく真相が分かったというに…\nもう少し早くわらわが動いておれば…",
  ui_story_5089_50890802_69_dialog_content = "そんな顔するなんて、タンドウらしくないよ。",
  ui_story_5089_50890802_70_dialog_content = "PlayerName？",
  ui_story_5089_50890802_71_dialog_content = "僕の知ってるタンドウなら、たとえ運命が相手であろうと、\n絶対に抗ってみせる。",
  ui_story_5089_50890802_72_dialog_content = "周りが怖くなるくらい勇敢な人だ。",
  ui_story_5089_50890802_73_dialog_content = "…買いかぶりすぎじゃよ。この窮地は決して勇気だけで打開できるものではない。",
  ui_story_5089_50890802_74_dialog_content = "せめて交渉に持ち込むに足るコマがあればよいのじゃが…",
  ui_story_5089_50890802_75_dialog_content = "あるよ。",
  ui_story_5089_50890802_76_dialog_content = "何じゃと？",
  ui_story_5089_50890802_77_dialog_content = "コマならたくさんあるって言ったんだよ。",
  ui_story_5089_50890802_78_dialog_content = "たとえば――町を丸ごと買えるだけの金、とかね。",
  ui_story_5089_50890802_79_dialog_content = "！",
  ui_story_5089_50890802_80_dialog_content = "じゃが…あれはお世継ぎがお主に贈ったものじゃ。\nしかも返さねばならぬのじゃろう？",
  ui_story_5089_50890802_81_dialog_content = "やっとここまで来たんだ。\n使えるものは全部使わなきゃ今までの苦労が水の泡になっちゃうよ。",
  ui_story_5089_50890802_82_dialog_content = "とはいうても金がいくらあったとて、\n限られた時間内に味方を増やすには――",
  ui_story_5089_50890802_83_dialog_content = "そのことだけど…",
  ui_story_5089_50890802_84_dialog_content = "僕は朝廷内のまどろっこしい駆け引きとかはよく分からない。",
  ui_story_5089_50890802_85_dialog_content = "だから、もっとシンプルに考えてみるのはどう？",
  ui_story_5089_50890802_86_dialog_content = "お金って物を買うための道具だよね？",
  ui_story_5089_50890802_87_dialog_content = "ならば…PlayerNameは何を買おうというのじゃ？",
  ui_story_5089_50890802_88_dialog_content = "たぶん敵はまだ火龍輿を使ったことがないと思うんだ。",
  ui_story_5089_50890802_89_dialog_content = "火龍輿ってすごい音がするから、使えば必ず住民たちが気づくし、\nそんな物が走ってたら、あの工房が使われてないって言われても信じないと思う。",
  ui_story_5089_50890802_90_dialog_content = "確かにこれまでに見た者はおらぬ。",
  ui_story_5089_50890802_91_dialog_content = "密かに事を運び、秘密工房の「秘密」を守るには、\n貨物を幾度にも分けて運ぶしかないしのう。",
  ui_story_5089_50890802_92_dialog_content = "でも今回は火龍輿を使う。しかもおそらく何台も使うだろうね。",
  ui_story_5089_50890802_93_dialog_content = "火龍輿の使用は百工院が管理しておる。",
  ui_story_5089_50890802_94_dialog_content = "二大機巧師門派出身の官僚と朝廷が直接任命した管理官が\n共に監督管理しておるのじゃ。",
  ui_story_5089_50890802_95_dialog_content = "大王でさえ手続きを省いて勝手に使うことは許されぬ。",
  ui_story_5089_50890802_96_dialog_content = "ただすでに工房主に貸し出したものとなれば、\nさほど厳格な管理はされておらぬ。",
  ui_story_5089_50890802_97_dialog_content = "つまり、今工房の方に集まってる火龍輿は天命を受けし者が\n工房主から又借りした可能性が高いってことだね。",
  ui_story_5089_50890802_98_dialog_content = "ならば、工房主を当たってみるか？",
  ui_story_5089_50890802_99_dialog_content = "いや。",
  ui_story_5089_50890802_100_dialog_content = "正面から相手を刺激する必要はないと思う。\nいずれにせよ、今焦ってるのは向こうなんだ。",
  ui_story_5089_50890802_101_dialog_content = "こうやって外から見てると、センキョクの言ってた「波」がよく見える気がする。",
  ui_story_5089_50890802_102_dialog_content = "タンドウ、百工院が貸し出したのは「火龍輿」だけだよね。",
  ui_story_5089_50890802_103_dialog_content = "そうじゃ。",
  ui_story_5089_50890802_104_dialog_content = "だったら僕は…",
  ui_story_5089_50890802_105_dialog_content = "「道」を買う。",
  ui_story_5089_50890802_106_dialog_content = "……PlayerNameは真に奇才じゃのう！",
  ui_story_5089_50890802_107_dialog_content = "<color=#e8d9bb>秘密工房では――</color>",
  ui_story_5089_50890802_108_dialog_content = "いったいどうなっているのです？\n誰が火龍輿を勝手に動かしていいと言ったのですか？",
  ui_story_5089_50890802_109_dialog_content = "うるさいわね、こっちが聞きたいわよ。",
  ui_story_5089_50890802_110_dialog_content = "上から何度も武器を送れと催促が来ているというのに、\nあなたたちこそ何をやっているの？",
  ui_story_5089_50890802_111_dialog_content = "十分な量を造れないなら、済の国の分を先に出せばいいでしょう。それくらいはできるはずよ。",
  ui_story_5089_50890802_112_dialog_content = "…済の国に早く物を送らなければ、両国関係に影響が出てしまいます。",
  ui_story_5089_50890802_113_dialog_content = "ふん、3歳の子どもでさえ、そんな言葉にはだまされないわ。",
  ui_story_5089_50890802_114_dialog_content = "天命を受けし者の船に乗った以上、誰の命令を聞くべきか言われなくても分かるわよね。\n誰が両国関係なんて気にするのよ。",
  ui_story_5089_50890802_115_dialog_content = "まさか…あの大王を本気で鄴王だと思っているわけではないでしょう？",
  ui_story_5089_50890802_116_dialog_content = "そんなはずありません。",
  ui_story_5089_50890802_117_dialog_content = "そうよね。あの大王様はかつて死刑囚だったそうね。\n天命を受けし者に身を寄せたおかげで、鄴王として今の今まで生きてこられた。",
  ui_story_5089_50890802_118_dialog_content = "もしおかしな考えでも起こそうものなら、\n今手にしている物をすべて、そっくりそのまま返してもらうわ。",
  ui_story_5089_50890802_119_dialog_content = "大事を目の前にして、言う事を聞く気がないのなら、\n諸侯国なんて乱れるだけ乱れればいいのよ。",
  ui_story_5089_50890802_120_dialog_content = "そのくらいの道理は、あなたでも分かるでしょう？",
  ui_story_5089_50890802_121_dialog_content = "…もちろんです。",
  ui_story_5089_50890802_122_dialog_content = "ならいいわ。さっさと荷を積む手伝いをしてちょうだい。",
  ui_story_5089_50890802_123_dialog_content = "テイト様、大変です。",
  ui_story_5089_50890802_124_dialog_content = "今度は何よ？",
  ui_story_5089_50890802_125_dialog_content = "火龍輿を使っての輸送は無理そうです。",
  ui_story_5089_50890802_126_dialog_content = "報酬は十分払ったでしょう？",
  ui_story_5089_50890802_127_dialog_content = "問題はそこではありません。実は…",
  ui_story_5089_50890802_128_dialog_content = "道が封鎖されました。",
  ui_story_5089_50890802_129_dialog_content = "はぁ！？",
  ui_story_5089_50890901_1_dialog_content = "PlayerNameの豪快な金遣いのおかげで、うまくいったようじゃのう。",
  ui_story_5089_50890901_2_dialog_content = "工房近くにある軌道沿いの土地も一時的に借り上げたぞ。\n村の者に頼み、障害も設けてもろうた。",
  ui_story_5089_50890901_3_dialog_content = "天命を受けし者もこれでは身動きとれまい。",
  ui_story_5089_50890901_4_dialog_content = "ただ道を封じたがために、商人も足止めを食ろうてしもうたが――",
  ui_story_5089_50890901_5_dialog_content = "お二人とも、私めはただ米を買いに来ただけでございます。\n罪など犯しておりません。",
  ui_story_5089_50890901_6_dialog_content = "どうか便宜を図り、隊商を通してはくださいませんか？",
  ui_story_5089_50890901_7_dialog_content = "済の国から穀物を買い付けにきたんですか？",
  ui_story_5089_50890901_8_dialog_content = "はい、さようでございます。それが…何か問題でも？\n手続きはきちんと済ませておりますが…",
  ui_story_5089_50890901_9_dialog_content = "（タンドウ）",
  ui_story_5089_50890901_10_dialog_content = "（うむ）",
  ui_story_5089_50890901_11_dialog_content = "コホン。お主、目の前のこの方が何者か知っておるか？",
  ui_story_5089_50890901_12_dialog_content = "い、いえ、存じ上げませんが…",
  ui_story_5089_50890901_13_dialog_content = "この方はPlayerName、アストラ大陸の特使、天空ノ谷の主であり、\n済王殿下より直々に栄誉国民の称号を賜った方であるぞ。",
  ui_story_5089_50890901_14_dialog_content = "龍女様のご加護も厚く、リン家商会の友人でもあり、\n済の国のお世継ぎがたいそう熱をあげ…",
  ui_story_5089_50890901_15_dialog_content = "（タンドウ！もう十分だよ！あの熱い視線を見てよ。\nこれ以上言ったら、どんな目に遭うか…）",
  ui_story_5089_50890901_16_dialog_content = "なんと、あなた様がかの使者様でしたか！\nお会いできて誠に光栄でございます！",
  ui_story_5089_50890901_17_dialog_content = "何か私めにお手伝いできることはございますか？私めにできることならば何でも…\nあ、道はあなた様が封じたのでしたね。",
  ui_story_5089_50890901_18_dialog_content = "道といわず、どこでもご自由に封じてください！",
  ui_story_5089_50890901_19_dialog_content = "そ、そんな大げさな事じゃないんです。\nただ買いたい物があって…",
  ui_story_5089_50890901_20_dialog_content = "何なりとお申しつけください！お値引きいたしますよ！",
  ui_story_5089_50890901_21_dialog_content = "タンドウ、金はあとどのくらい残ってる？",
  ui_story_5089_50890901_22_dialog_content = "工人に払う賃金と軌道と土地を借り上げた費用を引いても\nまだたんと残っておる。",
  ui_story_5089_50890901_23_dialog_content = "だったら、残りは全部この人にあげて。",
  ui_story_5089_50890901_24_dialog_content = "こ、これは、どういう…",
  ui_story_5089_50890901_25_dialog_content = "この金で、済の国の商人の皆さんが鄴の国で買い付けた食糧全てを買い戻したいんです。",
  ui_story_5089_50890901_26_dialog_content = "それは…私めには少々荷が重く…",
  ui_story_5089_50890901_27_dialog_content = "済王様の命で食糧を買い付けていることは知っています。",
  ui_story_5089_50890901_28_dialog_content = "！",
  ui_story_5089_50890901_29_dialog_content = "済王様には僕に無理やりやらされたと言ってください。\nお咎めがあったら、その時は全責任を僕に押し付けて構いません。",
  ui_story_5089_50890901_30_dialog_content = "ならば…おっしゃる通りにいたします。",
  ui_story_5089_50890901_31_dialog_content = "ありがとうございます。僕も約束は守ります。",
  ui_story_5089_50890901_32_dialog_content = "ふぅ、やっと行ったね。",
  ui_story_5089_50890901_33_dialog_content = "ホホホ。",
  ui_story_5089_50890901_34_dialog_content = "もう…偉そうにするのは得意じゃないんだよ。\nそんなにおかしかったかな…？",
  ui_story_5089_50890901_35_dialog_content = "そうではない。実に堂々として立派であったぞ。",
  ui_story_5089_50890901_36_dialog_content = "おや？",
  ui_story_5089_50890901_37_dialog_content = "遠くに見える、あの者たちは…",
  ui_story_5089_50890901_38_dialog_content = "<color=#e8d9bb>少し前――</color>",
  ui_story_5089_50890901_39_dialog_content = "トントントン。",
  ui_story_5089_50890901_40_dialog_content = "このような時にいったい誰が便りなど？",
  ui_story_5089_50890901_41_dialog_content = "…",
  ui_story_5089_50890901_42_dialog_content = "センキョク先輩！百工院にいる先輩からの便りです！\nあの空の末裔が…",
  ui_story_5089_50890901_43_dialog_content = "ちょっと何度言ったら分かるのよ。\n宮廷で「先輩」はナシ。",
  ui_story_5089_50890901_44_dialog_content = "こっちには派閥とか党派を組むつもりがなくても、\n朝廷って所はね、すぐにヘンな誤解をするのよ。",
  ui_story_5089_50890901_45_dialog_content = "候風卿がいい例でしょ？",
  ui_story_5089_50890901_46_dialog_content = "候風卿とは…確か10数年も前に官職に就いていた方ですよね？",
  ui_story_5089_50890901_47_dialog_content = "確かどの門派にも属さず、あちこちを巡り歩きながら、\n無所属の匠に技を教わったという異端児機巧師ですよね。",
  ui_story_5089_50890901_48_dialog_content = "才能には恵まれていたものの、少々傲慢で、\n二大門派が門下に引き入れようとしても断ったとか。",
  ui_story_5089_50890901_49_dialog_content = "官僚となった後も過激な改革論を展開し――",
  ui_story_5089_50890901_50_dialog_content = "カラクリの販売制限を撤廃しようとしたり、\n全門派の資源をすべて朝廷で統括管理すべきと主張したと聞いています。",
  ui_story_5089_50890901_51_dialog_content = "国のために尽くす情熱にはあふれていたようですが、\n考え方が過激で現実的でもありません。",
  ui_story_5089_50890901_52_dialog_content = "あのような末路をたどったのも、ほかならぬ自分のせいです。\nセンキョク様、真似をするなどと言い出さないでくださいよ。",
  ui_story_5089_50890901_53_dialog_content = "まさか。私は何でも言う事をよく聞く良臣よ。\n今だってこうして牢に入れと言われれば、大人しく入ってるでしょ？",
  ui_story_5089_50890901_54_dialog_content = "自分がなぜ牢に放り込まれたか、お忘れのように見えますが？",
  ui_story_5089_50890901_55_dialog_content = "理由なんてどうでもいいのよ。\n自分が設計に関わった機巧砲を使ったことが理由じゃなければね。",
  ui_story_5089_50890901_56_dialog_content = "さあ、何て書いてあるか見てみましょ。",
  ui_story_5089_50890901_57_dialog_content = "…あははは！面白いじゃない、さっすがPlayerName！",
  ui_story_5089_50890901_58_dialog_content = "突飛だけど、この状況ではむしろ最善策だわ。",
  ui_story_5089_50890901_59_dialog_content = "どうやら、見極めたみたいね。",
  ui_story_5089_50890901_60_dialog_content = "何をですか？",
  ui_story_5089_50890901_61_dialog_content = "何でもないわ。この後ちょっとお使いを頼まれてくれない？",
  ui_story_5089_50890901_62_dialog_content = "今は官職に就いてないただの機巧師だから、\n政に口は出せないわ。",
  ui_story_5089_50890901_63_dialog_content = "でも情報をやり取りして、師門の裏切者を成敗するのは政じゃない。",
  ui_story_5089_50890901_64_dialog_content = "だから、先輩に伝えて。",
  ui_story_5089_50890901_65_dialog_content = "はい、先輩。",
  ui_story_5089_50890901_66_dialog_content = "それから…お隣さん、気分はどう？",
  ui_story_5089_50890901_67_dialog_content = "…",
  ui_story_5089_50890901_68_dialog_content = "候風卿の名前を出せば、話に乗ってくれるかと思ったんだけど。",
  ui_story_5089_50890901_69_dialog_content = "10年前朝廷に仕え、その後派閥争いに巻き込まれ、\n死刑を言い渡された後、行方不明になった。",
  ui_story_5089_50890901_70_dialog_content = "この条件を満たす人は1人しかいないわ。",
  ui_story_5089_50890901_71_dialog_content = "…私とはもう何の関係もありません。",
  ui_story_5089_50890901_72_dialog_content = "私が抱き続けてきた恩も仇もみな…ただの笑い話だったのです。",
  ui_story_5089_50890901_73_dialog_content = "何のために刀を振るえばよいのか、何ができるのか…\nもう分からなくなってしまいました。",
  ui_story_5089_50890901_74_dialog_content = "ですからセンキョク様、私のことはお気になさらないでください。",
  ui_story_5089_50890901_75_dialog_content = "たった一つの目的のために生きて、役に立てなくなったら捨てられる。",
  ui_story_5089_50890901_76_dialog_content = "それって妖魔を描写する時に聞いた言葉だわ。",
  ui_story_5089_50890901_77_dialog_content = "キュウさん、一つ聞いてもいい？",
  ui_story_5089_50890901_78_dialog_content = "人と妖魔の違いって何かしら？",
  ui_story_5089_50890901_79_dialog_content = "…",
  ui_story_5089_50890901_80_dialog_content = "違いがあるのでしょうか？",
  ui_story_5089_50890901_81_dialog_content = "はぁ…こっちは私じゃ無理みたい。",
  ui_story_5089_50890901_82_dialog_content = "任せたわ。",
  ui_story_5089_50890901_83_dialog_content = "…",
  ui_story_5089_50890901_84_dialog_content = "PlayerName、何を考えておるのじゃ？",
  ui_story_5089_50890901_85_dialog_content = "人と妖魔の違いって何かな？",
  ui_story_5089_50890901_86_dialog_content = "なんと？",
  ui_story_5089_50890901_87_dialog_content = "いや、何でもないよ。今何か言った？",
  ui_story_5089_50890901_88_dialog_content = "今ある障害じゃがのう、\n天命を受けし者が強行突破しようとすれば、突破されてしまうのう。",
  ui_story_5089_50890901_89_dialog_content = "援軍を呼ぼう。",
  ui_story_5089_50890901_90_dialog_content = "璟良城内に駐留できる兵の数は限られておるゆえ、\n璟良軍の多くは城外に駐留しておるのじゃ。",
  ui_story_5089_50890901_91_dialog_content = "城内の兵のように皆が精鋭とはいかぬが、\n今われらに足りぬのは数じゃ。",
  ui_story_5089_50890901_92_dialog_content = "じゃあ急ごう。郡主なら兵を動かせるんだよね。",
  ui_story_5089_50890901_93_dialog_content = "PlayerName。",
  ui_story_5089_50890901_94_dialog_content = "どうしたの…どうして短剣を僕に？",
  ui_story_5089_50890901_95_dialog_content = "城外に駐留しておるとはいえ、璟良軍であることに変わりはない。\n城内で起こった事はすでに伝わっておろう。",
  ui_story_5089_50890901_96_dialog_content = "お主も分かっておるはずじゃ。\n今となっては、あの偽物の叔父がわらわに情けをかけるはずもない。",
  ui_story_5089_50890901_97_dialog_content = "郡主であろうと、兵を動かすことはかなわぬであろう。",
  ui_story_5089_50890901_98_dialog_content = "じゃあ、どうして？",
  ui_story_5089_50890901_99_dialog_content = "受け取るのじゃ。",
  ui_story_5089_50890901_100_dialog_content = "…だから、どうして僕に短剣を？",
  ui_story_5089_50890901_101_dialog_content = "ここの璟良軍がいかなる命を受けたかは知らぬ。",
  ui_story_5089_50890901_102_dialog_content = "じゃが少なくとも「叔父」がまだその身分にこだわる限り、\n表立ってわらわを手に掛けることはなかろう。",
  ui_story_5089_50890901_103_dialog_content = "ならば璟良軍にとって、灼華郡主は今も守るべき者のはず。ゆえ　に…",
  ui_story_5089_50890901_104_dialog_content = "君を人質にとったお芝居をして、\n璟良軍を工房の方へ誘い出せっていうんだね？",
  ui_story_5089_50890901_105_dialog_content = "そんなの、危険すぎる…\n何が起こるか、まったく予想もつかないよ…",
  ui_story_5089_50890901_106_dialog_content = "万が一そのまま捕まっちゃったら？\nあの「鄴王」が暴走して君を殺そうとしたら？",
  ui_story_5089_50890901_107_dialog_content = "まずは一旦戻ろう。他の方法を考えてから――",
  ui_story_5089_50890901_108_dialog_content = "<color=#e8d9bb>タンドウが突然僕の手をつかみ、短剣をさっと自分の首に当てた</color>",
  ui_story_5089_50890901_109_dialog_content = "タンドウ！",
  ui_story_5089_50890901_110_dialog_content = "<color=#e8d9bb>僕は必死に抵抗したけれど、\n刃はタンドウの首に一筋の赤い傷をつけた</color>",
  ui_story_5089_50890901_111_dialog_content = "PlayerName、わらわを見よ。",
  ui_story_5089_50890901_112_dialog_content = "<color=#e8d9bb>一粒の血が刃を伝って僕の手のひらに落ちてきた。\nでもタンドウは木漏れ日の指す中、にっこりとほほ笑んでいた</color>",
  ui_story_5089_50890901_113_dialog_content = "お主を信じる。",
  ui_story_5089_50890901_114_dialog_content = "…分かった。",
  ui_story_5089_50890901_115_dialog_content = "誰だ？",
  ui_story_5089_50890901_116_dialog_content = "来ないで！",
  ui_story_5089_50890901_117_dialog_content = "灼華郡主の命は僕が預かった。",
  ui_story_5089_50890901_118_dialog_content = "！",
  ui_story_5089_50890901_119_dialog_content = "郡主殿下が人質に取られた！全隊ただちに集まれ！",
  ui_story_5089_50890901_120_dialog_content = "郡主殿下を解放しろ！解放すれば命だけはひとまず助けてやる！",
  ui_story_5089_50890901_121_dialog_content = "放せって言われたて、大人しく放すわけないでしょ？\nそれに脅しは通用しないよ。",
  ui_story_5089_50890901_122_dialog_content = "僕は天命を受けし者の一員だ。このすぐ近くに僕たちの拠点がある。\nそこには大量の火器だってあるんだ。",
  ui_story_5089_50890901_123_dialog_content = "だから慎重になった方がいいよ。\n僕たちはいつでも君たちを道連れにできるんだから。",
  ui_story_5089_50890901_124_dialog_content = "射手！",
  ui_story_5089_50890901_125_dialog_content = "強制感知！",
  ui_story_5089_50890901_126_dialog_content = "ううっ――",
  ui_story_5089_50890901_127_dialog_content = "逃がすな！",
  ui_story_5089_50890901_128_dialog_content = "隊長、大変です！あの悪党と郡主殿下を見失いました！",
  ui_story_5089_50890901_129_dialog_content = "さっさと追え！郡主殿下に何かあったらどうするんだ！",
  ui_story_5089_50890901_130_dialog_content = "しかし、いったいどこへ向かえば…おや？\n海棠の花がなぜ…",
  ui_story_5089_50890901_131_dialog_content = "きっと郡主殿下が残した手がかりに違いない！\nこっちだ！",
  ui_story_5089_50890901_132_dialog_content = "何としても奴らの拠点を探し出せ！",
  ui_story_5089_50890901_133_dialog_content = "大王様、城外に駐留する璟良軍の一隊が工房の方角へ向かいました。",
  ui_story_5089_50890901_134_dialog_content = "何だと？",
  ui_story_5089_50890901_135_dialog_content = "報告では、郡主殿下が人質にとられたとのことです。",
  ui_story_5089_50890901_136_dialog_content = "璟良軍の指揮官も大事があってはならぬと、\n即刻兵を向かわせたようです。",
  ui_story_5089_50890901_137_dialog_content = "現在璟良軍は工房を包囲し、周囲の道も封鎖されております。",
  ui_story_5089_50890901_138_dialog_content = "間もなく包囲攻撃を開始する模様です。",
  ui_story_5089_50890901_139_dialog_content = "我々の手の者がひとまず工房内を落ち着かせていますが――",
  ui_story_5089_50890901_140_dialog_content = "大王様は何をするつもりなのかと奴らが騒いでおります。",
  ui_story_5089_50890901_141_dialog_content = "ふっ…",
  ui_story_5089_50890901_142_dialog_content = "これしきの策で一か八かの勝負に出るつもりか？",
  ui_story_5089_50890901_143_dialog_content = "参るぞ。",
  ui_story_5089_50890901_144_dialog_content = "何をする気なのかと問うのなら、余自ら赴いてやろうではないか。",
  ui_story_5089_50890901_145_dialog_content = "<color=#e8d9bb>しばらくして――</color>",
  ui_story_5089_50890901_146_dialog_content = "ふぅ、やっといなくなりましたか。",
  ui_story_5089_50890901_147_dialog_content = "灯台下暗しとはよく言ったもんです。\n敵の足下ってのはやはり一番安全ですねぇ。",
  ui_story_5089_50890901_148_dialog_content = "それにしても、ずいぶんと腰の重い王様ですねぇ。\nいったい何を考えているのやら、宮殿が壊れたってのに直しもしないで。",
  ui_story_5089_50890901_149_dialog_content = "梁が大きくて幸いでしたよ。\nでなけりゃ僕の足腰が持ちませんでした。",
  ui_story_5089_50890901_150_dialog_content = "ようやく誰もいなくなったことですし、\nそろそろ宮殿を出て、気ままに過ごすとしますか。",
  ui_story_5089_50890901_151_dialog_content = "おや？キュウさんの刀じゃありませんか。\nなんだってこんな所に…？",
  ui_story_5089_50890901_152_dialog_content = "なるほど、では渡しに行きましょうかね。",
  ui_story_5089_50890901_153_dialog_content = "はぁ…はぁ…ぼ、僕はもう…くたくたなのに…",
  ui_story_5089_50890901_154_dialog_content = "追っ手の勢いがぜんぜん衰えない…",
  ui_story_5089_50890901_155_dialog_content = "カイドウの花で誘い、回り道をさせたが、\nあやつら思っておった以上に反応がよいのう。",
  ui_story_5089_50890901_156_dialog_content = "どうやら厳格に規律を守り、訓練も怠っておらんかったようじゃ。",
  ui_story_5089_50890901_157_dialog_content = "つまり「叔父」は常に兵力を磨いておったのじゃな。\nそのうえ、あの大量の火器となると…",
  ui_story_5089_50890901_158_dialog_content = "天命を受けし者は…何を企んでおるのじゃ…",
  ui_story_5089_50890901_159_dialog_content = "今あれこれ考えても仕方ないよ。\nいずれにせよ、僕たちはできることを全部やった。",
  ui_story_5089_50890901_160_dialog_content = "まずはここでひと休みしよう。",
  ui_story_5089_50890901_161_dialog_content = "今のところ工房には何の異変もないみたいだけど、\nもっと先に進めば、何か動きを見せるかもしれない。",
  ui_story_5089_50890901_162_dialog_content = "<color=#e8d9bb>背後では璟良軍の兵士たちが散開し、僕たちを取り囲んでいた。\n手に持った松明が真っ暗な夜空を赤く染める</color>",
  ui_story_5089_50890901_163_dialog_content = "<color=#e8d9bb>前方の天命を受けし者の工房には、人の気配はするものの人影は見えず、\nまるで冬眠中の巨大な猛獣が横たわっているかのように闇の中で不気味な空気を漂わせていた</color>",
  ui_story_5089_50890901_164_dialog_content = "PlayerName、ずっと言えず仕舞いじゃったが…",
  ui_story_5089_50890901_165_dialog_content = "お主に助けを求めたとはいえ、\nかように危険な目に遭わせようと思うておったわけではない。",
  ui_story_5089_50890901_166_dialog_content = "すまぬ。",
  ui_story_5089_50890901_167_dialog_content = "気にしないで。それにきっと大丈夫だよ。",
  ui_story_5089_50890901_168_dialog_content = "僕も君を信じる。",
  ui_story_5089_50890901_169_dialog_content = "あれ？璟良軍に動きが…",
  ui_story_5089_50890901_170_dialog_content = "大王様の御成り――",
  ui_story_5089_50890901_171_dialog_content = "あれは…",
  ui_story_5089_50890901_172_dialog_content = "「叔父」。",
  ui_story_5089_50890901_173_dialog_content = "タンドウ、そちはもう少し賢いと思っていたのだがな。",
  ui_story_5089_50890901_174_dialog_content = "余がひとたび命を下せば、あの工房は完全に守られる。\nそれしきのことも分からぬのか？",
  ui_story_5089_50890901_175_dialog_content = "そちらにとって、ここは墓場としか成り得ぬ場所――",
  ui_story_5089_50890901_176_dialog_content = "自ら網にかかるとは実に愚かだ。",
  ui_story_5089_50890901_177_dialog_content = "お主が本物の叔父であれば、そうじゃろうのう。",
  ui_story_5089_50890901_178_dialog_content = "じゃがお主はまがいものじゃ。かような勝手は許されぬ！",
  ui_story_5089_50890901_179_dialog_content = "今皆の前でお主のその仮面を剥いでやる、候風卿！",
  ui_story_5089_50890902_1_dialog_content = "PlayerName、今じゃ！",
  ui_story_5089_50890902_2_dialog_content = "強制感知！",
  ui_story_5089_50890902_3_dialog_content = "うっ…",
  ui_story_5089_50890902_4_dialog_content = "（璟良軍に手間取ってる暇はない。僕たちの目的はこの人たちと戦うことじゃない）",
  ui_story_5089_50890902_5_dialog_content = "（天命を受けし者は容貌を変える時、人の皮で作ったお面を使う…）",
  ui_story_5089_50890902_6_dialog_content = "（一瞬でいい…一瞬でいいから…お面を引き裂く隙があれば…）",
  ui_story_5089_50890902_7_dialog_content = "！？",
  ui_story_5089_50890902_8_dialog_content = "<color=#e8d9bb>刃が偽物の鄴王の片側の顔の皮を引き裂いた</color>",
  ui_story_5089_50890902_9_dialog_content = "<color=#e8d9bb>しかし引き裂かれたのは血の通わない面ではなく――</color>",
  ui_story_5089_50890902_10_dialog_content = "<color=#e8d9bb>真っ赤な鮮血を流す、正真正銘の生きた人の皮だった</color>",
  ui_story_5089_50890902_11_dialog_content = "どうして…？",
  ui_story_5089_50890902_12_dialog_content = "満足したか？",
  ui_story_5089_50890902_13_dialog_content = "求めていた答えを得られたか？",
  ui_story_5089_50891001_1_dialog_content = "だ…大王様！急ぎ医者を！お前たち、何を呆然としている！？",
  ui_story_5089_50891001_2_dialog_content = "下がれ。たかが子どものいたずらだ。",
  ui_story_5089_50891001_3_dialog_content = "そんな…あなたが鄴王様のはずがない…でも、どうして…",
  ui_story_5089_50891001_4_dialog_content = "ただこれだけのためにあれこれ策をめぐらしていたとは。\nまったく愚かにも程がある。",
  ui_story_5089_50891001_5_dialog_content = "鄴王として長く王座に座り続けてきたが、\n誰一人として異変に気づく者はいなかった。",
  ui_story_5089_50891001_6_dialog_content = "まさかその間余が面一つに頼り、\n亡霊のごとく生きてきたとでも思っていたのか？",
  ui_story_5089_50891001_7_dialog_content = "！",
  ui_story_5089_50891001_8_dialog_content = "10年前本物と入れ替わった時から、\n己の顔を少しずつ変えてきたのだよ。",
  ui_story_5089_50891001_9_dialog_content = "皮と肉を割き、骨を削り――",
  ui_story_5089_50891001_10_dialog_content = "腕の形が違うなら、切り落として新たな腕をつなげばよい。",
  ui_story_5089_50891001_11_dialog_content = "声が違うというのなら、毒を飲み、喉を潰せばよい。",
  ui_story_5089_50891001_12_dialog_content = "聞いたことがあるぞ…即位する前叔父はよく刺客に狙われておった、と…\nこういうことじゃったか。",
  ui_story_5089_50891001_13_dialog_content = "天命を受けし者の使命を果たすためとあらば、\nいかなる犠牲も惜しまぬというか。",
  ui_story_5089_50891001_14_dialog_content = "天命を受けし者だと？\nふっ、あやつらはただ影に潜んで暮らすネズミにすぎぬ。",
  ui_story_5089_50891001_15_dialog_content = "己を買い被るにも程がある。\n余の鄴の国に手を出さんとするとは！",
  ui_story_5089_50891001_16_dialog_content = "お主、何を…",
  ui_story_5089_50891001_17_dialog_content = "今や邪気祓いもさして効がなく、幼帝に天下を治める能もない。\n風雲急を告げ、乱世がまもなく訪れんとしている。",
  ui_story_5089_50891001_18_dialog_content = "済の国との関係を考え、穏やかに事を運ぼうと思ったこともあったが――",
  ui_story_5089_50891001_19_dialog_content = "かような事態となった今、\n天命を受けし者に火器を与えるのもまた上策といえよう。",
  ui_story_5089_50891001_20_dialog_content = "武器さえ手に入れば、あやつらはすぐに事を起こす。",
  ui_story_5089_50891001_21_dialog_content = "各国にはすでに天命を受けし者が深く入り込んでおる。皓津の水禍が各地で起こるであろう。\n各国が混乱している隙に天命を受けし者が央京へ向かう。",
  ui_story_5089_50891001_22_dialog_content = "そうなった時には、目の前の獲物に目がくらんだ虫ケラどもを\n余がすべて食らってしまえばよい。",
  ui_story_5089_50891001_23_dialog_content = "候風卿が「候」ち続けた「風」を…",
  ui_story_5089_50891001_24_dialog_content = "今度こそ己の手で起こしてみせる！",
  ui_story_5089_50891001_25_dialog_content = "余は10年間兵力を磨き、機を待ち続けてきた。",
  ui_story_5089_50891001_26_dialog_content = "群雄割拠の世が訪れし時、天命を受けし者の「波」はもはや必要ない。",
  ui_story_5089_50891001_27_dialog_content = "タンドウ、そちは余の秘密を知ってしまった。",
  ui_story_5089_50891001_28_dialog_content = "だが今日の行いは甚だ愚かといえど、その賢さは本物だ。\nどうだ、余に付いてこぬか？",
  ui_story_5089_50891001_29_dialog_content = "そちが首を縦に振りさえすれば、\n灼華郡主として生かしておいてやる。",
  ui_story_5089_50891001_30_dialog_content = "空の末裔、そちの能力は戦場で大いに役立つ。\n余の麾下に入らぬか？",
  ui_story_5089_50891001_31_dialog_content = "将来七国を手に入れた暁には…",
  ui_story_5089_50891001_32_dialog_content = "お主…それは天命を受けし者が妖魔や邪祟と結託し、\n人の命をも顧みぬ輩と知っての企みか？",
  ui_story_5089_50891001_33_dialog_content = "あやつらの武器は大方が鄴の国のものだ。\nもちろん承知しておる。",
  ui_story_5089_50891001_34_dialog_content = "だが役にも立たぬ他国の民の命など何を気遣う必要があるのだ？\n敵の境遇に心を痛めるのは女子どものすることだ。",
  ui_story_5089_50891001_35_dialog_content = "妖魔は畜生にも劣る愚かな生き物、取るに足らぬ。\n天命を受けし者はそもそもが卑しき者の集まり、使えるだけ使えばよいのだ。",
  ui_story_5089_50891001_36_dialog_content = "そちが好まぬというなら、使うだけ使った後に殺せばよい。",
  ui_story_5089_50891001_37_dialog_content = "お主の考えは分かった。どうやら――",
  ui_story_5089_50891001_38_dialog_content = "われらは同じ道を歩めぬようじゃ。",
  ui_story_5089_50891001_39_dialog_content = "身の程知らずめ。",
  ui_story_5089_50891001_40_dialog_content = "あの…聞きたいことがあるんですけど…",
  ui_story_5089_50891001_41_dialog_content = "そんなこと話しちゃって、大丈夫なんですか？",
  ui_story_5089_50891001_42_dialog_content = "すぐそこの工房には天命を受けし者が大勢集まってるんですよ？",
  ui_story_5089_50891001_43_dialog_content = "余はそちらとは違う。工房はすでに封じてある。",
  ui_story_5089_50891001_44_dialog_content = "あやつらが事を起こすには、余の火器が欠かせぬ。",
  ui_story_5089_50891001_45_dialog_content = "火器を引き渡した後は、工房の中の者どもが生きようが死のうが、余には関わりのないことだ。",
  ui_story_5089_50891001_46_dialog_content = "でも、もし3日以内に火器を渡せなかったら？",
  ui_story_5089_50891001_47_dialog_content = "…なにゆえそれを？",
  ui_story_5089_50891001_48_dialog_content = "あなたが言ってたみたいに、\n空の末裔の能力ってすごく役に立つんです。",
  ui_story_5089_50891001_49_dialog_content = "でも今重要なのはそこじゃなくて、\nあなたが3日の期限を守れそうにないってことじゃないですか？",
  ui_story_5089_50891001_50_dialog_content = "いったい何をした？",
  ui_story_5089_50891001_51_dialog_content = "大王様！大変です――",
  ui_story_5089_50891001_52_dialog_content = "何事だ！",
  ui_story_5089_50891001_53_dialog_content = "ひ…百工院が火龍輿の軌道を撤去しているのです。\n我々が計画していた輸送経路が…ことごとく使用不可となりました。",
  ui_story_5089_50891001_54_dialog_content = "誰が許可したのだ！？",
  ui_story_5089_50891001_55_dialog_content = "百工院の者が言うには…",
  ui_story_5089_50891001_56_dialog_content = "ある善良な投資家から寄付があったそうです。",
  ui_story_5089_50891001_57_dialog_content = "借用人がヘンな使い方をしたせいで、\nダメになってた軌道を直してもらおうと思っただけです。",
  ui_story_5089_50891001_58_dialog_content = "唯一の条件は、撤去の順序をこっちで決めさせてもらうこと。\n別に理不尽な条件でもないですよね？",
  ui_story_5089_50891001_59_dialog_content = "あなたたちの注意もこうしてそらしてあげたわけですし。",
  ui_story_5089_50891001_60_dialog_content = "今日の午後始めたとしても、軌道を完全に元に戻すには3日以上かかるはずです。",
  ui_story_5089_50891001_61_dialog_content = "最初から僕の目的は「道」にあったんです。",
  ui_story_5089_50891001_62_dialog_content = "青二才が小賢しいマネを！大王様、ご命令を…",
  ui_story_5089_50891001_63_dialog_content = "愚か者め、下がっておれ！",
  ui_story_5089_50891001_64_dialog_content = "確かに小賢しいマネかもしれません。",
  ui_story_5089_50891001_65_dialog_content = "でもあなたなら分かってますよね。\n今はもう僕がどんな手を使ったかなんてどうでもいいんです。",
  ui_story_5089_50891001_66_dialog_content = "百工院を味方につけるとは…ふむ、璇璣卿か。",
  ui_story_5089_50891001_67_dialog_content = "センキョクが牢に入れられたのは機巧砲を勝手に使ったからじゃない――\nあなたの秘密を知ったからですね？",
  ui_story_5089_50891001_68_dialog_content = "センキョクをちゃんと監禁できなかった時点で、\nあなたは負けていたんです。",
  ui_story_5089_50891001_69_dialog_content = "これからも王座に座り続けることができたとしても…",
  ui_story_5089_50891001_70_dialog_content = "朝廷の官僚も、天下の機巧師たちもこれからずっと\nあなたの一挙一動を見ています。",
  ui_story_5089_50891001_71_dialog_content = "火龍輿の軌道はいくらでも撤去できる。\n木牛流馬の轅（ながえ）は壊れるかもしれない。",
  ui_story_5089_50891001_72_dialog_content = "馬車を使うとしても、馬の体力が持つか分からない。",
  ui_story_5089_50891001_73_dialog_content = "火龍輿以外の道具はなおさらです。\n大量の貨物を短い時間で運ぶことなんてできませんよね。",
  ui_story_5089_50891001_74_dialog_content = "何より…",
  ui_story_5089_50891001_75_dialog_content = "記録に載っていない大量の火器を運び出す理由を\nどう説明するんですか？",
  ui_story_5089_50891001_76_dialog_content = "…",
  ui_story_5089_50891001_77_dialog_content = "「鄴王」様、申し訳ありません。",
  ui_story_5089_50891001_78_dialog_content = "この先はどうか分かりませんが――",
  ui_story_5089_50891001_79_dialog_content = "今「波」は僕たちの味方です。",
  ui_story_5089_50891001_80_dialog_content = "なるほど。",
  ui_story_5089_50891001_81_dialog_content = "そちが塞いだのは天命を受けし者の道ではなく、\n余の道だったか。",
  ui_story_5089_50891001_82_dialog_content = "われらが自ら網にかかったと言うたが、\n網にかかったのは己だとは思わなんだか？",
  ui_story_5089_50891001_83_dialog_content = "ここまでじゃ、候風卿。",
  ui_story_5089_50891001_84_dialog_content = "火器が期限までに届かねば、\n天命を受けし者も大人しくしてはおるまい。",
  ui_story_5089_50891001_85_dialog_content = "お主はどうやら忠義を尽くしておらんかったようじゃしのう。\n奴らがひとたびその気になれば、すぐに調べがつくはずじゃ。",
  ui_story_5089_50891001_86_dialog_content = "どうじゃ、落ち着いてわれらと話さぬか？",
  ui_story_5089_50891001_87_dialog_content = "妖魔も天命を受けし者も、お主の思うほど与し易い相手ではない。\nお主の企みは道理の通じない猛獣と取引せんとするも同じじゃ。",
  ui_story_5089_50891001_88_dialog_content = "はははは、落ち着いて話すだと？\n余は鄴の国の王ぞ！",
  ui_story_5089_50891001_89_dialog_content = "鄴の進むべき道は余が決める！",
  ui_story_5089_50891001_90_dialog_content = "誰の指図も受けぬ――！",
  ui_story_5089_50891001_91_dialog_content = "<color=#e8d9bb>ブスッ――</color>",
  ui_story_5089_50891001_92_dialog_content = "<color=#e8d9bb>刃が肉を切り裂く、鈍く低い音が響いた</color>",
  ui_story_5089_50891001_93_dialog_content = "<color=#e8d9bb>鮮血が辺り一面に飛び散る</color>",
  ui_story_5089_50891001_94_dialog_content = "候風卿――！",
  ui_story_5089_50891001_95_dialog_content = "<color=#e8d9bb>鋭い金属の鈎形の尾が「鄴王」の身体を背後から貫いた</color>",
  ui_story_5089_50891001_96_dialog_content = "あ、あれは…蠍獣！",
  ui_story_5089_50891001_97_dialog_content = "はぁ…大人しく言う事を聞いていればよかったものを。",
  ui_story_5089_50891001_98_dialog_content = "私の機巧術は長い年月をかけて磨き上げられた百家の粋を集めているの。\nこういう堅実さこそ確かな実を結ぶのよ。",
  ui_story_5089_50891001_99_dialog_content = "現実味のない志は、抱いたところで命を落とすだけ。",
  ui_story_5089_50891001_100_dialog_content = "き、貴様…！",
  ui_story_5089_50891001_101_dialog_content = "郡主様も一つだけいい事を言ったわ。",
  ui_story_5089_50891001_102_dialog_content = "天命を受けし者を甘く見てはいけない。",
  ui_story_5089_50891001_103_dialog_content = "主の命が下ったわ。鄴の国はもう必要ない。",
  ui_story_5089_50891001_104_dialog_content = "この土地は私がいただいくわ。好きに使わせてもらうわね。\n最大出力で蠍の火力試験をすることも許可されたの。",
  ui_story_5089_50891001_105_dialog_content = "あははは、こんなにいい事づくめとは思わなかったわ。\n「鄴王」様、あなたが燭陰火をくれたおかげよ。",
  ui_story_5089_50891001_106_dialog_content = "さてと…あの山を吹き飛ばせと命令が来てるわね。",
  ui_story_5089_50891001_107_dialog_content = "行くわよ、蠍。照準の調整やら動力源の準備やら…\nやることがたくさんあるの。",
  ui_story_5089_50891001_108_dialog_content = "<color=#e8d9bb>蠍が勢いよく尾を抜き去ると、「鄴王」はそのまま地面に横たわった</color>",
  ui_story_5089_50891001_109_dialog_content = "ああ、そうそう。使い物にならない裏切り者がまだいたわね…",
  ui_story_5089_50891001_110_dialog_content = "天命を受けし者よ、奴をこの場で処刑しなさい！",
  ui_story_5089_50891001_111_dialog_content = "大王様――！",
  ui_story_5089_50891001_112_dialog_content = "<color=#e8d9bb>遠くに控えていた璟良軍が前に出ようとしたその時、\nきれいに整っていた陣形が突然乱れた</color>",
  ui_story_5089_50891001_113_dialog_content = "<color=#e8d9bb>多くの兵が武器を取り、傍らにいる仲間を襲い出したのだ！</color>",
  ui_story_5089_50891001_114_dialog_content = "大変だ、「鄴王」様が――",
  ui_story_5089_50891001_115_dialog_content = "海棠灼々！",
  ui_story_5089_50891001_116_dialog_content = "タ、タンドウ…",
  ui_story_5089_50891001_117_dialog_content = "勘違いするでない。\nお主の誘いに乗る気は毛頭ない。",
  ui_story_5089_50891001_118_dialog_content = "じゃが、お主は今もわれらが天命を受けし者と対するコマの一つじゃ。",
  ui_story_5089_50891001_119_dialog_content = "それだけではない。片づけねばならぬ恩も仇も残っておろうが。",
  ui_story_5089_50891001_120_dialog_content = "余計なことを…ゲホッ…",
  ui_story_5089_50891001_121_dialog_content = "今立ち去らねば…後悔するぞ…",
  ui_story_5089_50891001_122_dialog_content = "後悔か。敢えて申せば、宮殿にいるうちに一か八か\nお主を引きずり降ろさんかったことじゃろうのう。",
  ui_story_5089_50891001_123_dialog_content = "あの山のふもとには罪のない民が大勢暮らしておる。\n国を養う食糧を育てる田畑も広がっておるのじゃぞ。",
  ui_story_5089_50891001_124_dialog_content = "ここで逃げなどしたら、鄴の国の郡主の名に恥じるわ！",
  ui_story_5089_50891001_125_dialog_content = "わらわもPlayerNameも傷一つないというのに、\nおめおめと逃げてたまるものか！",
  ui_story_5089_50891001_126_dialog_content = "ははは…まったく…予想外だったぞ…",
  ui_story_5089_50891001_127_dialog_content = "そちがここまで命知らずだったとは。",
  ui_story_5089_50891001_128_dialog_content = "だが、さような大口は…生き残ってから叩くがよい。",
  ui_story_5089_50891001_129_dialog_content = "<color=#e8d9bb>璟良軍内部の戦いが続く中、今度は工房から天命を受けし者の刺客たちが襲ってきた</color>",
  ui_story_5089_50891002_1_dialog_content = "このまま戦い続けても、不利になる一方ね。",
  ui_story_5089_50891002_2_dialog_content = "キュウさん。",
  ui_story_5089_50891002_3_dialog_content = "こんな光景を目にしても、まだ何も言う事はない？",
  ui_story_5089_50891002_4_dialog_content = "…",
  ui_story_5089_50891002_5_dialog_content = "はぁ…え？",
  ui_story_5089_50891002_6_dialog_content = "誰！？",
  ui_story_5089_50891002_7_dialog_content = "主の命を受け、邪魔者を排除する。",
  ui_story_5089_50891002_8_dialog_content = "チッ、ずいぶん深くまで入り込んでたのね。",
  ui_story_5089_50891002_9_dialog_content = "雷光奇制！",
  ui_story_5089_50891002_10_dialog_content = "…",
  ui_story_5089_50891002_11_dialog_content = "！",
  ui_story_5089_50891002_12_dialog_content = "どきなさい！",
  ui_story_5089_50891002_13_dialog_content = "キュウさん、他の事は傍観してて構わないけど…",
  ui_story_5089_50891002_14_dialog_content = "まさか、こんな恥知らずなヤツらの手にかかって命を落としたいの？",
  ui_story_5089_50891002_15_dialog_content = "…",
  ui_story_5089_50891101_1_dialog_content = "うっ――",
  ui_story_5089_50891101_2_dialog_content = "タンドウ、その調子だよ…ううっ…",
  ui_story_5089_50891101_3_dialog_content = "PlayerName、いかがしたのじゃ…な、なんという高熱じゃ！",
  ui_story_5089_50891101_4_dialog_content = "大丈夫だよ、ちょっと能力を使いすぎちゃって…\nすぐに回復するから…",
  ui_story_5089_50891101_5_dialog_content = "何がすぐに回復するじゃ！",
  ui_story_5089_50891101_6_dialog_content = "…いや、おかしい。",
  ui_story_5089_50891101_7_dialog_content = "お主の能力を見るのはこれが初めてではない。\nその力がいかほどのものか、よう承知しておるつもりじゃ。",
  ui_story_5089_50891101_8_dialog_content = "敵の数が多いとはいえ、これしきの戦いでお主が倒れるはずがない。",
  ui_story_5089_50891101_9_dialog_content = "いったい何をしておる！？",
  ui_story_5089_50891101_10_dialog_content = "…分かっちゃったか。",
  ui_story_5089_50891101_11_dialog_content = "ごめんね、ちゃんと話そうと思ってたんだけど、チャンスがなくて。",
  ui_story_5089_50891101_12_dialog_content = "今は…直接見てもらった方が早いかも。",
  ui_story_5089_50891101_13_dialog_content = "？",
  ui_story_5089_50891101_14_dialog_content = "感知。",
  ui_story_5089_50891101_15_dialog_content = "ようやくお話ができますね。",
  ui_story_5089_50891101_16_dialog_content = "ずっと待っていましたよ、タンドウ様。",
  ui_story_5089_50891101_17_dialog_content = "璇璣卿ではないか！そばにおるのは…",
  ui_story_5089_50891101_18_dialog_content = "ええ、積もる話もあるんですが、\nこちらにも招かれざる客が来ておりまして。",
  ui_story_5089_50891101_19_dialog_content = "センキョク、後ろ！",
  ui_story_5089_50891101_20_dialog_content = "雷光奇制！",
  ui_story_5089_50891101_21_dialog_content = "PlayerName、ありがとう。",
  ui_story_5089_50891101_22_dialog_content = "まさか…PlayerNameは同時に二つの戦闘を指揮しておったのか？\nゆえにかようなまでに消耗を？",
  ui_story_5089_50891101_23_dialog_content = "その通りです。でも、それだけではありませんよ。\n私との感知をどのくらい続けていたと思いますか？",
  ui_story_5089_50891101_24_dialog_content = "…",
  ui_story_5089_50891101_25_dialog_content = "PlayerName？",
  ui_story_5089_50891101_26_dialog_content = "そ、そう大して長くもないよ…昨日センキョクと別れた時に始めたから――",
  ui_story_5089_50891101_27_dialog_content = "もう丸一日が経ちます。",
  ui_story_5089_50891101_28_dialog_content = "センキョクがちゃんと話してくれないからだよ…",
  ui_story_5089_50891101_29_dialog_content = "それにちゃんと調整してたしね。\n何もない時は、そこまで強い感知はしてない…",
  ui_story_5089_50891101_30_dialog_content = "でも感知が途切れないように、今の今までろくに寝てないんでしょ？",
  ui_story_5089_50891101_31_dialog_content = "…",
  ui_story_5089_50891101_32_dialog_content = "しかも感知でつながってたのは私一人じゃない。",
  ui_story_5089_50891101_33_dialog_content = "そのことだけど…キュウに謝らなくちゃ。",
  ui_story_5089_50891101_34_dialog_content = "昨日の夜君の話を聞いて、何か嫌な予感がしたから、\nこっそり感知をつないでおいたんだ。",
  ui_story_5089_50891101_35_dialog_content = "「鄴王」と戦ってた時も見てたよ。",
  ui_story_5089_50891101_36_dialog_content = "君の気持ちは分かる。でも…",
  ui_story_5089_50891101_37_dialog_content = "あぶない！",
  ui_story_5089_50891101_38_dialog_content = "うう…",
  ui_story_5089_50891101_39_dialog_content = "タンドウ！大丈夫！？",
  ui_story_5089_50891101_40_dialog_content = "！",
  ui_story_5089_50891101_41_dialog_content = "キュウ！今は緊急事態だよ、1人でも多く仲間が欲しい！\n手伝って！",
  ui_story_5089_50891101_42_dialog_content = "し、しかし私は…",
  ui_story_5089_50891101_43_dialog_content = "<color=#e8d9bb>しばらく沈黙が続いた後、キュウは一つため息をついた</color>",
  ui_story_5089_50891101_44_dialog_content = "<color=#e8d9bb>キュウは黙ったまま刺客の近くに落ちていた短剣を取り、\n今まさにセンキョクと戦っている天命を受けし者に襲いかかった</color>",
  ui_story_5089_50891101_45_dialog_content = "！",
  ui_story_5089_50891101_46_dialog_content = "<color=#e8d9bb>刺客が慌ててかわすと、短剣はゆがんだ弧を描き、\n刺客の傍らをかすめた後、キュウの手を離れ、壁に刺さった</color>",
  ui_story_5089_50891101_47_dialog_content = "キュウさん、あなた…",
  ui_story_5089_50891101_48_dialog_content = "これまで刀は体の一部も同然でした。",
  ui_story_5089_50891101_49_dialog_content = "傷を受けようとも、血を流そうとも、何ともありませんでした。",
  ui_story_5089_50891101_50_dialog_content = "私には刀の描くべき道がはっきりと見えていたのです。\n恩と仇――その二つに向かって伸びる道が…",
  ui_story_5089_50891101_51_dialog_content = "しかし今はもう見えなくなってしまいました。\n刀に見捨てられて当然です。",
  ui_story_5089_50891101_52_dialog_content = "ご覧の通りです。私にはもう刀は振れません。",
  ui_story_5089_50891101_53_dialog_content = "キュウ…",
  ui_story_5089_50891101_54_dialog_content = "PlayerName、今戦況は厳しい。\n何の関わりもない者と無駄話をしておる暇はないぞ。",
  ui_story_5089_50891101_55_dialog_content = "幾度か迷ったこともあったが、\n今思うに、かような護衛は切り捨てて正解じゃった。",
  ui_story_5089_50891101_56_dialog_content = "タンドウ？",
  ui_story_5089_50891101_57_dialog_content = "10年もの間剣術を磨き続けたというに、\nたった一日でそのすべてを捨ててしまう――",
  ui_story_5089_50891101_58_dialog_content = "あやつに剣術を授けたという天下一の剣客も\n名ばかりであったようじゃのう。",
  ui_story_5089_50891101_59_dialog_content = "…未熟な私がいけないのです。\n恩師をけなすのは、どうかおやめください。",
  ui_story_5089_50891101_60_dialog_content = "恩師じゃと？真か？",
  ui_story_5089_50891101_61_dialog_content = "師から受けた恩をお主はその刀に込めたことがあるのか？",
  ui_story_5089_50891101_62_dialog_content = "…",
  ui_story_5089_50891101_63_dialog_content = "恩だ仇だとこだわるのならば、わらわが教えてやろう。",
  ui_story_5089_50891101_64_dialog_content = "父母から授かった命、隣近所の助け、師の教えが「恩」なれば――",
  ui_story_5089_50891101_65_dialog_content = "蜃風号でユエ船長や璇璣卿が力を尽くし、\nそのおかげでわれらが今生きておることもまた「恩」じゃ。",
  ui_story_5089_50891101_66_dialog_content = "PlayerNameが今もお主を見捨てることなく、\n気に掛けておるのもまた「恩」じゃ。",
  ui_story_5089_50891101_67_dialog_content = "じゃがお主はそれらを何とも思っておらんかったようじゃのう。\n皆の心を踏みにじりおって。",
  ui_story_5089_50891101_68_dialog_content = "…殿下は…人の心がお分かりになるというのですか。",
  ui_story_5089_50891101_69_dialog_content = "言われずとも分かっております。\n私はこれまで多くの方に助けていただきました。",
  ui_story_5089_50891101_70_dialog_content = "しかし、殿下こそ本当に分かっていらっしゃるのですか？",
  ui_story_5089_50891101_71_dialog_content = "私は殿下のお側で一時たりとも怠ることなく、\n護衛の名に恥じない務めを果たして参りました。",
  ui_story_5089_50891101_72_dialog_content = "しかし殿下は何も言わず、私を履き古した靴のようにお捨てになりました！",
  ui_story_5089_50891101_73_dialog_content = "おや、怒れるのじゃのう。",
  ui_story_5089_50891101_74_dialog_content = "お主は血も涙もない、ただの人形かと思うておったが。",
  ui_story_5089_50891101_75_dialog_content = "失望されましたか？",
  ui_story_5089_50891101_76_dialog_content = "うむ。",
  ui_story_5089_50891101_77_dialog_content = "まだ感情があるならば、\nこれまで多くの者に助けられてきたと分かっておるならば――",
  ui_story_5089_50891101_78_dialog_content = "なにゆえ恩や仇にこだわる！",
  ui_story_5089_50891101_79_dialog_content = "殿下…？",
  ui_story_5089_50891101_80_dialog_content = "タンドウ、後ろ！",
  ui_story_5089_50891101_81_dialog_content = "海棠灼々！",
  ui_story_5089_50891101_82_dialog_content = "<color=#e8d9bb>無数の海棠の花が大きな波となり、辺り一帯を覆い――</color>",
  ui_story_5089_50891101_83_dialog_content = "お主に言わねばならぬことがある。",
  ui_story_5089_50891101_84_dialog_content = "わらわが護衛の職を解いたのは、お主が不忠だからではない。\nお主が分かっておらぬからじゃ。",
  ui_story_5089_50891101_85_dialog_content = "<color=#e8d9bb>あっという間に視界を埋め尽くす</color>",
  ui_story_5089_50891101_86_dialog_content = "<color=#e8d9bb>そこにいた誰もが花の海に心奪われ、\nその美しい光景をただ茫然と眺めていた</color>",
  ui_story_5089_50891101_87_dialog_content = "<color=#e8d9bb>タンドウは血色に染まった着物をまとい、凛とした光を目に輝やかせ、立っていた。\nその美しさは花の中にあって最も美しく、最も人々を魅了した</color>",
  ui_story_5089_50891101_88_dialog_content = "天に五十の理（ことわり）あり、されど人の道は一つなり。",
  ui_story_5089_50891101_89_dialog_content = "理不尽な天でさえも人の道を閉ざしておらぬというに、\nなにゆえお主は己の道を閉ざすのじゃ！",
  ui_story_5089_50891101_90_dialog_content = "宿では言えず仕舞いじゃったことを今言おう。",
  ui_story_5089_50891101_91_dialog_content = "籠に囲うて鳥の美しき羽根を愛で――",
  ui_story_5089_50891101_92_dialog_content = "虎の命を奪い、はぎ取った虎斑の皮をまとうは――",
  ui_story_5089_50891101_93_dialog_content = "真の愛とはいえぬ。",
  ui_story_5089_50891101_94_dialog_content = "万物は生まれながらにして自由じゃ。\n真にそれを愛するならば、鳥は空に、虎は山に放つべきじゃ。",
  ui_story_5089_50891101_95_dialog_content = "お主が真相にたどり着くよう仕向けたのは、\nその枷や鎖からお主を解き放ちたいと思うたからじゃ。",
  ui_story_5089_50891101_96_dialog_content = "命令だからと守られるのはもうまっぴらじゃ。\n影に潜む刃など、わらわは要らぬ。",
  ui_story_5089_50891101_97_dialog_content = "お主には胸を張り、陽の光の下で自由に生きてほしいのじゃ。",
  ui_story_5089_50891101_98_dialog_content = "万の民が声高らかに讃える将軍となり、\nお主の名がわらわの名と共に並ぶ日を待ちわびておるのじゃ。",
  ui_story_5089_50891101_99_dialog_content = "命令ではなく、己の意志でわらわに付いてきてほしい。",
  ui_story_5089_50891101_100_dialog_content = "わらわは――",
  ui_story_5089_50891101_101_dialog_content = "お主の真の主となりたいのじゃ！",
  ui_story_5089_50891101_102_dialog_content = "タンドウ…殿下…",
  ui_story_5089_50891101_103_dialog_content = "お主はもうわらわの護衛ではない。\nゆえに命令はせぬ。",
  ui_story_5089_50891101_104_dialog_content = "じゃが、命令にも恩や仇にも、面の下の小さな視野にも縛られぬ今、\nまだわらわの力となる意志があるならば――",
  ui_story_5089_50891101_105_dialog_content = "立ち上がるのじゃ！這ってでも立ち上がれ――",
  ui_story_5089_50891101_106_dialog_content = "キュウ！",
  ui_story_5089_50891101_107_dialog_content = "わらわの元へ来い！",
  ui_story_5089_50891101_108_dialog_content = "…以前申し上げたか分かりませんが、\nタンドウ殿下は時にとても我が儘でいらっしゃいます。",
  ui_story_5089_50891101_109_dialog_content = "覚えがないのう。",
  ui_story_5089_50891101_110_dialog_content = "ここへ来て申すがよい。",
  ui_story_5089_50891101_111_dialog_content = "…",
  ui_story_5089_50891101_112_dialog_content = "承知いたしました。",
  ui_story_5089_50891101_113_dialog_content = "<color=#e8d9bb>しばらくして――</color>",
  ui_story_5089_50891101_114_dialog_content = "<color=#e8d9bb>ドーン！</color>",
  ui_story_5089_50891101_115_dialog_content = "<color=#e8d9bb>修復したばかりの宮殿の門が再び崩れ落ちた</color>",
  ui_story_5089_50891101_116_dialog_content = "大罪人が脱獄した！追え！",
  ui_story_5089_50891101_117_dialog_content = "先輩、ただ今戻りました。これは…いったい何があったのですか？",
  ui_story_5089_50891101_118_dialog_content = "大したことじゃないわ。\nやっとお隣さんができたのにいなくなっちゃっただけ。ふぅ。",
  ui_story_5089_50891101_119_dialog_content = "今私の横をかすめていったのは…あのお嬢さんだったのですか？",
  ui_story_5089_50891101_120_dialog_content = "先に行って道を拓いてもらうことにしましょ。\n戦って疲れちゃった…少し休むことにするわ。",
  ui_story_5089_50891101_121_dialog_content = "まったく…あ、お待ちください。",
  ui_story_5089_50891101_122_dialog_content = "もしやあのお嬢さん、武器も持たずに出て行かれたのですか？",
  ui_story_5089_50891101_123_dialog_content = "当たり前でしょ。\n彼女の実力なら宮殿を真っ二つにすることくらい朝飯前なのよ。",
  ui_story_5089_50891101_124_dialog_content = "私が王様でも、刀を持たせたまま牢に入れるなんてことしないわ。",
  ui_story_5089_50891101_125_dialog_content = "では、素手で璟良軍全軍に立ち向かうのですか！？\n心配ではないのですか？",
  ui_story_5089_50891101_126_dialog_content = "何の心配をする必要があるの？",
  ui_story_5089_50891101_127_dialog_content = "暗い顔して黙ってた時ならまだしも――",
  ui_story_5089_50891101_128_dialog_content = "今の彼女を止められるヤツなんていない。",
  ui_story_5089_50891101_129_dialog_content = "見つけたぞ！ここだ、すでに包囲した！",
  ui_story_5089_50891101_130_dialog_content = "向こうは武器を持っていない、捕らえろ！",
  ui_story_5089_50891101_131_dialog_content = "どうやらご存知ないようですね。",
  ui_story_5089_50891101_132_dialog_content = "たとえ刀や剣でなくとも、ひとたび剣客が握れば、万物は刃と化すのです。",
  ui_story_5089_50891101_133_dialog_content = "<color=#e8d9bb>さっと身を翻すと、キュウはそのまま夜の闇の中に消えていった。そして――</color>",
  ui_story_5089_50891101_134_dialog_content = "<color=#e8d9bb>花びらが宙を舞い――</color>",
  ui_story_5089_50891101_135_dialog_content = "な、なんだ…これは…",
  ui_story_5089_50891101_136_dialog_content = "<color=#e8d9bb>木の葉が舞う</color>",
  ui_story_5089_50891101_137_dialog_content = "おい、何をしている？そんな所に転がって何を…うっ！",
  ui_story_5089_50891101_138_dialog_content = "<color=#e8d9bb>青竹が突然上から覆いかぶさってくる</color>",
  ui_story_5089_50891101_139_dialog_content = "下がれ！急げ、うわあああ――",
  ui_story_5089_50891101_140_dialog_content = "<color=#e8d9bb>黒い影がさっと闇をかすめる</color>",
  ui_story_5089_50891101_141_dialog_content = "あそこだ！食らえ！",
  ui_story_5089_50891101_142_dialog_content = "な、なに…？これは…外套ではないか…奴はどこへ行っ…う！",
  ui_story_5089_50891101_143_dialog_content = "<color=#e8d9bb>瞬く間に大勢の兵士を斬り倒した</color>",
  ui_story_5089_50891101_144_dialog_content = "こ、こいつ…悪鬼だ！",
  ui_story_5089_50891101_145_dialog_content = "いいえ、人です。",
  ui_story_5089_50891101_146_dialog_content = "妖魔ではありません。",
  ui_story_5089_50891101_147_dialog_content = "ようやく分かったのです。\nですから道を開けてくださいませんか？",
  ui_story_5089_50891101_148_dialog_content = "急いでいるのです。",
  ui_story_5089_50891101_149_dialog_content = "…やれ。",
  ui_story_5089_50891101_150_dialog_content = "はぁ…",
  ui_story_5089_50891101_151_dialog_content = "<color=#e8d9bb>キュウは腰をかがめ、倒れた兵の側に落ちていた槍を拾うと、\n軽々と柄を降り、刀の代わりにした</color>",
  ui_story_5089_50891101_152_dialog_content = "どけ。",
  ui_story_5089_50891101_153_dialog_content = "私は――",
  ui_story_5089_50891101_154_dialog_content = "殿下のお側へ戻るのだ！",
  ui_story_5089_50891201_1_dialog_content = "PlayerName、テイトの位置は分かったか？",
  ui_story_5089_50891201_2_dialog_content = "この先だよ！",
  ui_story_5089_50891201_3_dialog_content = "チッ。",
  ui_story_5089_50891201_4_dialog_content = "あれだけの人数がそろっても止められないとは。",
  ui_story_5089_50891201_5_dialog_content = "カラクリ獣の方がよっぽど役に立つわ。",
  ui_story_5089_50891201_6_dialog_content = "じゃがお主の蠍は確か、われらに粉々にされたのではなかったかのう？",
  ui_story_5089_50891201_7_dialog_content = "そうだよ。それにすぐに援軍も来るんだ。\n今のうちに降参した方が身のためだよ。",
  ui_story_5089_50891201_8_dialog_content = "援軍？まあ恐ろしいこと。",
  ui_story_5089_50891201_9_dialog_content = "でもいくら援軍が来ようと、人でしょう？\n本気で山崩れに立ち向かうつもりなのかしら？",
  ui_story_5089_50891201_10_dialog_content = "そんな無駄な事に時間を使うくらいなら、\n辺りの住民を避難させた方がいいのではなくて？",
  ui_story_5089_50891201_11_dialog_content = "今簡単に計算してみたの。\nあの山が崩れれば、辺り一帯の田畑はすべて土に埋まってしまう。",
  ui_story_5089_50891201_12_dialog_content = "だから私にこの一見おかしな任務が与えられたわけね。",
  ui_story_5089_50891201_13_dialog_content = "ここは鄴の国で最も重要な穀物の産地なのでしょう？\n今年は一粒の収穫も望めなさそうね。",
  ui_story_5089_50891201_14_dialog_content = "済の国も鄴の国の食糧を買い占めているというし、\n下手すると大飢饉になるわね。",
  ui_story_5089_50891201_15_dialog_content = "君も鄴の国の人でしょ？どうしてこんなことできるの！？",
  ui_story_5089_50891201_16_dialog_content = "言ったはずよ。\n私の機巧術を認めてくれる人――それが私の主よ。",
  ui_story_5089_50891201_17_dialog_content = "いかん、PlayerName。\nあやつの話に乗ってはならぬ。",
  ui_story_5089_50891201_18_dialog_content = "あやつは時を稼いでおるのだ…テイト、蠍はどこじゃ？",
  ui_story_5089_50891201_19_dialog_content = "ふふふ、残念ね。もう遅いわ。",
  ui_story_5089_50891201_20_dialog_content = "あそこに光が見えるでしょう？",
  ui_story_5089_50891201_21_dialog_content = "蠍の攻撃準備は整っている。燭陰火も全開。\nもうすぐあの山は花火のように…パーン！",
  ui_story_5089_50891201_22_dialog_content = "爆発するの。",
  ui_story_5089_50891201_23_dialog_content = "おかしくなったか！？\nさような暴挙に出れば、お主も無事ではいられぬ。",
  ui_story_5089_50891201_24_dialog_content = "自分の命を守る術なら心得ているわ。",
  ui_story_5089_50891201_25_dialog_content = "蠍は修復再生後、全力攻撃するのは今回が初めてなの。\n近くで効果を確認しなくてわね。",
  ui_story_5089_50891201_26_dialog_content = "嬉しいでしょう？こんな機会滅多にないわよ。",
  ui_story_5089_50891201_27_dialog_content = "…PlayerName、こやつに構わず、まずは蠍を止めに行くぞ！",
  ui_story_5089_50891201_28_dialog_content = "もう遅いわよ。",
  ui_story_5089_50891201_29_dialog_content = "<color=#e8d9bb>ドオオーーン！！</color>",
  ui_story_5089_50891201_30_dialog_content = "<color=#e8d9bb>刺すような光が大きな山を貫き、\n砕けた無数の岩や石が雨のように落ちてきた</color>",
  ui_story_5089_50891201_31_dialog_content = "璟良軍よ、候…大王を連れてゆけ！\n周囲を捜索し、民を救助し次第即刻退去じゃ！",
  ui_story_5089_50891201_32_dialog_content = "話の途中で立ち去るとは、郡主様にあるまじき非礼ね。",
  ui_story_5089_50891201_33_dialog_content = "<color=#e8d9bb>崩れた岩石の中に紛れていたカラクリ獣がタンドウに襲いかかる！</color>",
  ui_story_5089_50891201_34_dialog_content = "あぶない！",
  ui_story_5089_50891201_35_dialog_content = "この先は危険だ、帰れ。",
  ui_story_5089_50891201_36_dialog_content = "ですから、今さっき天の道から地の理まで説明したでしょう？\nまだ信じられませんかねぇ。",
  ui_story_5089_50891201_37_dialog_content = "卦象にこの先で天が崩れ、地が裂けると出てるんでございますよ。",
  ui_story_5089_50891201_38_dialog_content = "急いでこの刀を持ち主に返さないことには、\n崩れる天を支え、裂ける地を塞ぐことはできないんですって。",
  ui_story_5089_50891201_39_dialog_content = "真にそんな事が起こっているなら璟良軍が解決する。\nお前は帰れ。",
  ui_story_5089_50891201_40_dialog_content = "はぁ…ですから、そこを何とか――",
  ui_story_5089_50891201_41_dialog_content = "<color=#e8d9bb>ドオオーーン…</color>",
  ui_story_5089_50891201_42_dialog_content = "な、なに！？山が…こんなことが…！",
  ui_story_5089_50891201_43_dialog_content = "ほら、言ったでしょう？",
  ui_story_5089_50891201_44_dialog_content = "では急いでるもんで、先に失礼しますよ！",
  ui_story_5089_50891201_45_dialog_content = "待て！お前…",
  ui_story_5089_50891201_46_dialog_content = "<color=#e8d9bb>突然黒い風が横をかすめたような気がした</color>",
  ui_story_5089_50891201_47_dialog_content = "今…誰か通ったか？",
  ui_story_5089_50891201_48_dialog_content = "海棠灼々！",
  ui_story_5089_50891201_49_dialog_content = "うっ！",
  ui_story_5089_50891201_50_dialog_content = "海で会った時よりも強くなっているようね。",
  ui_story_5089_50891201_51_dialog_content = "誰もがお主のように今有る物を使う脳しかなく、\n己の力では前に進めぬ輩と思うたら大間違いじゃぞ。",
  ui_story_5089_50891201_52_dialog_content = "ふふ、言う事だけは立派ね。",
  ui_story_5089_50891201_53_dialog_content = "出てきなさい！",
  ui_story_5089_50891201_54_dialog_content = "その「今有る物」の手から生き延びられるかどうか、\n見せてもらおうではないの。",
  ui_story_5089_50891201_55_dialog_content = "！",
  ui_story_5089_50891201_56_dialog_content = "（タンドウはもう限界だ…このままじゃダメだ…）",
  ui_story_5089_50891201_57_dialog_content = "（山崩れもまだ収まらない…どうすれば…）",
  ui_story_5089_50891201_58_dialog_content = "<color=#e8d9bb>シュッ――</color>",
  ui_story_5089_50891201_59_dialog_content = "<color=#e8d9bb>色濃い夜の闇の中に一筋の雷光が走った</color>",
  ui_story_5089_50891201_60_dialog_content = "キュウ！",
  ui_story_5089_50891201_61_dialog_content = "遅いぞ！",
  ui_story_5089_50891201_62_dialog_content = "タンドウ殿下、よくお考えください。\nこれでも最速で参上いたしました。",
  ui_story_5089_50891201_63_dialog_content = "しかし…お詫び申し上げます。",
  ui_story_5089_50891201_64_dialog_content = "お側に戻るのが遅くなりました。",
  ui_story_5089_50891201_65_dialog_content = "分かればよい。",
  ui_story_5089_50891201_66_dialog_content = "チッ、邪魔な奴が現れたわね。",
  ui_story_5089_50891201_67_dialog_content = "でも、あなたたちが3人そろったところで、\nこの工房すべてのカラクリ獣に勝てるのかしら？",
  ui_story_5089_50891201_68_dialog_content = "グォォ！！！",
  ui_story_5089_50891201_69_dialog_content = "私1人で十分です。",
  ui_story_5089_50891201_70_dialog_content = "タンドウ殿下とPlayerName様に近づく者は、\nこの刀が許しません！",
  ui_story_5089_50891201_71_dialog_content = "（その後の戦いは「まぶしい」としか形容のしようがなかった）",
  ui_story_5089_50891201_72_dialog_content = "（次から次へと押し寄せるカラクリ獣とひと時も止むことなく落ちてくる石を前に、\nキュウは一歩も動くことなく――）",
  ui_story_5089_50891201_73_dialog_content = "（地面に落ちている武器や枝、木の葉、石、さらにはカラクリ獣の残骸さえも…）",
  ui_story_5089_50891201_74_dialog_content = "（目に映るすべてがキュウの手の中で刃に変わり、まるで無敵の武器のようだ）",
  ui_story_5089_50891201_75_dialog_content = "羿（げい）が九日を射落とし、群帝が龍に乗りて翔ぶ様を見ているようじゃのう。",
  ui_story_5089_50891201_76_dialog_content = "雷（いかづち）のごとく激しく、水面（みなも）のごとく穏やか――",
  ui_story_5089_50891201_77_dialog_content = "見つけたのじゃのう…己の道を。",
  ui_story_5089_50891201_78_dialog_content = "グアアア――",
  ui_story_5089_50891201_79_dialog_content = "ど、どうなっているの？ただの人がここまで戦えるはずがないわ…",
  ui_story_5089_50891201_80_dialog_content = "まだよ――！",
  ui_story_5089_50891201_81_dialog_content = "<color=#e8d9bb>しかし、テイトがカラクリ獣に号令をかける間もなく、\nキュウはその背後に回っていた</color>",
  ui_story_5089_50891201_82_dialog_content = "動くな。",
  ui_story_5089_50891201_83_dialog_content = "！",
  ui_story_5089_50891201_84_dialog_content = "ふっ…私を捉えて何が変わるというの？",
  ui_story_5089_50891201_85_dialog_content = "天命を受けし者が蠍を回収するわ。\n私の最強のカラクリ獣は引き続き戦場でその威力を発揮する。",
  ui_story_5089_50891201_86_dialog_content = "それにいくらあなたが強くても、山崩れは止められない！",
  ui_story_5089_50891201_87_dialog_content = "<color=#e8d9bb>ドオオーーン！</color>",
  ui_story_5089_50891201_88_dialog_content = "<color=#e8d9bb>鉱山内で凄まじい圧力に耐えていた岩石の層が不吉な音を発し、\nたくさんの巨石が大地をも砕き割る勢いで落ちてきた</color>",
  ui_story_5089_50891201_89_dialog_content = "大変だ、タンドウ、キュウ！\n急いでここを離れなきゃ！",
  ui_story_5089_50891201_90_dialog_content = "そうするしかあるまい。\n住民は璟良軍がすでに避難させておるはずじゃ。",
  ui_story_5089_50891201_91_dialog_content = "後のことはまた後に考えるとしよう。",
  ui_story_5089_50891201_92_dialog_content = "キュウ、何を考え込んでおるのじゃ？",
  ui_story_5089_50891201_93_dialog_content = "止められます。",
  ui_story_5089_50891201_94_dialog_content = "何じゃと？",
  ui_story_5089_50891201_95_dialog_content = "師匠がおっしゃっていました。\n「驚霆剣」は山をも拓き海をも分かつと。",
  ui_story_5089_50891201_96_dialog_content = "でも教わってないんでしょ…？",
  ui_story_5089_50891201_97_dialog_content = "今まで師匠の「教えられない」という言葉はただの言い訳だと思っていました。",
  ui_story_5089_50891201_98_dialog_content = "しかし今分かりました。\n「驚霆剣」は教えられるものではないのです。",
  ui_story_5089_50891201_99_dialog_content = "なぜなら「驚霆剣」は技ではなく――",
  ui_story_5089_50891201_100_dialog_content = "心だからです。",
  ui_story_5089_50891201_101_dialog_content = "だとしても、今の君には剣が…",
  ui_story_5089_50891201_102_dialog_content = "み、皆さん！は、早く手を貸してください！",
  ui_story_5089_50891201_103_dialog_content = "やっ、ややや…！こんなたくさんの落石、かわせませんよ――",
  ui_story_5089_50891201_104_dialog_content = "テンカン、かような時に手間をかけるでない！",
  ui_story_5089_50891201_105_dialog_content = "いや実はですね、卦象に…って、ややや！\nこりゃひどい落石ですねぇ、先に進めやしません。",
  ui_story_5089_50891201_106_dialog_content = "キュウさん、刀を持ってきましたよ。\n受け取ってくださいっ！",
  ui_story_5089_50891201_107_dialog_content = "そうはさせないわ！",
  ui_story_5089_50891201_108_dialog_content = "！",
  ui_story_5089_50891201_109_dialog_content = "<color=#e8d9bb>テンカンが剣を投げるとほぼ同時に、\n数匹の火吹き蟹がタンドウに襲いかかった</color>",
  ui_story_5089_50891201_110_dialog_content = "<color=#e8d9bb>キュウは足を取られ、刀は最後に襲ってきた火吹き蟹が奪ったまま、\n落石の最も激しい場所へと落ちていった</color>",
  ui_story_5089_50891201_111_dialog_content = "<color=#e8d9bb>火吹き蟹は一瞬で落石に潰され、刀はその傍らにカタンと落ちた</color>",
  ui_story_5089_50891201_112_dialog_content = "…僕が拾ってくる！",
  ui_story_5089_50891201_113_dialog_content = "PlayerName！/PlayerName様！",
  ui_story_5089_50891201_114_dialog_content = "感知！",
  ui_story_5089_50891201_115_dialog_content = "（落石の位置さえ分かれば、通り抜けられる！）",
  ui_story_5089_50891201_116_dialog_content = "取ったよ！",
  ui_story_5089_50891201_117_dialog_content = "<color=#e8d9bb>ドオオーーン！</color>",
  ui_story_5089_50891201_118_dialog_content = "<color=#e8d9bb>大地が轟音を立てながら震え、\n今までなんとか持ちこたえていた鉱山がついに完全に崩れた</color>",
  ui_story_5089_50891201_119_dialog_content = "（ダメだ、数が多すぎる…かわせない！）",
  ui_story_5089_50891201_120_dialog_content = "<color=#e8d9bb>その瞬間金色の光が輝いた</color>",
  ui_story_5089_50891201_121_dialog_content = "…石が…宙に浮いてる…？",
  ui_story_5089_50891201_122_dialog_content = "<color=#e8d9bb>かつて見た金色の蓮の花が頭上を覆い、\nありとあらゆる危険をその花弁の外に留めてくれていた</color>",
  ui_story_5089_50891201_123_dialog_content = "ポケットの中が熱い…\n確かシンゲイにもらった葉っぱしか入ってなかったはずだけど…",
  ui_story_5089_50891201_124_dialog_content = "<color=#e8d9bb>ポケットの中に入っていたのはただの葉っぱではなかった</color>",
  ui_story_5089_50891201_125_dialog_content = "<color=#e8d9bb>金色の光が波のように輝く龍の鱗</color>",
  ui_story_5089_50891201_126_dialog_content = "…シンゲイ、ありがとう。",
  ui_story_5089_50891201_127_dialog_content = "今度会ったら、お菓子をたくさん食べさせてあげる…",
  ui_story_5089_50891201_128_dialog_content = "キュウ、刀だよ！受け取って――！",
  ui_story_5089_50891201_129_dialog_content = "ありがとうございます。",
  ui_story_5089_50891201_130_dialog_content = "<color=#e8d9bb>山が崩れ落ちていく様は、まるで巨人が倒れ、\nあるいは天地が崩れ落ちるかのような光景</color>",
  ui_story_5089_50891201_131_dialog_content = "<color=#e8d9bb>その轟音や震動もよそに、キュウは目を閉じ、周囲のあらゆる情報を遮断する</color>",
  ui_story_5089_50891201_132_dialog_content = "師匠、今ようやく刀を振るうとは何たるか、分かった気がします。",
  ui_story_5089_50891201_133_dialog_content = "天に五十の理（ことわり）あり、されど人の道は一つなり。",
  ui_story_5089_50891201_134_dialog_content = "理不尽な天でさえも人の道を閉ざしておらぬというに、\nなにゆえお主は己の道を閉ざすのじゃ！",
  ui_story_5089_50891201_135_dialog_content = "期限か…そうだな…",
  ui_story_5089_50891201_136_dialog_content = "君が恩返しや仇討ちのために刀を振るうことがなくなるまでにしよう。",
  ui_story_5089_50891201_137_dialog_content = "キュウさん、一つ聞いてもいい？",
  ui_story_5089_50891201_138_dialog_content = "人と妖魔の違いって何かしら？",
  ui_story_5089_50891201_139_dialog_content = "センキョク様、やはり私が愚かだったようです。\nあの時私にはあなた様の問いの意味が分かりませんでした。",
  ui_story_5089_50891201_140_dialog_content = "しかし幸いにも、私には迷った時手を差し伸べてくれる人たちがいます。",
  ui_story_5089_50891201_141_dialog_content = "これが…私の答えです。",
  ui_story_5089_50891201_142_dialog_content = "人と妖魔の違いとは、私たちは決して本能や命令で動く道具ではなく――",
  ui_story_5089_50891201_143_dialog_content = "そのようなものがなくとも、抜け殻になることなく――",
  ui_story_5089_50891201_144_dialog_content = "迷おうとも、深淵に堕ちようとも、愚かさに縛られ身動きが取れなくなろうとも、\n無数の人の暖かさと思いやりに包まれている存在だということです。",
  ui_story_5089_50891201_145_dialog_content = "その暖かさは闇に覆われる狭い影から私たちを救い出し――",
  ui_story_5089_50891201_146_dialog_content = "陽の光の下で、堂々と生きる勇気を与えてくれるのです！",
  ui_story_5089_50891201_147_dialog_content = "<color=#e8d9bb>キュウはぱっと目を開け、目にもとまらぬ速さで刀を振った</color>",
  ui_story_5089_50891201_148_dialog_content = "<color=#e8d9bb>山が割れ、天地がうなり声をあげる</color>",
  ui_story_5089_50891201_149_dialog_content = "<color=#e8d9bb>それはとても激しく、とても軽やかな一振りだった</color>",
  ui_story_5089_50891201_150_dialog_content = "この一振りは恩返しのためでも、仇討ちのためでもありません。",
  ui_story_5089_50891201_151_dialog_content = "<color=#e8d9bb>これまでに自分を暖かく包んでくれたすべての友に贈るプレゼントだ</color>",
  ui_story_5089_50891201_152_dialog_content = "<color=#e8d9bb>刀から放たれた光は岩石や山をかすめ、\n無敵の力が触れる物すべてを切り裂いていく</color>",
  ui_story_5089_50891201_153_dialog_content = "すごい…",
  ui_story_5089_50891201_154_dialog_content = "<color=#e8d9bb>再び顔を上げた時には、ついさっきまで轟音を立てながら崩れていた山が\n砂と土となって元の場所に広がっていた</color>",
  ui_story_5089_50891201_155_dialog_content = "<color=#e8d9bb>霜刃は空を貫き、刀剣は驚霆となる</color>",
  ui_story_5089_50891201_156_dialog_content = "<color=#e8d9bb>遠くの山では――</color>",
  ui_story_5089_50891201_157_dialog_content = "センキョク先輩…今の攻撃は…もうありませんよね？",
  ui_story_5089_50891201_158_dialog_content = "たぶんね。",
  ui_story_5089_50891201_159_dialog_content = "まさか、あそこまでの威力とは思わなかったわ。",
  ui_story_5089_50891201_160_dialog_content = "こんなに離れてるのに蠍が真っ二つになっ…あら？",
  ui_story_5089_50891201_161_dialog_content = "先輩…それ、まさか…燭陰火ですか！？",
  ui_story_5089_50891201_162_dialog_content = "いつも言ってるでしょ。機巧師は言葉も厳密でなくちゃ。",
  ui_story_5089_50891201_163_dialog_content = "今は「燭火」と「陰火」と呼ぶべきね。",
  ui_story_5089_50891201_164_dialog_content = "このような時に冗談ですか！",
  ui_story_5089_50891201_165_dialog_content = "こ、これは我が門派の宝ですよ！\nそ、それが…ま、真っ二つに――！",
  ui_story_5089_50891201_166_dialog_content = "それにしても、きれいに真ん中で割れてるわね。",
  ui_story_5089_50891201_167_dialog_content = "キュウさん、大手柄よ。",
  ui_story_5089_50891201_168_dialog_content = "何をおっしゃっているのですか！\n師匠や門派に何と言えば…",
  ui_story_5089_50891201_169_dialog_content = "あ、そのことなら私に任せて。心配いらないわ。",
  ui_story_5089_50891201_170_dialog_content = "さあ、急いで同門に知らせましょ。\nここのカラクリ獣は片付けたことだし、今度はあっちを手伝ってあげないと。",
  ui_story_5089_50891201_171_dialog_content = "うちの門派から裏切者が出たんだもの。\n事後処理もしっかりしないとね。",
  ui_story_5089_50891201_172_dialog_content = "はい。",
  ui_story_5089_50891201_173_dialog_content = "ふぅ。",
  ui_story_5089_50891201_174_dialog_content = "キュウ、大丈夫？",
  ui_story_5089_50891201_175_dialog_content = "何ともありません。ただ少し力が抜けてしまって…",
  ui_story_5089_50891201_176_dialog_content = "待って！よく見たら全身血だらけじゃないか！\nこんな状態で戦ってたの？",
  ui_story_5089_50891201_177_dialog_content = "急いで治療しよう！",
  ui_story_5089_50891201_178_dialog_content = "PlayerName様、ありがとうございます。\nしかし私にはまだやる事があるのです。",
  ui_story_5089_50891201_179_dialog_content = "そんな状態で何を言ってるの！？",
  ui_story_5089_50891201_180_dialog_content = "タンドウ、君も何とか言ってよ！",
  ui_story_5089_50891201_181_dialog_content = "PlayerName、好きにさせてやろう。",
  ui_story_5089_50891201_182_dialog_content = "すべて終わらせなければならぬ。",
  ui_story_5089_50891201_183_dialog_content = "いったい何を…あ、そうか。",
  ui_story_5089_50891201_184_dialog_content = "終わりに…しなきゃだね。",
  ui_story_5089_50891201_185_dialog_content = "キュウか。",
  ui_story_5089_50891201_186_dialog_content = "はい。",
  ui_story_5089_50891201_187_dialog_content = "誰か、剣を持て。",
  ui_story_5089_50891201_188_dialog_content = "大王様、おけがされているのです。動いてはなりません！",
  ui_story_5089_50891201_189_dialog_content = "剣を持て。",
  ui_story_5089_50891201_190_dialog_content = "決着をつけねばならぬ。",
  ui_story_5089_50891201_191_dialog_content = "<color=#e8d9bb>キュウは懐から面を取り出し、被った</color>",
  ui_story_5089_50891201_192_dialog_content = "お手合わせ願います。",
  ui_story_5089_50891202_1_dialog_content = "<color=#e8d9bb>カン――</color>",
  ui_story_5089_50891202_2_dialog_content = "<color=#e8d9bb>2つの人影が交差したかと思うと、「鄴王」の剣が宙に飛び上がった</color>",
  ui_story_5089_50891202_3_dialog_content = "ッ…ゴホゴホ…",
  ui_story_5089_50891202_4_dialog_content = "大王様！も…もう…お止めください！",
  ui_story_5089_50891202_5_dialog_content = "勝負はついた。",
  ui_story_5089_50891202_6_dialog_content = "余の負けだ。",
  ui_story_5089_50891202_7_dialog_content = "…",
  ui_story_5089_50891202_8_dialog_content = "<color=#e8d9bb>パラッ</color>",
  ui_story_5089_50891202_9_dialog_content = "<color=#e8d9bb>キュウの面が剣の起こした風によって二つに割られ、地面に落ちた</color>",
  ui_story_5089_50891202_10_dialog_content = "これで恩も仇もすべてなくなりました。",
  ui_story_5089_50891202_11_dialog_content = "ああ。",
  ui_story_5089_50891202_12_dialog_content = "行け。",
  ui_story_5089_50891202_13_dialog_content = "<color=#e8d9bb>キュウは刀を納め、遠くにいるタンドウに向かって一礼すると、身を翻し立ち去った</color>",
  ui_story_5089_50891202_14_dialog_content = "<color=#e8d9bb>再び振り返ることはなかった</color>",
  ui_story_5089_50891300_1_dialog_content = "<color=#e8d9bb>済の国、王宮</color>",
  ui_story_5089_50891300_2_dialog_content = "父上、父上！許嫁から贈り物が届いたと聞きました！",
  ui_story_5089_50891300_3_dialog_content = "うむ。",
  ui_story_5089_50891300_4_dialog_content = "早く見せてください！",
  ui_story_5089_50891300_5_dialog_content = "ただの金にすぎぬ。",
  ui_story_5089_50891300_6_dialog_content = "あれ？これは僕が贈ったものではないですか？",
  ui_story_5089_50891300_7_dialog_content = "気に入らなかったのでしょうか？…あ、分かりました！\n英雄はこうした俗なものを好まないのですね。",
  ui_story_5089_50891300_8_dialog_content = "もっと心のこもったものを贈らなければ…よし、すぐに用意しよう！",
  ui_story_5089_50891300_9_dialog_content = "まったく…",
  ui_story_5089_50891300_10_dialog_content = "あの方はお世継ぎから贈られた金で、\n済の者が鄴の国で買い付けた食糧をすべて買い上げたそうですが、その意図は明らかです。",
  ui_story_5089_50891300_11_dialog_content = "大王様、いかがなさるおつもりですか？",
  ui_story_5089_50891300_12_dialog_content = "PlayerNameは余自らが認めた済の国の友人である。\n皓津を救ってくれた恩にもいまだ報いておらぬ。",
  ui_story_5089_50891300_13_dialog_content = "PlayerNameのしたことならば、顔を立ててやろうではないか。",
  ui_story_5089_50891300_14_dialog_content = "ただし次にまた鄴の国が不義をはたらくようであれば、\n黙ってはおらぬ。",
  ui_story_5089_50891300_15_dialog_content = "御意にございます。",
  ui_story_5089_50891300_16_dialog_content = "<color=#e8d9bb>パサッ――</color>",
  ui_story_5089_50891300_17_dialog_content = "<color=#e8d9bb>多くの人が行き交う埠頭から、また一隻の大船が帆を揚げ、出航した</color>",
  ui_story_5089_50891300_18_dialog_content = "あれからキュウは戻ってないの？",
  ui_story_5089_50891300_19_dialog_content = "あやつを自由にしてやったのはわらわじゃ。\n本人の意思を尊重せねばのう。",
  ui_story_5089_50891300_20_dialog_content = "たとえ二度と戻らずとも、キュウという心の友がいたことは一生忘れぬ。",
  ui_story_5089_50891300_21_dialog_content = "そういうPlayerNameはこれからいかがするつもりじゃ？",
  ui_story_5089_50891300_22_dialog_content = "え？僕たち今済の国に向かってるんでしょ？",
  ui_story_5089_50891300_23_dialog_content = "タンドウが言ったんだよ。天命を受けし者っていう共通の敵がいる今、\n一時争いをやめるよう済と鄴の両方を説得するって…",
  ui_story_5089_50891300_24_dialog_content = "僕も残りの金を返しに行かなきゃいけないし…あ、まだ候風卿…\nいや、鄴王様に代わりに金を返してくれたお礼を言ってなかった…",
  ui_story_5089_50891300_25_dialog_content = "それはそうと、あのまま王位に就かせていいの？",
  ui_story_5089_50891300_26_dialog_content = "他に術がないのじゃ。",
  ui_story_5089_50891300_27_dialog_content = "本物の叔父はあの様子じゃ。姉上もまだ国を治める準備ができておらぬ。\n今の鄴の国はほんのわずかな乱れにも耐えられぬのじゃ。",
  ui_story_5089_50891300_28_dialog_content = "候風卿は確かに傲慢に過ぎるが、\n鄴の国を思う心は本物じゃ。",
  ui_story_5089_50891300_29_dialog_content = "しかも今は璇璣卿と百工院を始めとする朝廷勢力が歯止めとなっておる。\nひとまず何の波風も起こせまい。",
  ui_story_5089_50891300_30_dialog_content = "ただわらわが聞いたのはそのことではないぞ。\nもっと先の話じゃ。",
  ui_story_5089_50891300_31_dialog_content = "そうだなぁ…皓津に行って、璟良にも来たから、\n今度は龍州の他の所へ行ってみたいな。",
  ui_story_5089_50891300_32_dialog_content = "でも長いことアストラを離れてたから、一度帰った方がいいかな？\nそうじゃないとバイスやカレンたちが心配する…",
  ui_story_5089_50891300_33_dialog_content = "タンドウ、どう思う？",
  ui_story_5089_50891300_34_dialog_content = "何を言うておるのじゃ？",
  ui_story_5089_50891300_35_dialog_content = "お主は籠の中の鳥でも、檻の中の獣でもない。\nわらわに聞いてどうする？",
  ui_story_5089_50891300_36_dialog_content = "鳥でも獣でもないなら、僕は何なのかな？",
  ui_story_5089_50891300_37_dialog_content = "そうじゃのう…",
  ui_story_5089_50891300_38_dialog_content = "<color=#e8d9bb>朝日の下でタンドウはほほ笑み、視線を挙げた。\nその厳かな瞳の中には明るい光が輝いていた</color>",
  ui_story_5089_50891300_39_dialog_content = "大鳥じゃ。",
  ui_story_5089_50891300_40_dialog_content = "いつしかその大きな翼を広げ、雲間を翔ぶであろう。",
  ui_story_5089_50891300_41_dialog_content = "ちょっと褒めすぎじゃないかな？",
  ui_story_5089_50891300_42_dialog_content = "いいや。",
  ui_story_5089_50891300_43_dialog_content = "おい！見ろ、海の上に人がいる！船を追ってくるぞ！",
  ui_story_5089_50891300_44_dialog_content = "何を寝ぼけたことを言ってやがる。海の上に人なんて…\nりゅ、龍女様！？本当に人だ！",
  ui_story_5089_50891300_45_dialog_content = "あっちで何を騒いでるんだろう？…うわ！",
  ui_story_5089_50891300_46_dialog_content = "あれ…キュウじゃない！？",
  ui_story_5089_50891300_47_dialog_content = "<color=#e8d9bb>船はすでに岸から遠く離れた水域を航行していたが、\n1つの人影が水面の上を駆け、こちらへと向かってくる</color>",
  ui_story_5089_50891300_48_dialog_content = "<color=#e8d9bb>その人影はあっという間に甲板近くまで迫り、\n無数の驚嘆の声の中、さっと飛び上がった</color>",
  ui_story_5089_50891300_49_dialog_content = "<color=#e8d9bb>キュウが冷たいしぶきと共に降り立った</color>",
  ui_story_5089_50891300_50_dialog_content = "タンドウ殿下、使者として他国へ向かうというのに\n護衛もお連れにならないとは不用心が過ぎるのではありませんか？",
  ui_story_5089_50891300_51_dialog_content = "決心はついたか？",
  ui_story_5089_50891300_52_dialog_content = "また此度のようなことがあれば、今度こそ許さぬぞ。",
  ui_story_5089_50891300_53_dialog_content = "心は決まっております。",
  ui_story_5089_50891300_54_dialog_content = "決して使命に恥ずる真似はいたしません。",
  ui_story_5089_50891300_55_dialog_content = "ならば、よい。",
  ui_story_5089_50891300_56_dialog_content = "天命を受けし者の脅威は兆の国全土に広がっておる。\n済の国を訪れし後は他の諸侯国の様子も見に行かねばならぬのう。",
  ui_story_5089_50891300_57_dialog_content = "今兆の国は決して穏やかではありません。なぜ殿下自ら出向かれるのですか？\n済の国以外の諸侯国は人を遣ればよいではありませんか。",
  ui_story_5089_50891300_58_dialog_content = "天下を巡り、縦横に策を通ず――かような機会はそうはあるまい。",
  ui_story_5089_50891300_59_dialog_content = "わらわは幼き頃より国のために尽くすことを志としてきた。\n危険があろうと、あきらめなどせぬ。",
  ui_story_5089_50891300_60_dialog_content = "大魚も大鳥も自由の身となった。この世に行けぬ所などなかろう。",
  ui_story_5089_50891300_61_dialog_content = "天下を巡り歩く度胸もなくして、\nいつしか大鳥を伴とする望みなど抱けようか？",
  ui_story_5089_50891300_62_dialog_content = "この先には、まだ長い旅路が続いておるのじゃ。",
  ui_story_5089_50891300_63_dialog_content = "<color=#e8d9bb>ある茶館で――</color>",
  ui_story_5089_50891300_64_dialog_content = "…こうして灼華郡主と異国の使者は再びそれぞれの旅路へと戻っていきました。",
  ui_story_5089_50891300_65_dialog_content = "この度の動乱も表向きは、なんとか治まったというわけです。",
  ui_story_5089_50891300_66_dialog_content = "さあさあ、皆さま。お話はひとまずここまで。\n憐れな鳥の主にどうか投げ銭を！",
  ui_story_5089_50891300_67_dialog_content = "はい？なんですって？作り話？\nそりゃあ濡れ衣ってもんでございますよ。",
  ui_story_5089_50891300_68_dialog_content = "今お話ししたことはすべて真実、証拠に詩を聞かせて差し上げましょう。",
  ui_story_5089_50891300_69_dialog_content = "海を刻みて舟は行き、海棠灼々として咲きほこる。",
  ui_story_5089_50891300_70_dialog_content = "春新たな晩に龍が舞い、風雷海を鎮めん。",
  ui_story_5089_50891300_71_dialog_content = "驚霆霜刃を凌ぎ、妖魔羅刹も塵となる。",
  ui_story_5089_50891300_72_dialog_content = "鳥は籠を破りて雲間に翔び、逍遥にして天広し。",
  ui_story_5089_50891300_73_dialog_content = "さあ「灼華行」の物語もこれでお終いです。",
  ui_story_5089_50891300_74_dialog_content = "もちろん、主人公の旅はまだまだ続きます。\nご興味のある方は――",
  ui_story_5089_50891300_75_dialog_content = "<color=#e8d9bb>パン！</color>",
  ui_story_5089_50891300_76_dialog_content = "<color=#e8d9bb>釈台を叩く音が鳴り響く。\n巻物がゆっくりと巻き戻り、ロウソクが消え、幕が下りた</color>",
  ui_story_5089_50891300_77_dialog_content = "また次回のお話で…天下のどこぞでお会いしましょう。",
  ui_story_5089_50891400_1_dialog_content = "決心はついたのですか？",
  ui_story_5089_50891400_2_dialog_content = "この一歩を踏み出せば、\n今いる仲間の皆さんとお別れすることになりますよ。",
  ui_story_5089_50891400_3_dialog_content = "これまでに築き上げてきた多くの絆を捨てることになります。",
  ui_story_5089_50891400_4_dialog_content = "それでも、あなたはあの方のために「遠方」へ行くのですね。",
  ui_story_5089_50891400_5_option_content = "うん。",
  ui_story_5089_50891400_6_option_content = "もう決めたんだ。",
  ui_story_5089_50891400_7_dialog_content = "…",
  ui_story_5089_50891400_8_dialog_content = "龍州へ行って、前よりずっと勇敢になりましたね。",
  ui_story_5089_50891400_9_dialog_content = "では、お別れをしに行きましょう。",
  ui_story_5089_50891400_10_dialog_content = "最後に皆さんとお別れをするのです。",
  ui_story_5089_50891400_11_dialog_content = "アストラを一周するんだね？",
  ui_story_5089_50891400_12_dialog_content = "初めて皆と出会った時みたいに！",
  ui_story_5089_50891400_13_dialog_content = "ああ？わざわざ「お別れ」しに来たって？",
  ui_story_5089_50891400_14_dialog_content = "何言ってやがんだ、どうせ戻ってくるんだろが。",
  ui_story_5089_50891400_15_option_content = "それは…分からない…",
  ui_story_5089_50891400_16_option_content = "うん…",
  ui_story_5089_50891400_17_dialog_content = "おい、こっち来い。",
  ui_story_5089_50891400_18_dialog_content = "男はな、こうすりゃ何もかも分かり合えるってもんだ。",
  ui_story_5089_50891400_19_dialog_content = "お前にもいろいろ事情があるんだろ？",
  ui_story_5089_50891400_20_dialog_content = "…ありがとよ。いろいろ助けてくれてよ。",
  ui_story_5089_50891400_21_dialog_content = "戻ったら、ちゃんと知らせろよ。",
  ui_story_5089_50891400_22_dialog_content = "ま、キツくなったら俺たちんとこ来いよ。\n歓迎するぜ。",
  ui_story_5089_50891400_23_dialog_content = "うん、ありがとう。",
  ui_story_5089_50891400_24_dialog_content = "クソッ、お前のせいで俺までしんみりしちまったじゃねえかよ。",
  ui_story_5089_50891400_25_dialog_content = "行けよ、イブにも一言あいさつしてやってくれ。",
  ui_story_5089_50891400_26_dialog_content = "またね、サメヤマ。",
  ui_story_5089_50891400_27_dialog_content = "…おう、またな。PlayerName。",
  ui_story_5089_50891400_28_dialog_content = "え、そんな…しばらく戻ってこないの？",
  ui_story_5089_50891400_29_dialog_content = "いや、それは僕にもよく分からなくて…",
  ui_story_5089_50891400_30_dialog_content = "な、泣かないで！サメヤマに見られたら大変だから！",
  ui_story_5089_50891400_31_dialog_content = "でも…",
  ui_story_5089_50891400_32_dialog_content = "絶対にまた会えるから！",
  ui_story_5089_50891400_33_dialog_content = "次に「帰って」きたら――",
  ui_story_5089_50891400_34_dialog_content = "その時には、アストラでは体験できない事をたくさんお土産話に持って帰ってくるから！",
  ui_story_5089_50891400_35_dialog_content = "約束だよ。",
  ui_story_5089_50891400_36_dialog_content = "うん、約束だ！",
  ui_story_5089_50891400_37_dialog_content = "ゆびきりしよう。",
  ui_story_5089_50891400_38_dialog_content = "うん！",
  ui_story_5089_50891400_39_dialog_content = "あ、一緒にみんなのところへ行こう。",
  ui_story_5089_50891400_40_dialog_content = "ずっと会いたがってたんだから。",
  ui_story_5089_50891400_41_dialog_content = "あなたが連れてきた「お嬢様」がR・Wで暮らしてるところ、\nまだ見たことなかったよね？",
  ui_story_5089_50891400_42_dialog_content = "ほら、それから、「不死鳥アタル」さんも…",
  ui_story_5089_50891400_43_dialog_content = "イブ？",
  ui_story_5089_50891400_44_dialog_content = "ごめんなさい、泣かないって約束したのに…",
  ui_story_5089_50891400_45_dialog_content = "でも…いろんなことあったなって、急に思い出しちゃって…",
  ui_story_5089_50891400_46_dialog_content = "そうだね。一緒にいろんなこと体験してきたよね。",
  ui_story_5089_50891400_47_dialog_content = "たくさんの仲間ができて、皆それぞれ変わってく…",
  ui_story_5089_50891400_48_dialog_content = "やっぱり僕はここが好きだなぁ。",
  ui_story_5089_50891400_49_dialog_content = "龍州の火鍋みたいで。",
  ui_story_5089_50891400_50_dialog_content = "だから…イブも大丈夫だって信じてる。",
  ui_story_5089_50891400_51_dialog_content = "だって皆が側にいてくれるんだから。",
  ui_story_5089_50891400_52_dialog_content = "う、うん…わかった…",
  ui_story_5089_50891400_53_dialog_content = "PlayerNameが帰ってくるの、待ってる…\nみんなと一緒に笑いながら待ってるよ！",
  ui_story_5089_50891400_54_dialog_content = "行こう、他の皆ともお別れしなきゃ。",
  ui_story_5089_50891400_55_dialog_content = "話は聞いています。",
  ui_story_5089_50891400_56_dialog_content = "バイスのためだというのなら、止める理由はありません。",
  ui_story_5089_50891400_57_dialog_content = "バイスは休暇扱いにしておきました。\n他に何か助けが必要なことがあれば言ってください。",
  ui_story_5089_50891400_58_dialog_content = "いいえ、十分です。\nヒイロさんと大元帥さんには心から感謝してます。",
  ui_story_5089_50891400_59_dialog_content = "今度の旅はまったくの「未知」なんです。",
  ui_story_5089_50891400_60_dialog_content = "だから、できるだけ自分たちだけで行こうと思うんです。",
  ui_story_5089_50891400_61_dialog_content = "そうだとしても、私たちは喜んでお手伝いします。",
  ui_story_5089_50891400_62_dialog_content = "あなたが行ってしまったら、皆寂しがります。",
  ui_story_5089_50891400_63_dialog_content = "特に「ひきこもり」のバートンはひどく寂しがるでしょうね。",
  ui_story_5089_50891400_64_dialog_content = "あ、あの…任務がない時は、ガルーに頼んでゲームに付き合ってもらうのはどうですか？\n引きこもってるよりいいと思うんですけど…",
  ui_story_5089_50891400_65_dialog_content = "ふふ、冗談です。",
  ui_story_5089_50891400_66_dialog_content = "今は長官がついているので、バートンも忙しくしています。",
  ui_story_5089_50891400_67_dialog_content = "ヒイロさんが冗談なんて…意外です…",
  ui_story_5089_50891400_68_dialog_content = "あなたの影響かもしれません。",
  ui_story_5089_50891400_69_dialog_content = "大元帥様さえお変わりになられたのです。\n私が変わっても不思議はありません。",
  ui_story_5089_50891400_70_dialog_content = "…",
  ui_story_5089_50891400_71_dialog_content = "どうかお気を付けて。",
  ui_story_5089_50891400_72_dialog_content = "はい！",
  ui_story_5089_50891400_73_dialog_content = "おーい、こっちだ、こっち！",
  ui_story_5089_50891400_74_dialog_content = "ナビゲーター、やっほー！",
  ui_story_5089_50891400_75_dialog_content = "お別れ言いにきたよ。",
  ui_story_5089_50891400_76_dialog_content = "おいおい、なんだよ。今日に限ってさっさと離陸しちまうんだな。",
  ui_story_5089_50891400_77_dialog_content = "おーい――！PlayerName！",
  ui_story_5089_50891400_78_dialog_content = "1日3食しっかり食うんだぞぉ、身体を大切にしろよぉ！",
  ui_story_5089_50891400_79_dialog_content = "バイスもゼッタイ連れて帰ってくんだよぉ。",
  ui_story_5089_50891400_80_dialog_content = "うん！必ず連れて帰ってくるよ！",
  ui_story_5089_50891400_81_dialog_content = "必ず無事に連れて帰るから！",
  ui_story_5089_50891400_82_dialog_content = "あの小僧め…バイスは啓光の軍人だということを忘れたか。\n当然のように連れて行きおって…",
  ui_story_5089_50891400_83_dialog_content = "お会いにはならないのですか？",
  ui_story_5089_50891400_84_dialog_content = "うむ。",
  ui_story_5089_50891400_85_dialog_content = "あやつには自由の翼がある。\n余計な負担はかけたくないからな。",
  ui_story_5089_50891400_86_dialog_content = "この先は「PlayerName」自身が己の旅路を切り拓き、己の物語をつむぐのだ。",
  ui_story_5089_50891400_87_dialog_content = "私にできることは、友人として静かにあの翼に祝福を贈ることだ。",
  ui_story_5089_50891400_88_dialog_content = "…お前も戻れ。我々にも決断すべき事があるだろう？",
  ui_story_5089_50891400_89_dialog_content = "お別れねぇ…",
  ui_story_5089_50891400_90_dialog_content = "…",
  ui_story_5089_50891400_91_dialog_content = "ビクトリア様もパロマもパソロもいないんだけど…",
  ui_story_5089_50891400_92_dialog_content = "君がいるでしょ？",
  ui_story_5089_50891400_93_dialog_content = "君にだけでも、会ってお別れが言えて――",
  ui_story_5089_50891400_94_dialog_content = "よかった。",
  ui_story_5089_50891400_95_dialog_content = "ちゃんと言わないと、心残りになっちゃうから。",
  ui_story_5089_50891400_96_dialog_content = "！？",
  ui_story_5089_50891400_97_dialog_content = "パロマに会えなかったのは残念だけど…",
  ui_story_5089_50891400_98_dialog_content = "ビクトリアが代わりに伝えてくれるかもしれないね。あはは…",
  ui_story_5089_50891400_99_dialog_content = "それも無理なら――",
  ui_story_5089_50891400_100_dialog_content = "ねえ、隠者さん――",
  ui_story_5089_50891400_101_dialog_content = "どうかビクトリアたちに伝えてくださいね。",
  ui_story_5089_50891400_102_dialog_content = "…誰と話してるの？",
  ui_story_5089_50891400_103_dialog_content = "あははは、そうだね。",
  ui_story_5089_50891400_104_dialog_content = "…",
  ui_story_5089_50891400_105_dialog_content = "ねえ…",
  ui_story_5089_50891400_106_dialog_content = "無事に帰ってきなさいよ。",
  ui_story_5089_50891400_107_dialog_content = "うん、もちろんだよ。",
  ui_story_5089_50891400_108_dialog_content = "じゃあね。",
  ui_story_5089_50891400_109_dialog_content = "ええ、じゃあ。",
  ui_story_5089_50891400_110_dialog_content = "…これで最後です。",
  ui_story_5089_50891400_111_dialog_content = "影ノ街総合商会と、それから…「空ファン」からの支援物資です。",
  ui_story_5089_50891400_112_dialog_content = "影ノ街には、挨拶に来ただけなのに、\nこんなにたくさんもらったら…",
  ui_story_5089_50891400_113_dialog_content = "何だか申し訳ないな。",
  ui_story_5089_50891400_114_dialog_content = "お前はこれから先もずっと影ノ街の友であり、我々の友だ。",
  ui_story_5089_50891400_115_dialog_content = "遠慮なく受け取れ。",
  ui_story_5089_50891400_116_dialog_content = "うわ！イ、イスタバンさん、いつからいたんですか…",
  ui_story_5089_50891400_117_dialog_content = "ハハハ。これからお前が行こうとしている場所には影の目は届かない。",
  ui_story_5089_50891400_118_dialog_content = "十分注意するんだぞ。",
  ui_story_5089_50891400_119_dialog_content = "はい。",
  ui_story_5089_50891400_120_dialog_content = "…ベセル、後は任せた。",
  ui_story_5089_50891400_121_dialog_content = "…",
  ui_story_5089_50891400_122_dialog_content = "ルークにスモーキー、ジュヌヴィエーヴ、それからナルセールさんもお待ちです。",
  ui_story_5089_50891400_123_dialog_content = "あなたは本当に人望が厚いのですね。\nアストラ中の人がお別れを言い来ていますよ。",
  ui_story_5089_50891400_124_dialog_content = "うん…",
  ui_story_5089_50891400_125_dialog_content = "僕も皆にちゃんとお別れを言ってから旅立ちたい。",
  ui_story_5089_50891400_126_dialog_content = "ベセルにも。",
  ui_story_5089_50891400_127_dialog_content = "…！",
  ui_story_5089_50891400_128_dialog_content = "…今回の旅は長くなるのですか？",
  ui_story_5089_50891400_129_dialog_content = "分からない…帰ってこられるかどうかも分からないんだ。",
  ui_story_5089_50891400_130_dialog_content = "でも、何があっても皆のことは忘れないよ。",
  ui_story_5089_50891400_131_dialog_content = "また戻ってくるためにも、全力を尽くすよ。",
  ui_story_5089_50891400_132_dialog_content = "PlayerNameさん…",
  ui_story_5089_50891400_133_dialog_content = "お気をつけて。",
  ui_story_5089_50891400_134_dialog_content = "何か面白い小説を見つけたら、持って帰ってきてあげるね。",
  ui_story_5089_50891400_135_dialog_content = "カフェで皆と一緒に読もう！",
  ui_story_5089_50891400_136_dialog_content = "じゃあ…",
  ui_story_5089_50891400_137_dialog_content = "またね、ベセル。",
  ui_story_5089_50891400_138_dialog_content = "いた、ここだ。",
  ui_story_5089_50891400_139_dialog_content = "PlayerName！",
  ui_story_5089_50891400_140_dialog_content = "またね！",
  ui_story_5089_50891400_141_dialog_content = "あ…",
  ui_story_5089_50891400_142_dialog_content = "またね――",
  ui_story_5089_50891400_143_dialog_content = "これからもあなたたちの旅路が\nステキな歌と希望に包まれますように…",
  ui_story_5089_50891400_144_dialog_content = "…さようなら。",
  ui_story_5089_50891400_145_dialog_content = "え？一緒に行きたいってこと？",
  ui_story_5089_50891400_146_dialog_content = "そ、そんなに行きたいってわけじゃないわよ。",
  ui_story_5089_50891400_147_dialog_content = "でも「幻想の地」とか何とかいう所へ行くんでしょ？面白そうじゃない。",
  ui_story_5089_50891400_148_dialog_content = "アントニーも興味津々だったわ。\n私はアントニーよりはちょっと暇だし、興味もって当然じゃないかしら？",
  ui_story_5089_50891400_149_dialog_content = "あれれー？最後かもしれないのに本当のこと伝えなくていいのぉ？後悔するわよー。",
  ui_story_5089_50891400_150_dialog_content = "…",
  ui_story_5089_50891400_151_dialog_content = "そなたはアストラの明けの明星だ。\nそのそなたが未知の旅に出るとなれば、確かに不安にもなる。",
  ui_story_5089_50891400_152_dialog_content = "そう？じゃ、こういうのはどう？",
  ui_story_5089_50891400_153_dialog_content = "ナビゲーターさんが望むなら、用心棒を5人捕まえてきてあげる。",
  ui_story_5089_50891400_154_dialog_content = "全属性の用心棒をそろえれば、どんな旅だって…",
  ui_story_5089_50891400_155_dialog_content = "だが、私にはそなたの未来が見える。",
  ui_story_5089_50891400_156_dialog_content = "そこにも無限の光が広がっている。",
  ui_story_5089_50891400_157_dialog_content = "そなたが真に戦う場所は未来なのかもしれぬ。",
  ui_story_5089_50891400_158_dialog_content = "きわめて現実的でありながら、幻想に満ちあふれる地――\nそなたがさらなる幸福を目指して戦う場所だ。",
  ui_story_5089_50891400_159_dialog_content = "そして、そなた自身の道だ。",
  ui_story_5089_50891400_160_dialog_content = "そなたを案ずる気持ちでいっぱいだが、\nそれでも祝福を贈ろう。",
  ui_story_5089_50891400_161_dialog_content = "ありがとうございます。\n皆さんの祝福のおかげで、安心して旅に出ることができます。",
  ui_story_5089_50891400_162_dialog_content = "あら、あたくしたちにレベルアップして、ファントムを叩っ斬るチャンスはくれないの？",
  ui_story_5089_50891400_163_dialog_content = "退屈で仕方ないんだけど。",
  ui_story_5089_50891400_164_dialog_content = "でもフレイヤ、ここで楽しく暮らしてるんでしょ？",
  ui_story_5089_50891400_165_dialog_content = "それはそうだけど…",
  ui_story_5089_50891400_166_dialog_content = "故郷も見に行ったし、我が家の「宝物」も確認したし、\n新しい服ももらった…",
  ui_story_5089_50891400_167_dialog_content = "目覚めた途端、急に大事にされてるって感じでなんか調子狂っちゃうわ。",
  ui_story_5089_50891400_168_dialog_content = "でも、あたくしがそれだけで満足すると思ってんの？",
  ui_story_5089_50891400_169_dialog_content = "いきなりやって来て、いろいろ聞かせてくれたと思ったら、\nあたくしたちには付いてくるなって？",
  ui_story_5089_50891400_170_dialog_content = "とんだお預け食らった気分よ…",
  ui_story_5089_50891400_171_dialog_content = "ちょっとだけでいいわ、連れて行ってくれない？",
  ui_story_5089_50891400_172_dialog_content = "だってあたくしの夢は――",
  ui_story_5089_50891400_173_dialog_content = "またね、フレイヤ。",
  ui_story_5089_50891400_174_dialog_content = "…",
  ui_story_5089_50891400_175_dialog_content = "君がこんなふうに楽しそうに「心」から笑ってるのを見て――",
  ui_story_5089_50891400_176_dialog_content = "安心したよ。",
  ui_story_5089_50891400_177_dialog_content = "…ちゃんとお別れ言っていきなさいよ。",
  ui_story_5089_50891400_178_dialog_content = "うん。",
  ui_story_5089_50891400_179_dialog_content = "ベツレヘムさん、さようなら。",
  ui_story_5089_50891400_180_dialog_content = "さよなら。",
  ui_story_5089_50891400_181_dialog_content = "皆宮殿の外で待っている。",
  ui_story_5089_50891400_182_dialog_content = "行くがよい、PlayerName。",
  ui_story_5089_50891400_183_dialog_content = "じゃあね、ザーリャ。",
  ui_story_5089_50891400_184_dialog_content = "一緒に行きたい。",
  ui_story_5089_50891400_185_dialog_content = "えっ？",
  ui_story_5089_50891400_186_dialog_content = "いいえ、何でもないわ。",
  ui_story_5089_50891400_187_dialog_content = "さようなら…",
  ui_story_5089_50891400_188_dialog_content = "あららー…さ、おいで。お姉様が人生ってものを教えてあげるわー。",
  ui_story_5089_50891400_189_dialog_content = "ちょっと！？",
  ui_story_5089_50891400_190_dialog_content = "滅多にないチャンスよー。貴方が「女の子」になれるのなんて、\n女王陛下と私みたいなお姉様の前くらいでしょ？",
  ui_story_5089_50891400_191_dialog_content = "ちょっと！！",
  ui_story_5089_50891400_192_dialog_content = "…ここで、最後だね。",
  ui_story_5089_50891400_193_dialog_content = "PlayerNameさん…必ず戻ってきてください。",
  ui_story_5089_50891400_194_dialog_content = "うん、またね、ライン。皆にも伝えておいて。",
  ui_story_5089_50891400_195_dialog_content = "さあ、舞台を主人公に返す時がきたようですね。",
  ui_story_5089_50891400_196_dialog_content = "行きましょう、皆さん。",
  ui_story_5089_50891400_197_dialog_content = "…",
  ui_story_5089_50891400_198_dialog_content = "…",
  ui_story_5089_50891400_199_dialog_content = "どうしたの？お別れを言いに来たのではないの？",
  ui_story_5089_50891400_200_dialog_content = "どうしてか分からないけど…急に言葉が、出て来なくなっちゃって…",
  ui_story_5089_50891400_201_dialog_content = "じゃ、マヤに言わせて！",
  ui_story_5089_50891400_202_dialog_content = "え？マヤがどうして…",
  ui_story_5089_50891400_203_dialog_content = "…ってマヤじゃない！？どうしてアクリュスさんが！？",
  ui_story_5089_50891400_204_dialog_content = "…私の後ろにいる。",
  ui_story_5089_50891400_205_dialog_content = "ナビちゃんが旅に出ちゃうって聞いたから、\n急いできたんだよ！",
  ui_story_5089_50891400_206_dialog_content = "でも道を忘れっちゃって、\nこの優しいお兄ちゃんが連れてきてくれたの。",
  ui_story_5089_50891400_207_dialog_content = "それで君の所に行っても、会えなかったんだね…",
  ui_story_5089_50891400_208_dialog_content = "そんな勝手に出歩いちゃ、ジェノやエルビスが心配するよ。",
  ui_story_5089_50891400_209_dialog_content = "コホン。",
  ui_story_5089_50891400_210_dialog_content = "ええっと…「エルビー」が心配するよ。",
  ui_story_5089_50891400_211_dialog_content = "「エルビス」さんだよ。",
  ui_story_5089_50891400_212_dialog_content = "ゴホ、ゴホゴホッ！",
  ui_story_5089_50891400_213_dialog_content = "心は決まったのか？",
  ui_story_5089_50891400_214_dialog_content = "本当にここを離れるのか。我々の助けもいらない、と？",
  ui_story_5089_50891400_215_dialog_content = "はい、もう決めたんです。\nいつまでも皆に頼ってばかりじゃいられません。",
  ui_story_5089_50891400_216_dialog_content = "…",
  ui_story_5089_50891400_217_dialog_content = "アクリュスさんたちはもう新しい未来を歩み始めてます…",
  ui_story_5089_50891400_218_dialog_content = "この先皆さんの望んでた暮らしが待ってることを願ってます。",
  ui_story_5089_50891400_219_dialog_content = "「君と共にあること」を望んでいる者がいたとしたら、どうするのだ？",
  ui_story_5089_50891400_220_dialog_content = "え？それは…",
  ui_story_5089_50891400_221_dialog_content = "君が我々に選択の権利を与えた。\nならば、我々の考えや想いも大切にしてほしい。",
  ui_story_5089_50891400_222_dialog_content = "君が去ることを望まぬ者もいる。",
  ui_story_5089_50891400_223_dialog_content = "君と旅に出ることをあきらめられぬ者もいる。",
  ui_story_5089_50891400_224_dialog_content = "そういう者たちがすぐ近くにいることだろう。",
  ui_story_5089_50891400_225_dialog_content = "そう…君の巨像に乗せきれんほどにな。",
  ui_story_5089_50891400_226_dialog_content = "そ、そうでしょうか？",
  ui_story_5089_50891400_227_dialog_content = "だったらマヤも行く。",
  ui_story_5089_50891400_228_dialog_content = "乗り切れないなら、マヤ、ご先祖様に頼むもん。",
  ui_story_5089_50891400_229_dialog_content = "でも、水族館はどうするの？",
  ui_story_5089_50891400_230_dialog_content = "あ…ああああっ！！",
  ui_story_5089_50891400_231_dialog_content = "ナビちゃんのこと考えてたら、水族館のこと忘れちゃった！",
  ui_story_5089_50891400_232_dialog_content = "う～ん…",
  ui_story_5089_50891400_233_dialog_content = "マヤ、無理しないで。",
  ui_story_5089_50891400_234_dialog_content = "そんな簡単に決められることじゃない。",
  ui_story_5089_50891400_235_dialog_content = "それに急いで決めなくていいんだよ。\n一緒に来なくても、君が僕のこと嫌いなんだとか思わないから。",
  ui_story_5089_50891400_236_dialog_content = "ほんとに？",
  ui_story_5089_50891400_237_dialog_content = "本当だよ。",
  ui_story_5089_50891400_238_dialog_content = "じゃ…マヤ、水族館で待ってる。",
  ui_story_5089_50891400_239_dialog_content = "うん、約束だよ。",
  ui_story_5089_50891400_240_dialog_content = "よかった！じゃ、マヤは戻ってジェノお兄ちゃんとエルビスさんに伝えるね！",
  ui_story_5089_50891400_241_dialog_content = "ゴホッ、ゴホゴホ――",
  ui_story_5089_50891400_242_dialog_content = "どうやら君も分かったようだな。",
  ui_story_5089_50891400_243_dialog_content = "「別れ」の時がくれば、共にはいられない。",
  ui_story_5089_50891400_244_dialog_content = "だが、「別れ」は永遠ではない。",
  ui_story_5089_50891400_245_dialog_content = "再び戻る希望があるのなら、「別れ」を重く考える必要はない。",
  ui_story_5089_50891400_246_dialog_content = "「別れ」の言葉を無理やり絞り出す必要もない。",
  ui_story_5089_50891400_247_dialog_content = "君の物語はこれからも続いて行く。",
  ui_story_5089_50891400_248_dialog_content = "君は君の道を選べ。\nその物語を己の思う素晴らしい結末へと導くのだ。",
  ui_story_5089_50891400_249_dialog_content = "アクリュスさん…",
  ui_story_5089_50891400_250_dialog_content = "では、また会おう。PlayerName。",
  ui_story_5089_50891400_251_dialog_content = "「空の末裔」よ、さらに広く高い空へと向かってゆけ。",
  ui_story_5089_50891400_252_dialog_content = "…",
  ui_story_5089_50891400_253_dialog_content = "…",
  ui_story_5089_50891400_254_dialog_content = "カレン、僕は…",
  ui_story_5089_50891400_255_dialog_content = "ソラヴァンが来たわ。",
  ui_story_5089_50891400_256_dialog_content = "出発の時間が来たのでしょう？",
  ui_story_5089_50891400_257_dialog_content = "うん。",
  ui_story_5089_50891400_258_dialog_content = "…なんか、あの時みたいだね。",
  ui_story_5089_50891400_259_dialog_content = "ソラヴァンと僕、それからカレンとバイスがいて、\nこうして白夜城で…",
  ui_story_5089_50891400_260_dialog_content = "…",
  ui_story_5089_50891400_261_dialog_content = "さよう…",
  ui_story_5089_50891400_262_dialog_content = "一緒に行こう、カレン。",
  ui_story_5089_50891400_263_dialog_content = "あの時のように？",
  ui_story_5089_50891400_264_dialog_content = "うん、あの時みたいに。",
  ui_story_5089_50891400_265_dialog_content = "…",
  ui_story_5089_50891400_266_dialog_content = "行きましょう、PlayerName！",
  ui_story_5089_50891400_267_dialog_content = "遅いわ、PlayerName。",
  ui_story_5089_50891400_268_dialog_content = "もうっ、1人で大変だったんだから。",
  ui_story_5089_50891400_269_dialog_content = "バイス、私…",
  ui_story_5089_50891400_270_dialog_content = "きっと来るって思ってたわ。",
  ui_story_5089_50891400_271_dialog_content = "ただ、こんなにかかるとは思わなかったけどね。",
  ui_story_5089_50891400_272_dialog_content = "今さらだけど、急に一緒に来てなんて、ごめんね…",
  ui_story_5089_50891400_273_dialog_content = "あら、私もそうでしょ？",
  ui_story_5089_50891400_274_dialog_content = "まったく…長い付き合いなのに、そんな他人行儀はよしてよ。",
  ui_story_5089_50891400_275_dialog_content = "かえって傷ついちゃうじゃない。",
  ui_story_5089_50891400_276_dialog_content = "えっ…",
  ui_story_5089_50891400_277_dialog_content = "他に何か手伝うことはあるかしら？",
  ui_story_5089_50891400_278_dialog_content = "大丈夫よ。あとは目的地を設定するだけ。",
  ui_story_5089_50891400_279_dialog_content = "目的地は…この前見つけた「幻想の地」だったわよね？",
  ui_story_5089_50891400_280_dialog_content = "うん。僕を呼んでた、バイスの記憶の欠片が飛んでいったあの裂け目だよ。",
  ui_story_5089_50891400_281_dialog_content = "ミジャードやビクトリア、聖女様に確認してもらったんだ。\nあの裂け目の向こうにはもう一つの世界が広がってる。",
  ui_story_5089_50891400_282_dialog_content = "その向こう側の世界はN物質が暴走する世界だと聞いたわ。",
  ui_story_5089_50891400_283_dialog_content = "うん、超現実的な世界…虚構を意味するX物質がほぼ計測されないんだ。",
  ui_story_5089_50891400_284_dialog_content = "そこは安全かもしれないけど、謎も多い。",
  ui_story_5089_50891400_285_dialog_content = "だから、他の人を巻き込むわけにはいかない。",
  ui_story_5089_50891400_286_dialog_content = "…あ、違う…皆「他の人」なんかじゃない。",
  ui_story_5089_50891400_287_dialog_content = "ねえ、そういえば、どうして「幻想の地」と呼ばれてるの？",
  ui_story_5089_50891400_288_dialog_content = "うーん…最後の最後に、ベツレヘムさんが言ってたんだけど――",
  ui_story_5089_50891400_289_dialog_content = "僕たちのいる世界と比べた時、実は向こうの世界の方が現実なのかもしれないって…",
  ui_story_5089_50891400_290_dialog_content = "だが同時にアストラと不思議な、断ち切ることのできない繋がりをもっている。",
  ui_story_5089_50891400_291_dialog_content = "よってバイスの記憶が流れ込んだのだろう。\n空の末裔の求める真相もそこにある。",
  ui_story_5089_50891400_292_dialog_content = "そして、その現実の中にも虚構が存在するかもしれぬ。",
  ui_story_5089_50891400_293_dialog_content = "つまり「現実」の世界でも、人々は美しい「幻想」を見ているということだ。",
  ui_story_5089_50891400_294_dialog_content = "「彼ら」が虚構の中に託した思いが、我々の世界と彼らの世界とをつなげたのだろう。",
  ui_story_5089_50891400_295_dialog_content = "…でも僕たちはその幻想を終わらせに行くわけじゃないし――",
  ui_story_5089_50891400_296_dialog_content = "より完全な「現実」を受け入れなきゃいけないわけでもない。",
  ui_story_5089_50891400_297_dialog_content = "ただ新しい旅の未知の中で、僕たちの思いがつなぐ「美しい夢」を見つけに行くんだ。",
  ui_story_5089_50891400_298_dialog_content = "現実の中であろうと、いつか必ず見つけられるって信じてる。",
  ui_story_5089_50891400_299_dialog_content = "そうしたらまた、アストラに帰ってこよう！",
  ui_story_5089_50891400_300_dialog_content = "私には難しいことはよく分からないけど…",
  ui_story_5089_50891400_301_dialog_content = "こうして一緒に旅に出られて、本当にうれしいわ。",
  ui_story_5089_50891400_302_dialog_content = "私もよ。",
  ui_story_5089_50891400_303_dialog_content = "台詞は少ないですが、私がいることも忘れないでください。",
  ui_story_5089_50891400_304_dialog_content = "忘れるわけないでしょ？",
  ui_story_5089_50891400_305_dialog_content = "そうだよ。君を連れ戻すために、どれだけ苦労したと思ってるの！？",
  ui_story_5089_50891400_306_dialog_content = "それでは、座標を設定してください。",
  ui_story_5089_50891400_307_dialog_content = "バイス。",
  ui_story_5089_50891400_308_dialog_content = "カレン、一緒に弾かない？",
  ui_story_5089_50891400_309_dialog_content = "ピアノは、弾けけないわ…",
  ui_story_5089_50891400_310_dialog_content = "構わないわよ。ほんの少し想像すればいいの。",
  ui_story_5089_50891400_311_dialog_content = "そうだよ、カレン。君は気持ちさえ込めてくれれば、\nあとは僕とバイスが導いてあげる。",
  ui_story_5089_50891400_312_dialog_content = "…分かったわ。",
  ui_story_5089_50891400_313_dialog_content = "なら…",
  ui_story_5089_50891400_314_dialog_content = "行きましょう！",
  ui_story_5089_50891400_315_dialog_content = "またね、アストラ。",
  ui_story_5089_50891400_316_dialog_content = "一緒に美しい夢を見てきた皆、またね。",
  ui_story_5089_50891400_317_dialog_content = "さよなら。",
  ui_story_5089_50891400_318_dialog_content = "END",
  ui_story_5089_50891400_319_dialog_content = "ありがとうございました"
}
return config
